window.BOOKS=window.BOOKS||{};window.BOOKS["GaoZhong_3"]=[["cancel","/ˈkænsl/","vt.","取消","Our flight was cancelled.","我们的航班取消了。"],["prepare","/prɪˈpɛr/","v.","准备； 配制","The prosecution wanted more time to prepare their case.","原告想要有更多的时间来准备诉讼。"],["govern","/ˈɡʌvɚn/","v.","统治； 管理","the leaders who govern the country","治理这个国家的领导人"],["surgeon","/ˈsɝdʒən/","n.","外科医生","...a heart surgeon.","…一位心脏外科医生。"],["analyse","/ˈæn(ə)laɪz/","vt.","分析； 研究","She still needs to analyse the data.","她仍需要分析这些数据。"],["abrupt","/əˈbrʌpt/","adj.","突然的， 意外的","an abrupt change of plan","计划的突然改变"],["resemble","/rɪˈzɛmbl/","vt.","像， 类似","It’s amazing how closely Brian and Steve resemble each other.","布赖恩和史蒂夫真是惊人地相像。"],["discourage","/dɪsˈkɝɪdʒ/","vt.","使气馁， 打消","It may be difficult to do at first. Don't let this discourage you.","开始时做起来也许比较困难。不要让这个泄你的气。"],["hall","/hɔl/","n.","大厅， 礼堂； 门厅， 过道","Each floor had ten rooms on both sides of the hall.","每一层在走廊的两边都各有十个房间。"],["pollution","/pəˈluʃən/","n.","污染","California’s tough anti-pollution laws","加利福尼亚州严厉的反污染法"],["remote","/rɪˈmot/","adj.","遥远的","a remote border town","一个偏远的边境小镇"],["explanation","/ˌekspləˈneɪʃn/","n.","解释， 说明","She told the court she would give a full explanation of the prosecution's decision on Monday.","她告诉法庭她将在星期一就控方的决定做出详尽的解释。"],["cafeteria","/ˌkæfəˈtɪəriə/","n.","自助餐厅","the school cafeteria","学校餐厅"],["salary","/ˈsæləri/","n.","工资， 薪水","The average salary for a teacher is $39,000 a year.","教师的平均工资是39,000美元一年。"],["pretend","/prɪˈtɛnd/","v.","假装， 装作","Let’s pretend we’re on the moon.","我们假装自己是在月球上吧。"],["youth","/jʊθ/","n.","青春； 青年","Despite his youth, he had travelled alone.","他虽然年纪还小，却已独自旅行过了。"],["without","/wɪðˈaʊt/","prep.","没有， 不","After the storm we were without electricity for five days.","暴风雨之后我们断电了五天。"],["drunk","/drʌŋk/","adj.","醉的","You’re drunk.","你喝醉了。"],["would","/wʊd/","modal verb.","将，将会〔表示想做某事或认为某事会发生〕","They said they would meet us at 10.30 at the station.","他们说过会在10点30分到车站接我们。"],["pick","/pɪk/","v.","拾起， 采集； 挑选","Students have to pick three courses from a list of 15.","学生必须从15门课中选修3门。"],["customs","/ˈkʌstəmz/","n.","海关； 关税","What right does Customs have to search my car?","海关有什么权力搜查我的车？"],["calculate","/ˈkælkjulet/","v.","计算， 核算","These instruments calculate distances precisely.","这些仪器计算距离非常精确。"],["energy","/ˈɛnɚdʒi/","n.","精力； 能量","The water is heated using energy from the sun.","水是利用太阳能加热的。"],["audience","/ˈɔdɪəns/","n.","观众， 听众","The audience began clapping and cheering.","观众开始鼓掌欢呼。"],["solid","/ˈsɑlɪd/","adj/n.","结实的，固体的；固体","The lake was frozen solid .","湖水冻得结结实实。"],["thus","/ðʌs/","adv.","这样； 因而","Most of the evidence was destroyed in the fire. Thus it would be almost impossible to prove him guilty.","大多数证据已在大火中烧毁，因而要证明他有罪几乎是不可能的。"],["meanwhile","/ˈminwaɪl/","adv.","同时","Cook the sauce over a medium heat until it thickens. Meanwhile start boiling the water for the pasta.","用中火把调味汁煮到变稠，同时烧水准备煮意大利面。"],["sniff","/snɪf/","v.","用力吸； 嗅， 闻","He opened the milk and sniffed it.","他打开牛奶闻了闻。"],["possess","/pəˈzɛs/","vt.","占有， 拥有","Different workers possess different skills.","不同的工人拥有不同技能。"],["require","/rɪˈkwaɪr/","vt.","需求； 要求","Campbell’s broken leg will probably require surgery.","坎贝尔的一条腿骨折，可能需要手术。"],["optional","/ˈɑpʃənl/","adj.","可选择的； 随意的","three optional courses","三门选修课"],["scratch","/skrætʃ/","v/n.","抓，划破；乱涂；乱写； 抓痕","John yawned and scratched his leg.","约翰打了个呵欠，挠了挠腿。"],["analysis","/əˈnæləsɪs/","n.","分析； 解析","She’s been in analysis for three years.","她接受精神分析治疗已经三年了。"],["click","/klɪk/","v/n.","点击；发出滴答声；滴答声","The door clicked shut behind me.","门在我身后咔嗒一声关上了。"],["apparent","/əˈpærənt/","adj.","明显的， 清楚的","The difference in quality was immediately apparent .","质量的差异显而易见。"],["journalist","/ˈdʒɝ​nlɪst/","n.","记者， 新闻工作者","a well-known journalist and broadcaster","一位著名的新闻记者兼播音员"],["left","/lɛft/","adv/adj/n.","向左边，在左边；左边的；左， 左边","Turn left just after the school.","过了那所学校马上左转。"],["dawn","/dɔn/","n.","黎明， 拂晓","When dawn broke (= the first light of the day appeared ) , we were still 50 miles from Calcutta.","破晓的时候，我们离加尔各答还有50英里。"],["sideways","/ˈsaɪdwez/","adj.","斜向一边的","Alfred shot him a sideways glance.","艾尔弗雷德斜着眼看了他一下。"],["object","/ˈɑbdʒɛkt/","v/n.","反对；物体； 目标； 宾语","If no one objects, I would like Mrs Harrison to be present.","如果没人反对的话，我想请哈里森夫人出席。"],["harbour","/hɑrbɚ/","n.","港口","as they sailed into Portsmouth Harbour","当他们驶入朴次茅斯港的时候"],["chapter","/ˈtʃæptɚ/","n.","章","Read Chapter 11 as your homework.","家庭作业是阅读第 11 章。"],["accessible","/əkˈsɛsəbl/","adj.","可使用的； 可进入的； 易接近的","The island is only accessible by boat.","这个岛只有坐船才能到。"],["flight","/flaɪt/","n.","飞行； 航班； 楼梯的一段","He immediately booked a flight to Toulouse.","他当即就订了去图卢兹的航班。"],["hang","/hæŋ/","v.","悬挂； 装饰； 绞死","If he is found guilty, he will almost certainly hang.","如果被判有罪，他几乎肯定会被处以绞刑。"],["role","/rol/","n.","[Ｃ] 角色； 作用","",""],["independent","/ˈɪndɪˈpɛndənt/","adj.","独立的， 有主见的","There are plans to split the corporation into a number of smaller independent companies.","有计划要把这家大企业分割成一些独立的小公司。"],["carriage","/ˈkærɪdʒ/","n.","四轮马车；  客车厢","The president-elect followed in an open carriage drawn by six beautiful grey horses.","新当选的总统紧随其后，坐着6匹灰色骏马开道的敞篷马车。"],["defence","/diˈfens/","n.","防御； 防护； 辩护","The land was flat, giving no scope for defence.","土地非常平坦，无法做防卫之用。"],["achieve","/əˈtʃiv/","vt.","达到， 取得","Frances achieved very good exam results.","弗朗西丝考试取得了优异成绩。"],["ahead","/əˈhɛd/","adv.","在前， 向前","He kept his gaze fixed on the car ahead.","他的目光一直盯着前面的那辆汽车。"],["anybody","/ˈɛnɪbɑdi/","pron.","任何人， 无论谁","She swore me not to tell anybody about my secret.","她向我发誓不把我的秘密告诉任何人。"],["roll","/rol/","v/n.","滚动,打滚；面包圈； 卷状物","He rolled his shoulders back.","他转动双肩。"],["turn","/tɝn/","v/n.","旋转；转变；转弯；轮流","Ricky turned and walked away.","里基转身走了。"],["elect","/ɪˈlɛkt/","vt.","选举","the country’s first democratically elected government","该国第一个民主选举产生的政府"],["example","/ɪgˈzæmpl/","n.","例子， 范例","Many countries, for example Mexico and Japan, have a lot of earthquakes.","许多国家，例如墨西哥和日本，经常发生地震。"],["result","/rɪˈzʌlt/","n.","结果， 效果","High unemployment is a direct result of the recession.","高失业率是经济衰退的直接后果。"],["same","/sem/","adj/n.","同样的， 同一的；同样的事","Her perfume has always had the same effect on me.","她身上的香水给我的感觉一如既往。"],["selfish","/ˈsɛlfɪʃ/","adj.","自私的","How can you be so selfish?","你怎能这样自私？"],["after","/ˈæftɚ/","prep&conj&adv.","在…之后， 后来","After the war many soldiers stayed in France.","战后，许多士兵留在法国。"],["headline","/ˈhɛdlaɪn/","n.","标题；","a paper carrying the front-page headline: ‘Space Aliens meet with President’","头版报道题为“天外来客会见总统”的报纸"],["connect","/kəˈnɛkt/","vt.","连接， 把…联系起来","We’d like two rooms with connecting doors (= doors that join the rooms ) .","我们想要两个有门相通的房间。"],["hand","/hænd/","n/vt.","手；指针；交付； 传递","Steve gripped the steering wheel tightly with both hands.","史蒂夫双手紧握方向盘。"],["merciful","/ˈmɝsɪfl/","adj.","仁慈的； 宽大的","Merciful God, save us.","仁慈的上帝，救救我们吧。"],["rebuild","/ˌriːˈbɪld/","vt.","重建","The church was completely rebuilt in the last century.","这座教堂在上个世纪全面重建。"],["sharpen","/ˈʃɑrpən/","v.","变锐利， 削尖","Anne sharpened her pencil and got out her homework.","安妮把铅笔削尖，然后拿出家庭作业来。"],["committee","/kəˈmɪti/","n.","委员会","a committee meeting","委员会会议"],["address","/əˈdrɛs/","n.","地址","What’s your new address?","你的新地址是什么？"],["union","/ˈjunɪən/","n.","联合， 联盟","the British Golf Union","英国高尔夫球协会"],["straight","/stret/","adj&adv.","直的","She was looking straight at me.","她直直地看着我。"],["wipe","/waɪp/","vt.","擦； 扫","I'll just wipe the table.","我只擦擦桌子。"],["sale","/sel/","n.","卖， 出售","Harvey gets a $50 commission every time he makes a sale (= sells something as part of his job ) .","哈维每做成一笔生意可得到50美元的佣金。"],["component","/kəmˈponənt/","n.","成分； 零部件","companies that make electronic components for computer products","为计算机产品生产电子零件的公司"],["suite","/sut/","n.","套， 组； 套间","a honeymoon suite","蜜月套房"],["consultant","/kənˈsʌltənt/","n.","顾问； 会诊医师","a management consultant","管理顾问"],["outdoors","/ˈaʊtˈdɔrz/","adv/n.","户外的，野外的；户外","It’s warm enough to eat outdoors tonight.","今晚很暖和，可以在户外用餐。"],["throw","/θro/","v.","投， 掷， 扔","He spent hours throwing a tennis ball against a wall.","他花了数小时对着一堵墙扔网球。"],["obvious","/ˈɑbvɪəs/","adj.","明显的， 显而易见的","The obvious way of reducing pollution is to use cars less.","减少污染显而易见的办法就是少用汽车。"],["arch","/ɑrtʃ/","n.","拱门； 拱形","When she passed under the arch leading out of the park, Mira whooped with delight.","从通向公园外的拱门下走过时，米拉高兴地喊叫起来。"],["discuss","/dɪˈskʌs/","v.","讨论， 议论","Littman refused to discuss the case publicly.","利特曼拒绝公开讨论此案。"],["standard","/ˈstændɚd/","adj/n.","标准的；标准，规格","We paid them the standard rate.","我们付给他们标准工资。"],["violent","/ˈvaɪələnt/","adj.","暴力的； 猛烈的","the increase in violent crime","暴力犯罪的增多"],["harmony","/ˈhɑrməni/","n.","协调， 融洽","I do believe it is possible for different ethnic groups to live together in harmony.","我确信不同民族的人民可以融洽相处。"],["correct","/kəˈrɛkt/","adj/vt.","正确的， 对的； 恰当的；改正；纠正","If my calculations are correct, we’re about ten miles from Exeter.","如果我计算得没错的话，我们离埃克塞特大约十英里。"],["empty","/ˈɛmptɪ/","adj/vt.","空的；倒空","an empty box","空盒子"],["wish","/wɪʃ/","n&v.","祝愿； 想要","If you wish to discuss this matter further please do not hesitate to contact me.","如果你想进一步讨论此事，请尽管和我联系。"],["institution","/ˌɪnstɪˈtjuːʃn/","n.","公共机构； 协会","powerful institutions such as world banks","诸如世界银行之类的强大机构"],["tie","/taɪ/","v/n.","系，拴，扎；关系； 领带； 绳子， 结","The flat is tied to the job.","这套公寓是为这个职位配的。"],["wise","/waɪz/","adj.","聪明的， 明智的","a wise precaution","明智的预防措施"],["ambition","/æmˈbɪʃən/","n.","雄心， 野心","He was young and full of ambition.","他年轻，而且雄心勃勃。"],["tin","/tɪn/","n.","罐头","a sardine tin","沙丁鱼罐头"],["enlarge","/ɪnˈlɑrdʒ/","v.","扩大， 放大","an operation to enlarge her breasts","她的丰胸手术"],["besides","/bɪˈsaɪdz/","adv/prep.","此外； 再说；除…以外","I need the money. And besides, when I agree to do something, I do it.","我需要这笔钱，而且，我一旦答应做什么事情就会做到。"],["serious","/ˈsɪrɪəs/","adj.","严肃的， 严重的； 认真的","the serious problem of unemployment","严重的失业问题"],["tip","/tɪp/","vt/n.","告诫，提示；给小费；顶端； 小费； 提示","Did you tip the waiter?","你给侍应生小费了吗？"],["export","/ˈekspɔːrt；ɪkˈ-/","vi/vt/n.","出口；输出","Italian food has been exported all over the world.","意大利食品已传遍世界。"],["conversation","/ˌkɒnvəˈseɪʃn/","n.","谈话， 交谈","a telephone conversation","电话交谈"],["laugh","/læf/","vi/n.","笑， 大笑；笑，大笑，笑声；嘲笑","Maria looked at him and laughed.","玛丽亚看着他大笑起来。"],["murder","/ˈmɝdɚ/","n&v.","谋杀","On the night the murder was committed , he was out of the country.","凶案发生当晚他不在国内。"],["fantasy","/ˈfæntəsi/","n.","幻想， 白日梦","I used to have fantasies about living in Paris with an artist.","我过去常幻想着在巴黎与一位艺术家同住。"],["pay","/pe/","v/n.","付钱，给…报酬；工资","How would you like to pay?","你想怎么付款？"],["check","/tʃɛk/","v/n.","核对；检查；批改；检查； 批改","Check the tiles carefully before you buy them.","购买之前要把瓷砖仔细检查一下。"],["list","/lɪst/","n/vt.","一览表，清单；列表","We are making a list of the top ten men we would not want to be married to.","我们正在列一个我们最不想嫁的10种男人的名单。"],["strange","/strendʒ/","adj.","奇怪的， 奇特的； 陌生的","strange noises","奇怪的噪声"],["lack","/læk/","n&v.","缺乏， 缺少","Too many teachers are treated with a lack of respect.","有太多老师得不到尊重。"],["toast","/tost/","vt/n.","向…敬酒；烘，烤；烤面包， 吐司； 祝酒， 祝酒词","I toasted the cheese sandwiches.","我烤了干酪三明治。"],["aside","/əˈsaɪd/","adv.","在旁边","He pushed his half-eaten salad aside and left.","他推开吃了一半的色拉走了。"],["circumstance","/ˈsɝ​kəmˌstəns/","n.","环境； 情况","The Soviet Union had been forced by circumstances to sign a pact with Nazi Germany.","苏联为形势所迫同纳粹德国签订了一项条约。"],["success","/səkˈsɛs/","n.","成功， 成就； 成功的人","The experiment was a big success.","实验非常成功。"],["brunch","/brʌntʃ/","n.","早午饭","And then I have brunch.","然后我就开始吃早午餐。"],["authority","/əˈθɔrəti/","n.","权威； 当局","an agreement between the US and Colombian authorities","美国和哥伦比亚当局的一份协议"],["creature","/ˈkritʃɚ/","n.","生物； 动物","all the living creatures in the sea","海洋中所有的生物"],["outgoing","/ˈaʊtˈgoɪŋ/","adj.","好交际的， 外向的； 即将离职的","We’re looking for someone with an outgoing personality.","我们在找一个性格外向的人。"],["tasteless","/ˈtestləs/","adj.","无滋味的","...a house crammed with tasteless furniture.","…一座塞满了毫无品位的家具的房子。"],["harm","/hɑrm/","n&vt.","伤害， 损伤","The scandal did his career a lot of harm.","丑闻对他的职业生涯造成很大损害。"],["instrument","/ˈɪnstrəmənt/","n.","乐器； 工具， 器械","surgical instruments","外科(手术)器械"],["medium","/ˈmidɪəm/","adj/n.","中间的，中等的；媒介","What size shirt does he wear – small, medium or large?","他穿多大尺码的衬衫——小号、中号还是大号？"],["remove","/rɪˈmuv/","vt.","移动， 拿走； 去除","Remove the old wallpaper and fill any holes in the walls.","撕下旧墙纸，把墙上的洞都填平。"],["wisdom","/ˈwɪzdəm/","n.","智慧","a man of great wisdom","一个有大智慧的男人"],["starvation","/stɑrˈveʃən/","n.","饥饿； 饿死","people dying of starvation","快饿死的人们"],["nowhere","/ˈnoˈwɛr/","adv.","任何地方都不； 无处","Nowhere is drug abuse more of a problem than in the US.","没有什么地方的吸毒问题比美国更严重。"],["psychology","/saɪˈkɑlədʒi/","n.","心理学","the psychology of three-year-olds","三岁孩子的思想"],["wrestle","/ˈrɛsl/","v.","摔跤， 格斗； 斟酌","Police officers wrestled him to the ground .","警察把他扑倒在地。"],["treasure","/ˈtrɛʒɚ/","n.","金银财宝， 财富","The Book of Kells is Trinity College’s greatest treasure.","《凯尔经》是三一学院的镇院之宝。"],["multiply","/ˈmʌltɪplaɪ/","v.","相乘； 增加","The amount of information available has multiplied.","可获得的信息大大增加了。"],["live","/laɪv；lɪv/","vi/adj/vt.","生活，居住；活的； 直播的；过着，经历","He lives just across the street from me.","他就住在我街对面。"],["approval","/əˈpruvl/","n.","赞成； 认可； 批准","The president has already given his approval to the plan.","总统已经批准了这个计划。"],["victory","/ˈvɪktəri/","n.","[C] 胜利","Union leaders are heading for victory in their battle over workplace rights.","工会领袖们在争取工作场所权利的斗争中正迈向胜利。"],["mobile","/ˈməʊbl/","adj.","活动的， 可移动的","mobile air-conditioners","移动式空调器"],["perform","/pɚˈfɔrm/","v.","表演， 表现； 履行","Chenier and the band are performing at the Silver Palace tomorrow.","车尼尔和乐队明天将在银宫演出。"],["evolution","/ˌɛvəˈluʃən/","n.","进展， 演变， 进化","the theory of evolution","进化论"],["expose","/ɪkˈspoz；ek-/","vt.","暴露； 揭露","He lifted his T-shirt to expose a jagged scar across his chest.","他撩起T恤衫，露出横贯胸部的锯齿状伤疤。"],["concentrate","/ˈkɑnsnˈtret/","v.","集中， 聚集","Now please concentrate.","现在请集中注意力。"],["cheer","/tʃɪr/","n&v.","欢呼， 喝彩","A great cheer went up from the crowd.","人群中爆发出巨大的欢呼声。"],["with","/wɪð/","prep.","与， 伴随； 有， 以","Her boots were covered with mud.","她的靴子上满是污泥。"],["there","/ðɛr/","adv/int.","在那里；那！你瞧！","We could go back to my cottage and have lunch there.","我们可以回到我的小屋去吃午饭。"],["permit","/pɚˈmɪt/","v/n.","许可，允许；许可证， 执照","Smoking is only permitted in the public lounge.","只允许在公共休息室里抽烟。"],["well","/wɛl/","adv/adj/int.","好，充分地；健康的；好吧","Mix the flour and butter well.","把面粉和黄油搅匀。"],["suitable","/ˈsutəbl/","adj.","合适的， 适宜的","We are hoping to find a suitable school.","我们希望能找到一所合适的学校。"],["personnel","/ˌpɜːsəˈnel/","n.","人员， 职员","All personnel are to receive security badges.","所有人员都将拿到安保徽章。"],["hopeless","/ˈhoʊpləs/","adj.","没有希望的； 不可救药的","We tried to stop the flames from spreading, but we knew it was hopeless.","我们试图阻止火势蔓延，但我们知道这是不可能的。"],["freeway","/ˈfriwe/","n.","高速公路","the Central Freeway","中央高速公路"],["fountain","/ˈfaʊntn/","n.","喷泉； 源泉","He was a fountain of information on Asian affairs.","他是亚洲事务的信息源。"],["pile","/paɪl/","v/n.","堆积，积累；堆","Ma stacked the cups and piled the plates.","妈妈把杯盘堆叠起来。"],["channel","/ˈtʃænl/","n.","海峡； 频道； 通道","the news on Channel 4","第四频道播出的新闻"],["sunburnt","/ˈsʌn/","adj.","晒黑的， 晒伤的","She woke him anxiously shaking at his sunburnt shoulders.","她焦急地摇着他被太阳晒黑的肩膀，唤醒了他。"],["focus","/ˈfokəs/","v/n.","聚焦，集中；中心， 焦点","His eyes were focussed straight ahead.","他的双眼盯着正前方。"],["entire","/ɪnˈtaɪɚ/","adj.","整个的， 全部的","It was the worst day in my entire life.","那是我一生中最糟糕的一天。"],["approach","/əˈprotʃ/","v/n.","接近， 靠近；方式，方法","As I approached the house, I noticed a light on upstairs.","我走近那幢房子的时候注意到楼上有灯光。"],["wrist","/rɪst/","n.","手腕， 腕关节","He broke his wrist climbing rocks for a cigarette ad.","他为了一个香烟广告攀岩折断了手腕。"],["experiment","/ɪkˈsperɪmənt/","n.","实验","The astronauts are conducting a series of experiments to learn more about how the body adapts to weightlessness.","那些宇航员正在进行一系列实验，以便更多地了解人体如何适应失重状态。"],["fierce","/fɪrs/","adj.","猛烈的， 激烈的","fierce fighting in the city","城里的激烈战斗"],["reservation","/ˌrezəˈveɪʃn/","n.","预订； 预约","a dinner reservation","预订晚餐"],["e-mail","/ˈi/","n/vt.","电子邮件；给…发电子邮件","You can contact us by e-mail.","你可以通过电子邮件跟我们联系。"],["hate","/het/","vt/n.","恨，讨厌，不喜欢；怨恨","It’s the kind of movie you either love or hate.","这是那种你要么喜欢要么讨厌的电影。"],["block","/blɑk/","v/n.","阻塞， 阻挡；大块；街区","A fallen tree is blocking the road.","一棵倒下的树把路阻断了。"],["write","/raɪt/","v.","写","I wrote her several letters , but she didn’t reply.","我给她写了几封信，可是她没有回复。"],["pet","/pɛt/","n.","宠物， 爱畜","They have two pets – a cat and a dog.","他们有两只宠物，一只猫和一只狗。"],["flow","/flo/","v/n.","流动；流， 流动","Money has been flowing into the country from Western aid agencies.","资金源源不断地从西方援助机构流入该国。"],["order","/ˈɔrdɚ/","n/vt.","顺序；命令；命令； 点菜； 订货","There seemed to be no logical order to the sections.","这几部分似乎没有逻辑顺序。"],["wage","/wedʒ/","n.","工资， 报酬","He earns a good wage.","他工资挺高。"],["period","/ˈpɪrɪəd/","n.","时期， 时代","Tomorrow’s weather will be dry with sunny periods.","明天天气干燥，间或晴朗。"],["musical","/ˈmjuzɪkl/","adj/n.","音乐的，爱好音乐的；音乐剧","a musical version of the fairy tale ‘Cinderella’","童话故事《灰姑娘》的音乐剧版"],["corporation","/ˌkɔːpəˈreɪʃn/","n.","团体； 公司， 企业","He works for a large American corporation.","他在一家美国大公司工作。"],["distant","/ˈdɪstənt/","adj.","远的， 遥远的","the sound of distant gunfire","远处的炮火声"],["understand","/ˈʌndɚˈstænd/","v.","懂得， 理解","She doesn’t understand English.","她不懂英语。"],["dismiss","/dɪsˈmɪs/","v.","解雇； 解散","The class was dismissed early today.","今天这个班级提早放学。"],["intelligence","/ɪnˈtɛlɪdʒəns/","n.","智力， 聪明","To be good at the game, you need a reasonable level of intelligence.","要想把这种游戏玩好，需要一定的智力水平。"],["reform","/rɪˈfɔrm/","v/n.","改革， 革新；改革；改善","plans to radically reform the tax system","彻底改革税收制度的计划"],["ever","/ˈɛvɚ/","adv.","曾经； 无论何时","Have you ever seen anything like it?","你可曾见过像这样的东西？"],["even","/ˈivən/","adv/adj.","甚至，更加，还要；平坦的","Most companies have suffered a drop in their profits, even very large companies.","大多数公司的利润都出现下滑，甚至连很大的公司也不例外。"],["restriction","/rɪˈstrɪkʃən/","n.","限制","a 50 mph speed restriction","每小时50英里的限速"],["crazy","/ˈkrezi/","adj.","疯狂的","The neighbours must think we’re crazy.","邻居一定会认为我们疯了。"],["razor","/ˈrezɚ/","n.","剃须刀","an electric razor","电动剃须刀"],["coach","/kotʃ/","v/n.","指导，训练；教练； 马车； 长途车","Nigel coaches a cricket team in his spare time.","奈杰尔业余时间担任一个板球队的教练。"],["champion","/ˈtʃæmpɪən/","n.","冠军， 优胜者","...a former Olympic champion.","…一位前奥运冠军。"],["wait","/wet/","v/n.","等待；等待， 等候","Hurry up! Everyone’s waiting.","快点！大家在等着呢。"],["circuit","/ˈsɝkɪt/","n.","电路","We did a circuit of the old city.","我们绕着老城走了一圈。"],["pint","/paɪnt/","n.","品脱； 一品脱啤酒","He’s gone down the pub for a quick pint.","他去小酒馆匆匆喝上一品脱啤酒。"],["matter","/ˈmætɚ/","vi/n.","要紧， 有重大关系；事情，物质；原因","If I have to stay late at work tonight, it won’t matter because we can go out another night.","如果今晚我必须工作到很晚的话，那也没关系，我们可以改天晚上再出去。"],["instant","/ˈɪnstənt/","adj/n.","立即的；速食的；瞬间","an instant success","马到成功"],["personalization","/ˌpɜːsənəlaɪˈzeɪʃn/","n.","个性化","The method is applied in personalization information recommendation and achieves better effect.","将该方法用于个性化信息检索，取得较好的效果。"],["shaver","/ˈʃevɚ/","n.","电动剃须刀","He uses an electric shaver.","他使用电动剃须刀。"],["top","/tɑp/","n.","顶部； 上面","a low wooden table with a glass top","玻璃桌面的矮木桌"],["native","/ˈnetɪv/","adj.","本土的， 本国的","English is not the native language for almost half of our overseas visitors.","我们有差不多一半的海外游客母语不是英语。"],["too","/tu/","adv.","也； 又； 太； 很","She doesn’t seem too upset about it.","她对此好像不是很难过。"],["have","/həv/","v/vt.","帮助构成完成时态；有，使，令","Our guests have arrived.","我们的客人到了。"],["violence","/ˈvaɪələns/","n.","暴力； 强烈","There is too much sex and violence on TV these days.","如今电视上性爱和暴力场面太多。"],["roast","/rost/","v.","烤","Are you going to roast the chicken?","这鸡你是准备烤的吗？"],["energetic","/ˌenəˈdʒetɪk/","adj.","精力旺盛的","an energetic man","精力旺盛的男子"],["consequence","/ˈkɑnsəkwɛns/","n.","结果， 后果","Her lawyer said she understood the consequences of her actions and was prepared to go to jail.","她的律师说她明白自己行为的后果并准备去坐牢。"],["quilt","/kwɪlt/","n.","加衬芯床罩","",""],["famous","/ˈfeməs/","adj.","著名的， 出名的","a famous actor","著名演员"],["question","/ˈkwɛstʃən/","vt/n.","询问；问题","Two men have been arrested and questioned.","已有两名男子被捕并受到盘问。"],["vinegar","/ˈvɪnɪɡɚ/","n.","醋","With vinegar and brown paper.","用醋和棕色纸张包扎。"],["spirit","/ˈspɪrɪt/","n.","精神， 灵魂","Although Laurie is dead, I can feel his spirit with me.","劳里虽然已经过世，但我还能感觉到他的灵魂和我在一起。"],["premier","/prɪˈmɪr/","n.","总理， 首相","the Irish Premier","爱尔兰总理"],["produce","/prəˈdus/","v.","生产， 制造","New drugs are producing remarkable results .","新药正在产生显著的效果。"],["allergic","/əˈlɝdʒɪk/","adj.","过敏的","an allergic reaction to nuts","对坚果的过敏性反应"],["cheat","/tʃit/","v/n.","哄骗，欺骗，骗取；骗子； 诈骗","He had cheated in the test by using a calculator.","他在考试时作弊，用了计算器。"],["framework","/ˈfremwɝk/","n.","框架， 结构","We have to act within the existing legal framework.","我们必须在现行的法律框架下行事。"],["regard","/rɪˈɡɑrd/","v/n.","当做，看待；关心， 注意； 致意","He was regarded as the most successful president of modern times.","他被看成是近代最成功的总统。"],["anecdote","/ˈænɪkdot/","n.","轶事； 趣事","The book is full of amusing anecdotes about his life in Japan.","这本书里全是他在日本生活的趣闻轶事。"],["prohibit","/prəˈhɪbɪt/","vt.","禁止， 阻止","Smoking is strictly prohibited inside the factory.","厂区严禁吸烟。"],["almost","/ˈɔlmost/","adv.","几乎， 差不多","Have you almost finished?","你差不多完成了吗？"],["steward","/ˈstuɚd/","n.","男乘务员","They also claim that the security team elbowed aside a steward .","他们还声称保安人员将一位乘务员推搡至一边。"],["fuel","/ˈfjuəl/","n.","燃料","Coal is one of the cheapest fuels.","煤是最廉价的燃料之一。"],["manner","/ˈmænɚ/","n.","方式；举止；","He felt some guilt over the manner of her death.","她以这种方式死去，他心里有些内疚。"],["upon","/əˈpɑn/","prep.","在…上面","an honour bestowed upon the association","授予该协会的荣誉"],["foresee","/fɔrˈsi/","vt.","预见， 预知","I’ve put your name on the list and I don’t foresee any problems.","我把你的名字写在名单上了，估计不会有什么问题。"],["harmful","/ˈhɑrmfəl/","adj.","有害的； 致伤的","the harmful effects of smoking","吸烟的害处"],["associate","/əˈsoʃɪet/","v.","结合； 结交","Through science we've got the idea of associating progress with the future.","通过科学我们已有了将进步与未来联系起来的观念。"],["pray","/pre/","v.","祈祷， 祈求","They went to the mosque to pray.","他们去清真寺祷告。"],["wake","/wek/","v.","醒来， 叫醒","When she woke, the sun was streaming through the windows.","她醒来时，阳光泻入窗内。"],["pin","/pɪn/","vt/n.","钉住，别住；别针； 胸针","They pinned a notice to the door.","他们把通知钉在门上。"],["academic","/ˌækəˈdemɪk/","adj/n.","学术的；院校的；大学教师； 学者","He possessed no academic qualifications.","他没有学历。"],["whether","/ˈwɛðɚ/","conj.","是否","Maurice asked me whether I needed any help.","莫里斯问我是否需要帮助。"],["function","/ˈfʌŋkʃən/","vi/n.","起作用； 行使职责；功能，作用，职责；函数","On weekdays, one third of the room functions as workspace.","在工作日，这个房间的三分之一充当工作场所。"],["raise","/rez/","vt.","举起； 提高， 使升高； 饲养， 养育","Can you raise the lamp so I can see?","你能把灯举高点好让我看清吗？"],["spoon","/spun/","n.","勺， 匙， 调羹","He stirred his coffee with a spoon.","他用匙搅了搅咖啡。"],["quite","/kwaɪt/","adv.","完全， 十分","I felt quite bitter about it at the time.","当时我对此感到相当痛苦。"],["lap","/læp/","n.","大腿；  一圈","Rubens Barrichello finished a lap ahead of his team-mate.","鲁本斯·巴里切罗领先队友一圈跑完全程。"],["mineral","/ˈmɪnərəl/","n.","矿物质， 矿物","The area is very rich in minerals .","该地区矿产非常丰富。"],["representative","/ˈrɛprɪˈzɛntətɪv/","n.","代表","a union representative","工会代表"],["terror","/ˈtɛrɚ/","n.","恐怖； 可怕的人","Death holds no terrors for (= does not frighten ) me.","死亡吓不倒我。"],["beneath","/bɪˈniːθ/","prep.","在…下方， 在…下面","Far beneath them, the trees of the forest sighed in the breeze.","远在他们的下方，森林中的树木在微风中悲泣。"],["everyone","/ˈɛvrɪwʌn/","pron.","每人， 人人","If everyone is ready, I’ll begin.","如果大家都准备好了，我就开始。"],["lay","/le/","v.","放， 搁； 产","John was laying the table.","约翰正在摆放餐具。"],["swap","/swɑp/","v.","交换","Do you want to swap umbrellas?","你想交换雨伞吗？"],["hatch","/hætʃ/","v.","孵蛋","The eggs take three days to hatch.","这些蛋要三天时间才能孵化。"],["pardon","/ˈpɑrdn/","vt&n.","原谅， 宽恕； 对不起","",""],["plenty","/ˈplɛnti/","n.","充足， 大量， 丰富","a land of plenty","一片富饶的土地"],["tick","/tɪk/","v/n.","发出滴答声；钟表的滴答声；记号","The old clock ticked noisily.","那只古老的钟大声地嘀嗒着。"],["basis","/ˈbesɪs/","n.","[C] 基础； 根据； 原则","Their claim had no basis in fact (=  it was not true  ) .","他们的说法没有事实根据。"],["adventure","/ədˈvɛntʃɚ/","n.","冒险； 奇遇","a great adventure","一大奇遇"],["condition","/kənˈdɪʃən/","n.","条件， 状况","Conditions in the prison were atrocious.","这座监狱的条件糟透了。"],["improve","/ɪmˈpruv/","v.","改进， 更新","a course for students wishing to improve their English","为想提高英语水平的学生开设的一门课"],["ceremony","/ˈsɛrəˌmoʊni/","n.","典礼， 仪式","a wedding ceremony","婚礼"],["bingo","/ˈbɪŋɡo/","n.","宾果","Vera won £20 at bingo.","薇拉玩宾戈赢了20英镑。"],["try","/traɪ/","v.","尝试， 试图； 努力","Let’s have a rest and then we’ll try again.","我们休息一下，然后再试。"],["gym","/dʒɪm/","n.","体育馆； 健身房","I go to the gym as often as I can.","我一有空就去健身房健身。"],["basic","/ˈbesɪk/","adj/n.","基本的；要素； 基础","the basic principles of chemistry","化学的基本原理"],["twist","/twɪst/","v/n.","拧，扭曲；扭曲， 歪曲","Her hands began to twist the handles of the bag she carried.","她的双手开始拧她拎着的那个包的拎柄。"],["unite","/juˈnaɪt/","v.","联合， 团结","Our goal is to unite the opposition parties and defeat the President.","我们的目标是联合各反对党挫败总统。"],["bush","/buʃ/","n.","灌木丛， 矮树丛","a rose bush","玫瑰丛"],["technique","/tɛkˈnik/","n.","技术， 技巧","He’s a great player, with brilliant technique.","他是个伟大的球员，球技十分精湛。"],["cause","/kɔz/","n/vt.","原因，起因；促使， 引起","It’s our job to establish the cause of the fire.","查明起火原因是我们的责任。"],["dioxide","/daɪˈɑksaɪd/","n.","二氧化物","She is your indispensable oxygen, carbon dioxide is not essential you me.","她是你不可缺少的氧气，我是你可有可无的二氧化碳。"],["wound","/wund/","vt/n.","伤，使受伤；伤害；[Ｃ] 创伤； 伤口","Gunmen killed two people and wounded six others in an attack today.","在今天的一起袭击事件中，持枪歹徒打死两人，打伤六人。"],["catastrophe","/kəˈtæstrəfi/","n.","灾难； 灾祸； 横祸","From all points of view, war would be a catastrophe.","从各个方面来看，战争都会是一场灾难。"],["busy","/ˈbɪzɪ/","adj.","忙碌的","She’s busy now – can you phone later?","她现在正忙，你稍后打来好吗？"],["convey","/kənˈve/","vt.","搬运； 传播， 传达","All this information can be conveyed in a simple diagram.","所有这些信息可以通过一张简单的图表来表示。"],["extra","/ˈɛkstrə/","adj.","额外的， 外加的","Could you get an extra loaf of bread?","你能多拿一条面包吗？"],["design","/dɪˈzaɪn/","v/n.","设计；制订；筹划；样式","The tower was designed by Gilbert Scott.","这座塔楼是吉尔伯特·斯科特设计的。"],["generous","/ˈdʒɛnərəs/","adj.","慷慨的， 大方的","a generous glass of wine","一大杯葡萄酒"],["land","/lænd/","v/n.","登陆； 降落；陆地","He was sent flying into the air and landed 20 feet away.","他被抛入空中，在20英尺以外落地。"],["coincidence","/koˈɪnsɪdəns/","n.","一致； 巧合","‘I’m going to Appleby tomorrow.’ ‘ What a coincidence ! I’m going there too.’","“明天我要去阿普尔比。”“太巧了！我也要去那里。”"],["victim","/ˈvɪktɪm/","n.","受害人， 牺牲品","The victim received head injuries from which she died a week later.","受害人头部受伤，一周后死亡。"],["department","/dɪˈpɑrtmənt/","n.","部门；  系","the personnel department","人事部"],["possibility","/ˌpɒsəˈbɪləti/","n.","可能， 可能性","There’s always a possibility that he might go back to Seattle.","他也许会回到西雅图去，这种可能性一直存在。"],["direction","/dəˈrɛkʃən/","n.","方向； 说明； 说明书； 指导","Which direction did they go in ?","他们朝哪个方向走了？"],["exhibition","/ˌɛksəˈbɪʃən/","n.","展览， 展览会； 展品","...an exhibition of expressionist art.","…一场印象主义艺术展览会。"],["burn","/bɝn/","v.","燃，烧，着火；使烧焦；","I burnt all his old letters.","我把他以前的信全烧了。"],["garlic","/ˈɡɑrlɪk/","n.","大蒜","Add a crushed clove of garlic (= single section of it ).","加一瓣压碎的大蒜。"],["alcoholic","/ˌælkəˈhɒlɪk/","adj/n.","酒精的；酒精中毒的；饮酒过度的人","alcoholic drinks","酒精饮料"],["bachelor","/ˈbætʃəlɚ/","n.","学士； 单身汉","Gerald was 38, and a confirmed bachelor (=  a man who has decided that he will never marry  ) .","杰拉德38岁，抱定主意独身。"],["countryside","/ˈkʌntrɪsaɪd/","n.","乡下， 农村","The house had lovely views over open countryside .","这房子望出去是开阔的乡村美景。"],["chief","/tʃif/","adj/n.","主要的，首要的；领导","He was recently appointed chief economist at the Bank of Scotland.","他最近被任命为苏格兰银行的首席经济学家。"],["automatic","/ˈɔtəˈmætɪk/","adj.","自动的， 机械的","an automatic weapon","自动武器"],["lamp","/læmp/","n.","灯， 油灯； 光源","She switched on the bedside lamp.","她打开了床头灯。"],["cry","/kraɪ/","v/n.","喊叫； 哭；喊；哭声","‘Stop!’ she cried.","“停下！”她喊道。"],["Antarctic","/æntˈɑrktɪk/","adj/n.","南极的；南极地区","I like to read his Antarctic adventures.","我喜欢读他的南极种种的冒险事迹。"],["conduct","/kənˈdʌkt/","vt.","引导； 管理","Aluminium, being a metal, readily conducts heat .","铝这种金属导热性能很好。"],["bury","/ˈbɛri/","vt.","埋， 葬","Electric cables are buried beneath the streets.","电缆埋在街道的下面。"],["obey","/əˈbe/","v.","服从， 顺从","The little boy made no effort to obey.","这小男孩不肯服从。"],["stable","/ˈstebl/","adj.","稳定的","A wide base will make the structure much more stable.","宽大的底座会使结构牢固许多。"],["lamb","/læm/","n.","羔羊； 羔羊肉","roast lamb","烤羊肉"],["fantastic","/fænˈtæstɪk/","adj.","极好的， 美妙的， 很棒的","You look fantastic!","你看上去棒极了！"],["changeable","/ˈtʃendʒəbl/","adj.","易变的， 变化无常的","changeable weather","变化无常的天气"],["spoken","/ˈspokən/","adj.","口语的","How do you think of your proficiency in written and spoken English?","你认为你的书面英语和口头英语熟练程度如何？"],["respond","/rɪˈspɑnd/","v.","回答； 做出反应","They are likely to respond positively to the president's request for aid.","他们有可能积极地回应该总统的援助请求。"],["incident","/ˈɪnsɪdənt/","n.","事件","Am I at risk because of some incident in my sexual past?","我过去性生活中的某件事会使我处于危险境地吗？"],["walk","/wɔk/","v/n.","走路， 步行；散步","‘How did you get here?’ ‘We walked.’","“你们是怎么来这里的？”“我们是步行来的。”"],["lame","/lem/","adj.","跛的； 残废的","a lame dog","一条瘸腿的狗"],["marry","/ˈmæri/","v.","和…结婚","He married Bea in 1925.","他在1925年娶了贝亚。"],["pity","/ˈpɪti/","n.","怜悯， 同情； 憾事","I listened to Jason’s story with pity.","我同情地听贾森讲述他的故事。"],["absorb","/æbˈsɔrb/","vt.","吸收； 吸引","Plants absorb nutrients from the soil.","植物从土壤中吸收养分。"],["supply","/səˈplaɪ/","v/n.","供给， 提供；供给；供应品","Paint for the project was supplied by the city.","该项目所用油漆由市政府提供。"],["uncertain","/ʌnˈsɝtn/","adj.","不确定的","My whole future now seemed uncertain.","现在我的前途似乎是个未知数。"],["concern","/kənˈsɝn/","n/vt.","关系；关心；涉及， 关系到","His main concern is to be able to provide for his family.","他最为关心的事就是能够养家。"],["circulate","/ˈsɝkjəlet/","vt.","使流通； 使运行","The document was previously circulated in New York at the United Nations.","这份文件过去曾在纽约的联合国总部传阅过。"],["liberty","/ˈlɪbɚti/","n.","自由","the fight for liberty and equality","争取自由和平等的斗争"],["recycle","/ˌriːˈsaɪkl/","v.","再循环， 回收","We take all our bottles to be recycled.","我们把我们所有的瓶子都回收利用。"],["let","/lɛt/","vt.","让","I can’t come out tonight – my dad won’t let me.","今天晚上我不能出来，我爸爸不允许。"],["state","/stet/","n/vt.","状态；国家；州；宣称","She was in an extremely confused state of mind .","她思绪纷乱。"],["press","/prɛs/","vt/n.","压，按；压， 按； 新闻界， 出版社","Manville kept his back pressed flat against the wall.","曼维尔后背紧紧地贴在墙上。"],["welcome","/ˈwɛlkəm/","n&vt&adj.","欢迎","I must be there to welcome my guests.","我必须在那里迎接我的客人。"],["confidential","/ˌkɒnfɪˈdenʃl/","adj.","极受信任的； 秘密的","a confidential government report","一份机密的政府报告"],["chaos","/ˈkeɑs/","n.","混乱","The country was plunged into economic chaos.","这个国家陷入了经济大混乱。"],["abundant","/əˈbʌndənt/","adj.","丰富的， 充裕的","an abundant supply of fresh water","充足的淡水供应"],["want","/wɔ:nt/","v.","想要， 需要","I really want a drink.","我很想喝一杯。"],["pace","/pes/","n.","步子， 步速； 节奏","He quickened his pace , longing to be home.","他加快步伐，盼望着早点回到家中。"],["ballet","/bæˈle/","n.","芭蕾舞， 芭蕾舞剧","We’re going to the ballet tomorrow evening.","我们明天晚上要去看芭蕾舞演出。"],["opposite","/ˈɑpəzɪt/","adj/n.","相反的， 对面的；相反，对面；对立面，对立物","I thought the medicine would make him sleep, but it had the opposite effect.","我以为这药会让他睡觉，但是它却起了反作用。"],["forecast","/ˈfɔrkæst/","n/vt.","预知；预告， 预测","The weather forecast is good for tomorrow.","天气预报说明天是晴天。"],["recognize","/ˈrɛkəɡˌnaɪz/","vt.","认出； 承认","I didn’t recognize you in your uniform.","你穿上制服我认不出你了。"],["warehouse","/ˈwɛrhaʊs/","n.","仓库； 大商店","Each warehouse reports back to the retailer which portion (if any) of the customer order it was able to fulfil.","每个仓库把它能完成客户定单的哪个部分（如果有）的报告返回给零售商。"],["pack","/pæk/","v/n.","包装， 整理；包，背包；一群","I forgot to pack my razor.","我忘记把剃须刀放入行李包了。"],["each","/itʃ/","adj&pron.","每人， 每个， 每件","Nobel for each and every one of us.","一个我们每一个人的诺贝尔和平奖。"],["abnormal","/æbˈnɔːrml/","adj.","反常的； 变态的","abnormal behaviour","反常行为"],["difference","/ˈdɪfrəns/","n.","不同","an adventure holiday with a difference","非同一般的历险度假"],["must","/mʌst/","modal verb/n.","必须；必须做的事；必不可少的东西","All passengers must wear seat belts.","所有乘客都必须系安全带。"],["circle","/ˈsɝkl/","v/n.","围起来， 环绕；圆圈","This is the road that circles the city.","这就是那条环城路。"],["resign","/rɪˈzaɪn/","v.","辞去， 辞职","A hospital administrator has resigned over claims he lied to get the job.","一位医院主管因为有人声称他的职位是骗来的而辞职了。"],["drier","/ˈdraɪɚ/","n.","烘干机， 吹风机","If you buy a drier, look for one with a sensor which switches off when clothes are dry.","你若要买烘干机，找一台带感应器的，可以在衣服干的时候自动断电。"],["bathe","/beð/","v.","洗澡， 沐浴， 浸洗","I bathed, washed my hair, and got dressed.","我洗了澡，洗了头，然后穿上衣服。"],["polite","/pəˈlaɪt/","adj.","有礼貌的， 有教养的","She’s always very polite.","她总是很有礼貌。"],["cut","/kʌt/","v/n.","切，剪，削，割；删节；伤口","They’re introducing CCTV cameras in an attempt to cut street crime in the area.","为了减少该地区的街头犯罪，他们安装了闭路电视摄像机。"],["entertainment","/ˌɛntɚˈtenmənt/","n.","娱乐； 娱乐表演","The town provides a wide choice of entertainment.","该镇提供各式各样的娱乐活动。"],["probably","/ˈprɑbəbli/","adv.","很可能， 大概","The White House probably won't make this plan public until July.","白宫可能要到7月份才会公布这项计划。"],["document","/dɑkjəmənt/","n.","文件， 文献","She produces legal documents for a downtown Seattle law firm.","她为西雅图市区的一家法律事务所撰写法律文件。"],["aluminum","/əˈlʊmɪnəm/","n.","铝","We take all our aluminum cans for recycling.","我们将所有的铝罐回收再利用。"],["ward","/wɔrd/","vt/n.","保卫，看护；病房， 收容所","the other patients in the ward","病房里的其他病人"],["starve","/stɑrv/","v.","饿死， 挨饿","Thousands of people will starve if food doesn’t reach the city.","如果食品不能运到那座城市，成千上万的人就要饿死。"],["prize","/praɪz/","n.","奖赏， 奖品， 奖金","In this month’s competition you could win a prize worth £3,000.","在本月的竞赛中您可以赢得价值3,000英镑的奖品。"],["accident","/ˈæksədənt/","n.","事故， 意外事件","Over 70,000 people are seriously injured every year in road accidents.","每年在道路事故中受重伤的有七万多人。"],["clay","/kle/","n.","黏土； 泥土","...the heavy clay soils of Georgia.","…佐治亚州厚重的黏土的土壤。"],["moment","/ˈmomənt/","n.","[C] 片刻， 瞬间， 刹那","He was here a moment ago .","他刚刚还在这里。"],["anyway","/ˈɛnɪˈwe/","adv.","不管怎样","I don't know why I settled on Miami, but anyway I did.","我不知道为什么我落户到了迈阿密，但不管怎样我做了。"],["promote","/prəˈmot/","vt.","促进； 提升； 推销","You don't have to sacrifice environmental protection to promote economic growth.","你们没有必要牺牲环保来促进经济增长。"],["routine","/rʊˈtin/","n.","常规， 日常事务","John’s departure had upset their daily routine .","约翰的离去打乱了他们的日常生活。"],["found","/faʊnd/","vt.","成立， 建立","Founded in 1935 in Ohio, Alcoholics Anonymous is now a world-wide organization.","嗜酒者互诫协会1935年创立于俄亥俄州，现在是一个世界性的组织。"],["tear","/(forv.)ˈter/","v/n.","扯破， 撕开；眼泪","Have you sewn up the tear in my coat?","你把我大衣上那个撕破的口子缝起来了吗？"],["excuse","/ɪkˈskjus/","n/vt.","借口， 理由；原谅， 宽恕","I’m tired of listening to his excuses.","我听厌了他的种种理由。"],["attack","/əˈtæk/","v&n.","攻击， 袭击","a bomb attack","炸弹袭击"],["spoonful","/ˈspʊnˈfʊl/","n.","一匙","He took a spoonful of the stew and ate it.","他舀起一匙炖菜吃了下去。"],["humour","/ˈhju:mə/","n.","幽默， 幽默感","his humour and charm","他的幽默感和魅力"],["divorce","/dɪˈvɔrs/","n/vt.","离婚；使离婚","Why doesn’t she get a divorce ?","她为什么不离婚呢？"],["currency","/ˈkɜrənsi/","n.","货币","The bank can supply you with foreign currency .","这家银行能为你提供外币。"],["distribute","/dɪˈstrɪbjut/","v.","分布； 分配","a man distributing leaflets to passers-by","一个向路人派发传单的男子"],["worried","/ˈwɝrɪd/","adj.","担心的； 烦恼的","She gave me a worried look.","她担心地看了我一眼。"],["attach","/əˈtætʃ/","vt.","系上， 贴上","We attach labels to things before we file them away.","我们在把东西归档前先给它们贴上标签。"],["canal","/kəˈnæl/","n.","运河； 水道","We walked along by the side of the canal.","我们沿着运河边往前走。"],["shout","/ʃaʊt/","v/n.","呼喊， 呼叫；[C]喊，高声呼喊","There’s no need to shout! I can hear you!","用不着大声喊叫！我听得见！"],["escape","/ɪˈskep/","v&n.","逃跑， 逃脱； 避开","He broke down the locked door and escaped.","他砸开上锁的门，逃走了。"],["flashlight","/ˈflæʃlaɪt/","n.","手电筒； 闪光信号","",""],["ankle","/ˈæŋkl/","n.","脚踝","slender ankles","纤细的脚踝"],["situation","/ˌsɪtʃʊˈeʃən/","n.","形势， 情况","I explained the situation to everyone.","我向大家介绍了一下情况。"],["think","/θɪŋk/","v.","想， 思索； 认为","I thought I heard something.","我觉得我听到了什么声音。"],["receive","/rɪˈsiv/","v.","收到， 得到","All the children will receive a small gift.","每个孩子都会收到一份小礼物。"],["thirst","/θɝst/","n.","渴， 口渴","Ice water is the only thing that really quenches my thirst (= gets rid of it ) .","只有冰水才能让我真正解渴。"],["participate","/pɑrˈtɪsəˈpet/","vi.","参加， 参与","Some members refused to participate.","有些会员拒绝参加。"],["surplus","/ˈsɝpləs/","n.","剩余， 过剩","Any surplus can be trimmed away.","多出来的部分可以修剪掉。"],["refresh","/riˈfrɛʃ/","v.","精神振作； 更新","A shower will refresh you.","洗个淋浴你就凉快了。"],["librarian","/laɪˈbrɛrɪən/","n.","图书管理员， 图书馆馆长","The new librarian is a friend of mine.","这位新来的图书管理员是我的朋友。"],["theft","/θɛft/","n.","盗窃案","Car theft is on the increase.","汽车盗窃案在上升。"],["religion","/rɪˈlɪdʒən/","n.","宗教","The U.S. Constitution promises freedom of religion.","美国宪法保证宗教信仰自由。"],["diagram","/ˈdaɪəɡræm/","n.","图表， 图样","This diagram will illustrate what I mean.","这个图表可说明我的意思。"],["claw","/klɔ/","n.","爪","The cat dug his claws into my leg.","猫的爪子抓进了我的腿中。"],["prayer","/prɛr/","n.","祈祷","Our thoughts and prayers are with you at this difficult time.","在这艰难时期我们时刻思念你，为你祈祷。"],["speech","/spitʃ/","n.","演讲","He has to make a lot of after-dinner speeches .","他经常要发表席后演说。"],["watch","/wɑtʃ/","v/n.","观察， 观看；手表","Do you mind if I watch?","你介意我看着吗？"],["clap","/klæp/","v.","拍手， 鼓掌","One man began to clap, and others joined in.","一个人鼓起了掌，其他人也跟着鼓掌。"],["quit","/kwɪt/","v.","离开； 停止","He quit his job after an argument with a colleague.","他和一个同事争吵后就辞职了。"],["polish","/ˈpɑlɪʃ/","v.","擦亮， 磨光； 润色","I spent all afternoon polishing the silver.","我整个下午都在擦拭银器。"],["chart","/tʃɑrt/","n.","图表； 航海图","a chart showing last year’s sales","显示去年销售情况的一份图表"],["insurance","/ɪnˈʃʊrəns/","n.","保险","Your father took out insurance to cover the mortgage.","你父亲购买了抵押借款保险。"],["medical","/ˈmɛdɪkl/","adj.","医学的， 医疗的","medical research","医学研究"],["principle","/ˈprɪnsəpl/","n.","原则； 原理","Schools try to teach children a set of principles.","学校设法教给孩子们一套道德准则。"],["till","/tɪl/","conj&prep.","直到， 直到…为止","I didn’t have a boyfriend till I was 17.","我直到17岁才有男朋友。"],["attend","/əˈtɛnd/","v.","出席， 参加； 专心， 考虑； 看护， 照料","Only 12 people attended the meeting.","只有12个人出席了会议。"],["goods","/ɡʊdz/","n.","商品， 货物","the large market for consumer goods","庞大的消费品市场"],["lie","/laɪ/","vi/n/vt.","躺，卧，平放；位于；谎言；说谎","The town lies in a small wooded valley.","该城镇坐落于一个林木茂盛的山谷中。"],["secure","/səˈkjʊr/","adj.","安全的， 可靠的； 放心的， 无虑的","There are no secure jobs these days.","如今已经没有铁饭碗了。"],["smell","/smɛl/","n/v.","气味；闻出，闻到，嗅到","What’s that horrible smell?","是什么味道，这么难闻？"],["used to","","v.","过去常常","He used to go to our school.","他曾在我们学校就读。"],["unable","/ʌnˈebl/","adj.","不能的， 不能胜任的","The military may feel unable to hand over power to a civilian president next year.","军方可能觉得无法在明年把政权移交给一位民选总统。"],["glare","/ɡlɛr/","v/n.","瞪眼，怒目而视；闪耀；强光","The old woman glared at him.","那个老妇人怒视着他。"],["disappointed","/ˈdɪsəˈpɔɪntɪd/","adj.","失望的","Dad seemed more disappointed than angry.","与其说爸爸生气，倒不如说他失望。"],["irrigation","/ˌɪrɪˈɡeʃn/","n.","灌溉","Small blockages or collapses of the canal would choke the intricate irrigation networks.","运河的小堵塞或倒塌都会阻塞整个负责的灌溉网络。"],["late","/let/","adv/adj.","晚， 迟；晚的，迟的","The stores are open later on Thursdays.","商店星期四开门较晚。"],["continue","/kənˈtɪnju/","v.","延伸； 继续","He will be continuing his education in the US.","他将在美国继续求学。"],["shoot","/ʃut/","vt/n.","射击，射中；摄影；嫩枝， 苗， 芽","Police shot one suspect when he pulled a gun on them.","警方在一名嫌疑人拔枪指着他们时击毙了他。"],["realize","/ˈriəˌlaɪz/","vt.","认识到； 实现","It took us a while to realize the extent of the tragedy.","我们过了一段时间才意识到这场悲剧有多严重。"],["budget","/ˈbʌdʒɪt/","n.","预算","We had a really tight budget .","我们的预算很紧。"],["actual","/ˈæktʃuəl/","adj.","实际的， 现实的","I’m not joking. Those were his actual words.","我没开玩笑，那都是他的原话。"],["tension","/ˈtɛnʃən/","n.","紧张， 不安； 拉紧， 绷紧； 压力， 张力","The tension was becoming unbearable, and I wanted to scream.","这种紧张变得难以忍受，我真想大声尖叫。"],["chest","/tʃɛst/","n.","箱子； 胸部","Her heart was pounding in her chest.","她的心在胸口怦怦直跳。"],["eastern","/ˈistɚn/","adj.","东方的， 东部的","the eastern shore of the island","岛的东岸"],["marathon","/ˈmærə/","n.","马拉松","the Boston Marathon","波士顿马拉松赛"],["last","/læst/","determiner/adv/v.","最近的，最近一段时间的，最近一次的；最近，上次；(使)持续","I hadn’t seen him since the last meeting.","自从上次会面后，我再没有见到他。"],["adapt","/əˈdæpt/","v.","适应； 改编","The ability to adapt is a definite asset in this job.","适应能力是做这份工作的绝对有利条件。"],["wash","/wɔʃ/","v/n.","洗涤，冲刷；洗； 洗的衣服","This shirt needs washing.","这件衬衫该洗洗了。"],["weight","/wet/","n.","重量","The average weight of a baby at birth is just over seven pounds.","婴儿的平均出生体重是七磅多一点。"],["doubt","/daʊt/","n&v.","怀疑， 疑惑","There was still one little nagging doubt at the back of his mind.","他的心头仍有一丝挥之不去的疑虑。"],["cheerful","/ˈtʃɪrfl/","adj.","兴高采烈的， 快活的","She’s feeling more cheerful today.","今天她高兴些了。"],["uncomfortable","/ʌnˈkʌmftəbl/","adj.","不舒服的， 不安的","This sofa is so uncomfortable.","这张沙发太不舒服了。"],["develop","/dɪˈvɛləp/","v.","发展；  发育； 开发； 冲洗","Knowledge in the field of genetics has been developing very rapidly.","遗传学领域的知识发展非常迅速。"],["misunderstand","/ˌmɪsʌndəˈstænd/","vt.","误会， 不理解","Rachel, you must have misunderstood her! Ellie would never say something like that.","雷切尔，你一定是误会她了！埃莉绝不会说那样的话。"],["warn","/wɔrn/","vt.","警告； 预告","‘Be careful, the rocks are slippery,’ Alex warned.","“小心，岩石很滑。”亚历克斯提醒说。"],["measure","/ˈmɛʒɚ/","v/n.","测量；权衡；方法， 措施","The rainfall was measured over a three-month period.","对三个月内的降雨量进行了测量。"],["guilty","/ˈɡɪlti/","adj.","有罪的， 犯法的； 内疚的","She looked self-conscious and guilty.","她看上去很不自然，很内疚的样子。"],["crossroads","/ˈkrɔsrodz/","n.","十字路口","The car was approaching the crossroads.","汽车正驶近交叉路口。"],["district","/ˈdɪstrɪkt/","n.","区， 地区","a postal district","邮政区"],["receipt","/rɪˈsit/","n.","收据； 收到， 接收","Keep your receipt in case you want to bring it back.","保留收据以备退货之需。"],["assume","/əˈsum/","vt.","假定， 设想； 承担","I think we can safely assume (=  it is almost certain  ) that interest rates will go up again soon.","我想我们几乎可以肯定，利率很快会再次上调。"],["swim","/swɪm/","vi.","游泳； 游","Let’s go swimming this afternoon.","今天下午我们游泳去吧。"],["full","/fʊl/","adv/adj.","完整地， 十分地；满的，充满的，完全的","The train was completely full.","火车坐得满满的。"],["basement","/ˈbesmənt/","n.","地下室","They bought an old schoolhouse to live in and built a workshop in the basement.","他们买了座旧校舍居住，还在地下室建了个作坊。"],["pepper","/ˈpɛpɚ/","n.","胡椒粉","salt and pepper","盐和胡椒粉"],["chant","/tʃænt/","v/n.","唱；歌颂；圣歌， 赞美诗","protesters chanting anti-government slogans","反复呼喊反政府口号的抗议者"],["capsule","/ˈkæpsl/","n.","胶囊； 太空舱","a space capsule orbiting the Earth","沿地球轨道飞行的太空舱"],["away","/əˈwe/","adv.","离开， 远离","Go away!","走开！"],["memory","/ˈmɛməri/","n.","回忆， 记忆","He has lots of happy memories of his stay in Japan.","他对在日本逗留的那段时光有许多美好的回忆。"],["concept","/ˈkɑnsɛpt/","n.","概念， 观念","a new concept in business travel","商务旅行的新理念"],["motivation","/ˌməutɪˈveɪʃn/","n.","动机","Jack is an intelligent pupil, but he lacks motivation.","杰克是一个很聪明的学生，但学习不够主动。"],["impossible","/ɪmˈpɑsəbl/","adj.","不可能的， 办不到的","‘I want to speak to Mr Franks.’ ‘I’m afraid that’s impossible.’","“我想和弗兰克斯先生谈谈。”“恐怕不行。”"],["effort","/ˈɛfɚt/","n.","努力， 艰难的尝试","please make an effort to be polite.","请尽量礼貌些。"],["wave","/wev/","v/n.","挥手；摇动；波， 波浪","Enid waved at us and we waved back.","伊妮德向我们挥手，我们也向她挥手。"],["disaster","/dɪˈzæstɚ/","n.","灾难， 祸患","One hundred and twenty people died in China’s worst air disaster .","有120人在中国这起最惨烈的空难事故中丧生。"],["anything","/ˈɛnɪˈθɪŋ/","pron.","某事  ； 任何事","You can buy anything you want.","你想要什么都可以买。"],["agriculture","/ˈæɡrɪkʌltʃɚ/","n.","农业， 农学","More than 75% of the land is used for agriculture.","75%以上的土地用于农耕。"],["grocer","/ɡrosɚ/","n.","零售商人； 食品店","The grocer sells wine and spirits.","这位食品商出售葡萄酒和烈性酒。"],["ecology","/ɪˈkɑlədʒi/","n.","生态学","the natural ecology of the Earth","地球的自然生态"],["stare","/stɛr/","v.","盯着看， 凝视","She sat there staring into space (= looking for a long time at nothing ) .","她坐在那里，出神地凝视前方。"],["painful","/ˈpenfl/","adj.","痛苦的； 疼痛的","stiff painful joints","僵硬疼痛的关节"],["steady","/ˈstɛdi/","adj.","稳固的； 平稳的","Paul is making steady progress.","保罗逐渐在进步。"],["vote","/vot/","v.","选举， 投票","In 1918 British women got the right to vote.","1918年，英国妇女获得了选举权。"],["early","/ˈɝli/","adv/adj.","早， 在早期；早的，早期的","The restaurant opened earlier this month.","这家餐馆本月早些时候开业了。"],["harvest","/ˈhɑrvɪst/","n&v.","收割； 收获","The company is now reaping the harvest of careful planning.","公司现在尝到了精心规划带来的甜头。"],["pain","/pen/","n.","疼痛；","The pain is getting worse.","疼得越来越厉害了。"],["disease","/dɪˈziz/","n.","病， 疾病","His father died of heart disease.","他父亲死于心脏病。"],["start","/stɑrt/","n&v.","开始， 着手； 出发","There’s so much to do. I don’t know where to start.","有那么多的事情要做，我都不知道从哪里开始。"],["purchase","/ˈpɝtʃəs/","n&vt.","购买","You can purchase insurance online.","你可以在网上买保险。"],["yet","/jɛt/","adv.","到目前为止； 还； 仍然","We’ve had no luck as yet.","到目前为止，我们还没什么运气。"],["engineer","/ˌendʒɪˈnɪə/","n.","工程师； 技师","He trained as a civil engineer (= one who designs and builds roads, bridges etc ).","他接受过土木工程师培训。"],["pair","/pɛr/","n.","一双， 一对","earrings, £5 a pair","耳环，5英镑一副"],["manage","/ˈmænɪdʒ/","vi/vt.","应付过去；管理；达成","I don’t know how she manages with seven children.","我不知道七个孩子她是怎么应付的。"],["equal","/ˈikwəl/","adj/vt.","平等的，相等的；等于， 比得上","Our constitution states that all men are equal.","我们的宪法规定人人平等。"],["alike","/əˈlaɪk/","adv/adj.","类似于， 以同样的方式；相同的，相似的","I learned a lot from teachers and students alike.","我从老师和学生身上都获益良多。"],["gravity","/ˈɡrævətɪ/","n.","地心引力， 重力","the force of gravity","重力"],["typical","/ˈtɪpɪkl/","adj.","典型的； 象征性的","typical British weather","典型的英国天气"],["bravery","/ˈbrevəri/","n.","勇敢， 勇气","an act of great bravery","非常勇敢的行为"],["finance","/ˈfaɪnæns/","n.","财政， 金融","leasing and other forms of business finance","租赁及其他商业金融形式"],["parking","/ˈpɑrkɪŋ/","n.","停车","No Parking (= used on signs )","禁止停车"],["shadow","/ˈʃædo/","n.","[C] 影子， 阴影","the long dark shadow of an old oak tree","一棵老橡树长长的影子"],["hydrogen","/ˈhaɪdrədʒən/","n.","氢","At the South Pole, in a region of continuous darkness, humans could access water to produce hydrogen and oxygen.","月球南极是一个持续黑暗的区域，在这里，人类能够接触到水，以生产氢和氧。"],["put","/pʊt/","vt.","放， 摆","He put the coffee on the table.","他把咖啡放在桌上。"],["climb","/klaɪm/","v.","爬， 攀登","Harry climbed the stairs.","哈里爬上楼梯。"],["offence","/əˈfɛns/","n.","犯罪； 过错； 冒犯； 攻击","Don’t be upset by what he said; he meant no offence (= did not intend to offend anyone ).","不要为他的话而生气，他并没有冒犯谁的意思。"],["carbon","/ˈkɑrbən/","n.","碳","They degrade into carbon and oxygen.","他们能被降解成碳和氧。"],["circus","/ˈsɝkəs/","n.","马戏团","My real ambition was to work in a circus.","我真正的理想是去马戏团工作。"],["controversial","/ˌkɒntrəˈvɜːʃl/","adj.","争论的， 争议的","the controversial issue of welfare reform","福利改革这一有争议的话题"],["dinosaur","/ˈdaɪnəˌsɔr/","n.","恐龙","My dinosaur and I go to school.","我的恐龙和我去上学。"],["enter","/ˈɛntɚ/","v.","进入","Both the boys entered the army.","两个男孩都参了军。"],["attain","/əˈten/","vt.","获得； 达到","More women are attaining positions of power.","越来越多的女性获得要职。"],["trap","/træp/","vt/n.","使陷入困境；陷阱， 圈套","Twenty miners were trapped underground.","20名矿工被困在地下。"],["lonely","/ˈlonli/","adj.","孤独的， 寂寞的","a lonely old man","一个孤单的老人"],["tram","/træm/","n.","有轨电车","You can get to the beach easily from the centre of town by tram.","你可以很容易地在市中心坐有轨电车到达海滩。"],["pale","/pel/","adj.","苍白的， 灰白的","He looked very pale and drawn.","他看上去非常苍白憔悴。"],["struggle","/ˈstrʌɡl/","n&v.","努力， 斗争， 挣扎","The team has been struggling all season.","整个赛季球队都打得很艰难。"],["gallery","/ˈgæləri/","n.","画廊， 美术品陈列室","an exhibition of African art at the Hayward Gallery","海沃德美术馆的非洲艺术展览"],["pest","/pɛst/","n.","害虫","a chemical used in pest control","用于防治虫害的一种化学品"],["warmth","/wɔrmθ/","n.","温暖， 暖和； 热烈， 热情， 热心","She went further into the room, drawn by the warmth of the fire.","她被火的温暖吸引着，走进了房间。"],["lesson","/ˈlɛsn/","n.","课； 功课； 教训","piano lessons","钢琴课"],["destroy","/dɪˈstrɔɪ/","v.","破坏， 毁坏","companies that are polluting and destroying the environment","污染和破坏环境的公司"],["supreme","/suˈprim/","adj.","极度的； 极大的， 最高的","the Supreme Allied Commander in Europe","欧洲盟军最高指挥官"],["ambulance","/ˈæmbjələns/","n.","救护车","the ambulance service","救护车服务"],["junior","/ˈdʒunɪɚ/","adj.","初级的； 年少的","a junior doctor","初级医生"],["coast","/kost/","n.","海岸， 海滨","We drove along the Pacific coast to Seattle.","我们沿着太平洋海岸驾车前往西雅图。"],["shuttle","/ˈʃʌtl/","n.","车辆、 飞机等","There is a free 24-hour shuttle between the airport terminals.","在机场的各航空站之间有24小时的免费穿梭巴士。"],["provide","/prəˈvaɪd/","v.","提供","Tea and biscuits will be provided.","有茶水和饼干供应。"],["allocate","/ˈæləket/","vt.","分配； 配给； 拨出","Tickets are limited and will be allocated to those who apply first.","票数有限，将分配给那些先申请的人。"],["light","/laɪt/","vi/adj/n.","点，变亮；明亮的； 轻的； 浅色的；光，灯，灯光","He stopped to light a cigarette.","他停下来点了一支烟。"],["valuable","/ˈvæljuəbəl/","adj.","值钱的， 贵重的","a valuable painting","一幅名贵的画"],["primary","/ˈpraɪmɛri/","adj.","初级的； 首要的","Our primary concern is to provide the refugees with food and health care.","我们的头等大事是向难民提供食品和医疗。"],["stubborn","/ˈstʌbɚn/","adj.","顽固的， 固执的； 难应付的","Why are you so stubborn?","你怎么这么固执？"],["enterprise","/ˈɛntɚˈpraɪz/","n.","企业， 事业","commercial enterprises such as banks and food manufacturers","银行和食品制造厂等商业企业"],["paperwork","/ˈpepɚˈwɝk/","n.","文书工作","Police work involves so much paperwork these days.","如今当警察也要做这么多文书工作。"],["solar","/ˈsolɚ/","adj.","太阳的","a solar eclipse","日食"],["consume","/kənˈsum/","vt.","消耗； 消费","Only 27% of the paper we consume is recycled.","我们消耗的纸张只有 27% 得到回收利用。"],["triangle","/ˈtraɪæŋɡl/","adj/n.","三角形的；三角形","Yes, it is like a triangle.","是的，它象一个三角形。"],["competence","/ˈkɑmpɪtəns/","n.","能力","Typing is considered by most employers to be a basic competence.","大多数雇主认为打字是一项基本技能。"],["helmet","/ˈhɛlmɪt/","n.","头盔","The bullet glanced off his helmet.","那颗子弹掠过他的头盔。"],["theme","/θim/","n.","主题","The book’s theme is the conflict between love and duty.","本书的主题是爱与责任之间的冲突。"],["consult","/kənˈsʌlt/","v.","请教， 商议； 查询","If symptoms persist, consult a doctor without delay.","如果症状持续的话，马上咨询医生。"],["merely","/ˈmɪrli/","adv.","仅仅， 只不过","He’s merely a boy – you can’t expect him to understand.","他只是个孩子——你不要指望他能理解。"],["wealth","/wɛlθ/","n.","财富","The country’s wealth comes from its oil.","这个国家的财富来自石油。"],["editor","/ˈɛdɪtɚ/","n.","编辑","the editor of a book of essays on modern poetry","现代诗歌论文集的编者"],["means","/minz/","n.","方法， 手段","The only means of communication was sign language.","唯一的交流方法是手语。"],["chain","/tʃen/","n.","链， 链条","She had a gold chain around her neck.","她脖子上戴了条金项链。"],["desire","/dɪˈzaɪɚ/","n&v.","渴望， 期望","The hotel has everything you could possibly desire .","这家酒店里你想要的东西应有尽有。"],["survive","/sɚˈvaɪv/","vi/vt.","幸存，生还；比…活得长","Only 12 of the 140 passengers survived.","140 名乘客中只有 12 人生还。"],["initial","/ɪˈnɪʃəl/","adj.","开始的， 最初的","an initial investment of £5,000","5,000英镑的初始投资"],["muddy","/ˈmʌdi/","adj.","泥泞的，多泥的","Take your boots off outside if they’re muddy.","要是靴子上都是泥，你就脱在门外吧。"],["consistent","/kənˈsɪstənt/","adj.","一致的， 连贯的","She’s the team’s most consistent player.","她是该队中表现最为稳定的选手。"],["sword","/sɔːrd/","n.","剑， 刀","The treaty hung like a sword of Damocles over French politics.","这个条约好像一把达摩克利斯之剑悬在法国政坛之上。"],["fingernail","/ˈfɪŋɡɚnel/","n.","手指甲","Guess how long is the longest fingernail in the world?","请大家猜猜看世界上最长的手指甲到底有多长呢。"],["permanent","/ˈpɝmənənt/","adj.","永久的， 持久的","He gave up a permanent job in order to freelance.","他放弃了固定工作，为的是当一名自由职业者。"],["chat","/tʃæt/","vi/n.","聊天， 闲谈；聊天，闲谈","John and I sat up until the early hours chatting.","我和约翰聊到凌晨才睡。"],["fetch","/fɛtʃ/","v.","去取来， 去请来","Quick! Go and fetch a doctor.","快！去请医生来。"],["fellow","/ˈfɛlo/","n.","同伴， 伙伴","He stood out in terms of competence from all his fellows.","他在能力方面比他所有同事都突出。"],["choice","/tʃɔɪs/","n.","选择， 抉择","He has to make some important choices.","他得作出一些重要的抉择。"],["travel","/ˈtrævl/","n&vi.","旅行","They travelled 200 miles on the first day.","他们第一天行进了200英里。"],["civilization","/ˌsɪvəlaɪˈzeɪʃn/","n.","文明， 文化","modern American civilization","现代美国文明"],["before","/bɪˈfɔr/","adv/conj/prep.","以前；在…之前；在…以前，在…前面","Haven’t I met you before somewhere?","我以前在哪儿见过你吗？"],["fiction","/ˈfɪkʃən/","n.","小说； 虚构， 杜撰","romantic fiction","爱情小说"],["friendly","/ˈfrɛndlɪ/","adj.","友好的","a friendly smile","亲切的微笑"],["possession","/pəˈzɛʃən/","n.","所有， 拥有； 财产， 所有物","That information is not in our possession.","那则信息不归我们所有。"],["tell","/tel/","v.","告诉， 吩咐； 辨别， 知道","I’ll tell you all about it when I get back.","我回来再告诉你这一切。"],["replace","/rɪˈples/","vt.","取代， 代替； 把…放回原处","I’m replacing Sue on the team.","我将接替队里的休。"],["appointment","/əˈpɔɪntmənt/","n.","约会","All consultations are by appointment only .","就诊必须预约。"],["stomach","/ˈstʌmək/","n.","[C] 胃， 胃部","I was so hungry my stomach hurt.","我饿得胃都痛了。"],["experience","/ɪkˈspɪrɪəns/","vt/n.","经历，体验；经验； 经历","Children need to experience things for themselves in order to learn from them.","儿童需要亲身经历事情以便从中学习。"],["listen","/ˈlɪsn/","vi.","听， 仔细听， 留神听","Listen! There’s a strange noise in the engine.","听！引擎发出奇怪的声音。"],["hit","/hɪt/","n&v.","打， 撞； 击中","He raised the hammer and hit the bell.","他举起钟锤敲钟。"],["major","/ˈmedʒɚ/","adj/n.","主要的；成年的；主修专业","There are two major political parties in the US.","美国有两大政党。"],["interrupt","/ˈɪntəˈrʌpt/","v.","打扰， 打断","Will you stop interrupting me!","别打断我的话！"],["beat","/bit/","v/n.","打赢；跳动；敲打；节拍","photographs of rioters beating a policeman","暴徒殴打一名警察的照片"],["worldwide","/ˈwɝldwaɪd/","adj.","遍及全球的， 世界各地的","We have offices in over 56 countries worldwide.","我们在全世界超过56个国家设有办事处。"],["bear","/bɛr/","v/n.","承担；忍受；熊","She was afraid she wouldn’t be able to bear the pain.","她恐怕自己忍受不了这种痛苦。"],["affair","/əˈfɛr/","n.","事， 事情","Are you interested in world affairs?","你对世界大事感兴趣吗？"],["consider","/kənˈsɪdɚ/","vt.","考虑； 认为","We will have to consider your offer carefully .","我们得仔细考虑你的提议。"],["housework","/ˈhaʊsˈwɝk/","n.","家务劳动","Men are doing more housework nowadays.","现今男人正在承担越来越多的家务。"],["potential","/pəˈtɛnʃl/","adj/n.","潜在的，可能的；潜力","The company has identified 60 potential customers.","该公司已确定了60位潜在的客户。"],["accustomed","/əˈkʌstəmd/","adj.","通常的， 习惯的","The pans were in their accustomed places.","那些锅在老地方。"],["group","/ɡrup/","n.","组， 群","A group of us are going to London.","我们有一群人要去伦敦。"],["jewelry","/ˈdʒʊəlri/","n.","〈总称〉 珠宝， 首饰","",""],["obtain","/əbˈten/","vt.","获得， 得到","Evans was trying to obtain a false passport and other documents.","埃文斯当时正试图获取假护照和其他文件。"],["lounge","/laʊndʒ/","n.","休息厅， 休息室","the television lounge","电视放映室"],["rugby","/ˈrʌɡbi/","n.","英式橄榄球","I ghosted his weekly rugby column for the Telegraph.","我为他代写《电讯报》每周的橄榄球专栏。"],["resist","/rɪˈzɪst/","vt.","抵抗； 挡开","He was charged with trying to resist arrest .","他被指控企图拒捕。"],["format","/ˈfɔrmæt/","n.","版式， 格式","a large-format book for the partially-sighted","一本给弱视者阅读的大开本的书"],["sacrifice","/ˈsækrɪfaɪs/","n&v.","牺牲， 奉献","The minister stressed the need for economic sacrifice.","部长强调了在经济上作出牺牲的必要性。"],["particular","/pɚˈtɪkjəlɚ/","adj.","特殊的；个别的","In this particular case, no one else was involved.","这件事没有其他人牵涉其中。"],["illegal","/ɪˈligl/","adj.","违法的， 不合规定的","illegal drugs","违禁药品"],["pause","/pɔz/","n&vi.","暂停， 停止","There was a pause while Alice changed the tape.","艾丽斯换磁带的时候出现了短暂的停顿。"],["congratulate","/kənˈɡrætʃulet/","vt.","祝贺， 恭贺","He never even stopped to congratulate me.","他甚至没有过来向我祝贺。"],["careless","/ˈkɛrləs/","adj.","粗心的； 漫不经心的","It was careless of him to leave the door unlocked.","他忘了锁门，真是粗心大意。"],["square","/skwɛr/","adj/n.","平方的； 方形的；广场；正方形","a large square room","一个正方形的大房间"],["rainbow","/ˈrenbo/","n.","彩虹； 幻想","...silk and satin in every shade of the rainbow.","…如彩虹般五颜六色的丝绸与锦缎。"],["twice","/twaɪs/","adv.","两次； 两倍","He was questioned by police twice yesterday.","他昨天被警察审问了两次。"],["ample","/ˈæmpl/","adj.","充足的， 丰富的","an ample bosom","丰满的胸部"],["altitude","/ˈæltɪtud/","n.","高度； 高处","The aircraft had reached its cruising altitude of about 39,000 feet.","那架飞机已经达到了大约三万九千英尺的巡航高度。"],["request","/rɪˈkwɛst/","n&vt.","要求， 请求","To request more information, please call our toll free number.","欲知详情，请拨打我们的免费电话。"],["classify","/ˈklæsɪfaɪ/","vt.","分类","We’d classify Drabble’s novels under ‘Romance’.","我们把德拉布尔的小说归类为“言情小说”。"],["part","/pɑrt/","v/n.","分离， 分别；部分；角色","When he parted the curtains, the sunlight flooded into the room.","他拉开窗帘，阳光洒进屋内。"],["percent","/pɚˈsɛnt/","n.","百分之…","I agree with you one hundred percent.","我百分之百地同意你的意见。"],["point","/pɔɪnt/","v/n.","指，指向；点； 要点， 观点； 分数","‘Look!’ she said and pointed.","“看呀！”她用手指着说道。"],["paddle","/ˈpædl/","v/n.","划桨； 戏水；桨状物；蹼","The dog was paddling furiously after the ducks.","那条狗在水里拼命划水追赶鸭子。"],["general","/ˈdʒɛnrəl/","adj.","大体的， 总的； 一般的； 普遍的","a general introduction to computing","计算机应用概论"],["tend","/tɛnd/","vi/vt.","趋向， 往往是；照管，护理","A problem for manufacturers is that lighter cars tend to be noisy.","制造商遇到的一个问题是重量较轻的汽车往往噪音大。"],["frighten","/ˈfraɪtn/","vt.","使惊恐， 吓唬","Don’t stand so near the edge! You’re frightening me.","别站得那么靠边！你要把我吓坏了。"],["relief","/rɪˈlif/","n.","缓解； 轻松","I felt a huge surge of relief and happiness.","我如释重负，大感欣慰。"],["boycott","/ˈbɔɪkɑt/","n&vt.","联合抵制","We boycott all products tested on animals.","我们抵制所有拿动物做试验的产品。"],["dimension","/dəˈmɛnʃən/","n.","尺寸， 尺度","a rectangle with the dimensions 5cm × 2cm","长五厘米、宽两厘米的长方形"],["park","/pɑrk/","n/vt.","公园；停车场；停放","Let’s go for a walk in the park.","我们去公园散步吧。"],["unbelievable","/ˌʌnbɪˈliːvəbl/","adj.","难以置信的","The opportunities are unbelievable.","机会好得令人难以相信。"],["process","/proˈsɛs/","vt/n.","加工，处理；程序； 方法","Goats’ cheese may be processed in many ways.","山羊奶干酪可以有多种加工方法。"],["deserve","/dɪˈzɝv/","vt.","应受， 值得","What have I done to deserve this?","我做了什么事，要得到这样的报应？"],["subscribe","/səbˈskraɪb/","v.","捐赠； 订阅","My main reason for subscribing to New Scientist is to keep abreast of advances in science.","我订阅《新科学家》的主要原因是要跟上科学的进步。"],["clear","/klɪr/","adj.","清晰的； 明亮的； 清楚的","clear instructions","明确的指示"],["chef","/ʃɛf/","n.","厨师","a master chef","手艺高超的厨师长"],["alternative","/ɔlˈtɝnətɪv/","adj.","选择性的， 二者择一的","An alternative route is along the Via Unione.","另一条路线是沿着联合路走。"],["zoom","/zum/","v.","突然扩大， 使猛增","",""],["colleague","/ˈkɑliɡ/","n.","同事","a colleague of mine from the bank","我在银行的一位同事"],["diamond","/ˈdaɪəmənd/","n.","钻石， 金刚石； 菱形","a diamond engagement ring","订婚钻戒"],["someone","/ˈsʌmwʌn/","pron.","某人； 重要人物","What would you do if someone tried to rob you in the street?","要是有人在街上抢劫你，你会怎么办？"],["build","/bɪld/","v/n.","建造；构造","The purpose is to build new houses for local people.","目的是要为当地居民建造新的住宅。"],["mean","/min/","v.","意味着， 意思是","What does ‘patronizing’ mean?","patronizing是什么意思？"],["approve","/əˈprʊv/","vi/vt.","赞成； 满意；批准，通过","You've never approved of Henry, have you?","你从未赞赏过亨利，是吧？"],["neither","/ˈniðɚ/","determiner/adv.","两者都不（的），两者中无一（的）；也不","‘Would you like tea or coffee?’‘Neither, thanks.’","“你要喝茶还是喝咖啡？”“都不要，谢谢。”"],["earn","/ɝn/","vt.","挣得， 赚得","He earns nearly £20,000 a year.","他每年挣近20,000英镑。"],["glad","/ɡlæd/","adj.","高兴的， 乐意的","We’re so glad you came.","你来了我们真高兴。"],["chew","/tʃʊ/","v.","咀嚼","This meat’s so tough I can hardly chew it!","这肉太老了，我几乎嚼不动！"],["pedestrian","/pəˈdɛstrɪən/","n.","步行者， 行人","Ingrid was a walker, even in Los Angeles, where a pedestrian is a rare sight.","英格丽德是个步行者，即使在行人少见的洛杉矶也是如此。"],["hurry","/ˈhɝrɪ/","v/n.","赶快；急忙；匆忙， 仓促","If we hurry, we’ll get there in time.","要是赶紧的话，我们能及时到那里。"],["account","/əˈkaʊnt/","v/n.","总计有； 认为；账目；描述","Chomsky’s account of how children learn their first language","乔姆斯基关于儿童如何学习第一语言的描述"],["tolerate","/ˈtɑləret/","vt.","忍受， 容忍","We simply will not tolerate vigilante groups on our streets.","我们决不容许有自行惩办犯罪的组织出现在我们的街头。"],["radioactive","/ˈredɪoˈæktɪv/","adj.","放射性的","the problem of how to dispose of radioactive waste","如何处理放射性废物的问题"],["underline","/ˈʌndəlaɪn/","vt.","在…下面划线； 强调","This tragic incident underlines the need for immediate action.","这一悲剧事件突显了立即采取行动的必要性。"],["innocent","/ˈɪnəsnt/","adj.","清白的， 无罪的； 纯真的","Nobody would believe that I was innocent.","没人肯相信我是清白的。"],["chopsticks","/ˈtʃɑp/","n.","筷子","Yes, I like using chopsticks.","是的，我喜欢用筷子。"],["alphabet","/ˈælfəˈbɛt/","n.","字母表","The modern Russian alphabet has 31 letters.","现代俄语字母表有31个字母。"],["ambiguous","/æmˈbɪɡjuəs/","adj.","暧昧的； 不明确的","The language in the Minister’s statement is highly ambiguous.","部长的声明措辞很含糊。"],["advance","/ədˈvæns/","v&n.","推进， 前进","Their aircraft were in advance of those used by the US.","他们的飞机比美国人用的要先进。"],["trip","/trɪp/","n.","[C] 旅行， 旅程","Two lucky employees won a round-the-world trip.","两名幸运的雇员赢得一次环游世界的机会。"],["botanical","/bəˈtænɪkl/","adj.","植物学的， 植物的","The area is of great botanical interest.","该地区很有植物学研究价值。"],["appreciate","/əˈpriʃɪet/","vt.","欣赏； 感激","Thanks ever so much for your help, I really appreciate it.","多谢你的帮助，我真的很感激。"],["record","/(forv.)rɪˈkɔrd/","v/n.","录制， 记录；记录； 唱片","Her husband made her record every penny she spent.","她丈夫要她把花的每分钱都记下来。"],["diverse","/daɪˈvɝs/","adj.","不同的， 多种多样的","subjects as diverse as pop music and archaeology","像流行音乐和考古学这样各不相同的学科"],["cube","/kjʊb/","n.","立方体， 立方","a sugar cube","一块方糖"],["strict","/strɪkt/","adj.","严格的， 严密的","a strict teacher","严格的老师"],["jump","/dʒʌmp/","v/n.","跳跃； 惊起； 猛扑；[C]跳跃","The cats jumped down and came to meet us.","这些猫跳下来，过来迎接我们。"],["knowledge","/ˈnɑlɪdʒ/","n.","知识， 学问","He did not have much knowledge of American history.","他对美国历史所知不多。"],["happen","/ˈhæpən/","v.","发生， 碰巧","When did the accident happen?","事故什么时候发生的？"],["pass","/pæs/","v.","传递； 经过","The crowd parted to let the truck pass.","人群分开让卡车通过。"],["past","/pæst/","adj/prep/n.","过去的，最近的；经过； 晚于；过去，往事","Judging by her past performance, Jane should do very well.","从以往的表现来看，简应该会干得很好。"],["festival","/ˈfɛstəvl/","n.","节日","Christmas is one of the main festivals in the Christian Calendar.","圣诞节是基督教历的重大节日之一。"],["shock","/ʃɑk/","vt/n.","使震惊；震动， 冲击","The hatred in her voice shocked him.","她语气中的仇恨让他震惊。"],["delighted","/dɪˈlaɪtɪd/","adj.","高兴的， 快乐的","Her screams of delighted laughter filled the air.","她喜悦的尖叫声在空中荡漾。"],["pancake","/ˈpænkek/","n.","薄煎饼","",""],["active","/ˈæktɪv/","adj.","积极的， 主动的","games for active youngsters","活跃好动的年轻人玩的游戏"],["bill","/bɪl/","n.","钞票； 账单； 法案， 议案","Have you paid the phone bill?","电话费你付了吗？"],["whichever","/wɪtʃˈɛvɚ/","pron.","不论哪个","Letting taxes rise abruptly would hurt not only the recovery but also whichever party the electorate ended up blaming.","突然的增税不但会妨害经济复苏，而且无论哪个政党这样做都会受到选民指责。"],["court","/kɔrt/","n.","法庭， 法院； 球场","It could not be proved in a court of law.","这无法在法庭上证实。"],["whose","/huz/","pron&conj.","谁的","",""],["bucket","/ˈbʌkɪt/","n.","桶； 铲斗","We drew water in a bucket from the well outside the door.","我们用水桶从门外的井里提水。"],["senior","/ˈsinɪɚ/","adj/n.","年长的，资深的；高年级的；上级， 长辈； 高年级学生","the senior Democrat on the House committee","众议院委员会中的资深民主党人"],["flexible","/ˈflɛksəbl/","adj.","柔软的， 灵活的","We can be flexible about your starting date.","你具体从哪天开始，我们可以灵活一点。"],["relative","/ˈrɛlətɪv/","adj/n.","相对的； 比较的；亲属，亲戚","The relative merits of both approaches have to be considered.","两种方法的相对优点都得考虑在内。"],["attitude","/ˈætɪtʊd/","n.","态度； 看法","As soon as they found out I was a doctor, their whole attitude changed.","他们一听说我是医生，态度就完全改变了。"],["organ","/ˈɔrɡən/","n.","器官","the liver, heart, and other internal organs","肝脏、心脏及其他内脏器官"],["average","/ˈævərɪdʒ/","adj/n.","平均的；普通的；平均数","The age of the candidates ranged from 29 to 49 with an average age of 37.","候选人的年龄29岁至49岁不等，平均37岁。"],["compare","/kəmˈpɛr/","vt.","比较， 对照","The report compares the different types of home computer available.","这份报告比较了市场上不同类型的家用计算机。"],["sceptical","/ˈskeptikəl/","adj.","怀疑的， 怀疑论的","‘You can trust me,’ he said. Jane looked sceptical.","“你可以相信我。”他说。而简看上去一脸怀疑。"],["unwilling","/ʌnˈwɪlɪŋ/","adj.","不愿意， 勉强的","an unwilling helper","勉强来帮忙的人"],["thriller","/ˈθrɪlɚ/","n.","使人激动的人； 惊险、 恐怖、 刺激的小说、 戏剧或电影","...a tense psychological thriller.","…一部紧张刺激的心理惊悚小说。"],["transparent","/trænsˈpærənt/","adj.","显然的； 透明的","a transparent plastic container","透明的塑料容器"],["characteristic","/ˌkærəktəˈrɪstɪk/","adj.","特有的， 独特的， 典型的","the highly characteristic (= very typical ) flint walls of the local houses","当地房子非常有特色的燧石墙"],["how","/haʊ/","adv.","怎样， 如何； 多少； 多么","How do you spell your name?","你的名字怎么拼写？"],["grasp","/ɡræsp/","vt.","抓住， 紧握； 领会","I grasped his arm firmly and led him away.","我紧紧抓住他的胳膊把他带走。"],["Buddhism","/ˈbʊdɪzəm/","n.","佛教","We can develop Buddhism as a string to weave all the beings in a single wreath.","我们可以将佛教发展成为一条将所有生物编织在同一个花环上的绳子。"],["receptionist","/rɪˈsɛpʃənɪst/","n.","接待员","So why are so many people hoping to be its receptionist?","那么，为何会有如此多的人想去当它的接待员呢？ ？"],["composition","/ˌkɒmpəˈzɪʃn/","n.","作文； 作曲","I had to write a composition about the Royal visit.","我得写一篇关于皇室出访的作文。"],["unlike","/ˈʌnˈlaɪk/","prep.","不像， 和…不同","Tammy was unlike any other woman I have ever known.","塔米和我认识的其他女人都不一样。"],["hearing","/ˈhɪrɪŋ/","n.","听力","a child with a hearing disability","有听力障碍的儿童"],["term","/tɝm/","n.","学期； 术语； 条款； 项","Teachers often feel overworked in term time (= during the term ) .","教师在学期内经常觉得工作担子过重。"],["volcano","/vɑlˈkeno/","n.","火山","Pompeii was destroyed when the volcano erupted in 79 AD.","庞贝城于公元79年在火山爆发中毁灭。"],["wedding","/ˈwɛdɪŋ/","n.","婚礼， 结婚","She’s busy planning her daughter’s wedding.","她正忙着筹备女儿的婚礼。"],["acquisition","/ˌækwɪˈzɪʃn/","n.","获得； 获得物","the acquisition of language","语言的习得"],["rigid","/ˈrɪdʒɪd/","adj.","刚硬的， 刚性的； 严格的","rigid and authoritarian methods of education","死板、专断的教育方法"],["deadline","/ˈdedlaɪn/","n.","最后期限， 截止日期","I’m always working under pressure to meet deadlines (= finish something on time ) .","我总是在赶工期的压力下工作。"],["spare","/spɛr/","adj/vt.","空闲的；多余的，剩余的；提供； 匀出， 分出","Have you got any spare boxes?","你有没有多余的盒子？"],["mine","/maɪn/","pron/v/n.","我的；开采，挖掘；矿藏","It was Glen’s idea, not mine.","这是格伦的主意，不是我的。"],["mind","/maɪnd/","v/n.","介意；思想","I don’t mind the heat, in fact I quite like it.","我不介意这么热，事实上我还挺喜欢的。"],["grateful","/ˈɡretfl/","adj.","感激的， 感谢的","Our grateful thanks go to all who participated.","我们衷心感谢所有参与者。"],["business","/ˈbɪznɪs/","n.","商业， 生意； 职业， 事业","Students on the course learn about all aspects of business.","这门课程的学生要学习商业活动的各个方面。"],["bungalow","/ˈbʌŋɡəˌlo/","n.","平房","Can I rent a bungalow ?","能租一个平房吗？"],["staff","/stæf/","n.","全体职员","The entire staff has done an outstanding job this year.","今年全体员工工作都非常出色。"],["possible","/ˈpɑsəbl/","adj.","可能的","Is it possible toget tickets for the game?","有没有可能弄到比赛的门票？"],["partly","/ˈpɑrtli/","adv.","部分地， 在一定程度上","The poor weather was partly responsible for the crash.","天气不好是造成坠机事故的部分原因。"],["breathless","/ˈbrɛθləs/","adj.","喘不过气来的","The long climb left Jan feeling breathless.","攀爬了那么长时间，简感到喘不过气来。"],["meet","/mit/","v/n.","遇见，会面；满足；集会","Meet me at 8.00.","八点钟来见我。"],["answer","/ˈænsɚ/","v/n.","回答， 应答； 接电话；答案","She thought for a moment before answering.","她想了一会儿才回答。"],["borrow","/ˈbɑro/","v.","借用； 借","Can I borrow your pen for a minute?","我可以借你的笔用一下吗？"],["maximum","/ˈmæksəməm/","n&adj.","最大量 ， 最大限度","The car has a maximum speed of 120 mph.","这辆汽车的最高时速为120英里。"],["under","/ˈʌndɚ/","adv/prep.","在下；在…下面， 向…下面","He took a deep breath before he went under.","他在钻下水前深深地吸了口气。"],["desert","/(forv.)dɪˈzɝ​t/","v/n.","舍弃， 遗弃；沙漠","Helen was deserted by her husband.","海伦被丈夫遗弃了。"],["represent","/ˌreprɪˈzent/","vt.","代表； 表现","Mr Kobayashi was chosen to represent the company at the conference.","小林先生被选中代表公司出席会议。"],["compete","/kəmˈpit/","vi.","比赛， 竞赛","The banks have long competed with American Express's charge cards and various shop cards.","这些银行长期以来一直与美国运通公司的记账卡和各种商店卡竞争。"],["die","/daɪ/","v.","死亡； 消失； 熄灭","He died in 1985 at the age of 76.","他1985年去世，终年76岁。"],["radium","/ˈredɪəm/","n.","镭","The scientists who discovered radium did not know that it would kill them.","那些发现了镭元素的科学家，并不知道这种元素会让他们丧命。"],["fragrant","/ˈfregrənt/","adj.","香的， 芬芳的","fragrant flowers","芳香的花朵"],["dig","/dɪɡ/","v.","挖  ， 掘","freshly dug carrots","刚挖出来的胡萝卜"],["accountant","/əˈkaʊntənt/","n.","会计， 会计师","I send all my income tax query to my accountant.","我把所有有关所得税的疑问送交会计师。"],["stocking","/ˈstɑkɪŋ/","n.","长筒袜","Santa Claus fills each stocking with presents on Christmas Eve.","在平安夜，圣诞老人用礼物装满每个长袜子。 。"],["sometimes","/ˈsʌmtaɪmz/","adv.","有时","I sometimes have to work late.","我有时得工作到很晚。"],["emergency","/ɪˈmɝdʒənsi/","n.","紧急情况或状态","Lifeguards are trained to deal with emergencies.","救生员接受过应对紧急情况的训练。"],["promise","/ˈprɑmɪs/","v/n.","答应，允诺；预示；答应， 允诺； 希望， 前景","Last night the headmaster promised a full investigation.","校长昨晚允诺进行全面调查。"],["dip","/dɪp/","v.","浸， 蘸","Dip each apple in the syrup until thickly coated.","把每个苹果在糖浆里蘸一下，直到被厚厚地裹上糖浆。"],["hold","/hold/","v.","拿， 握住； 举行","Hold the knife at an angle.","斜握着刀。"],["habit","/ˈhæbɪt/","n.","习惯， 习性","Regular exercise is a good habit.","经常锻炼是个好习惯。"],["passport","/ˈpæspɔrt/","n.","护照","I have an Irish passport.","我持爱尔兰护照。"],["absurd","/əbˈsɝ​d/","adj.","不合理的； 荒谬的","It seems an absurd idea.","这似乎是个荒唐的想法。"],["burglar","/ˈbɝɡlɚ/","n.","盗贼， 窃贼","Burglars broke into their home.","窃贼闯进了他们家。"],["considerate","/kənˈsɪdərɪt/","adj.","体贴的， 考虑周到的； 替人着想的","He was always kind and considerate.","他总是很善良，为别人着想。"],["rubber","/ˈrʌbɚ/","n.","橡皮； 橡胶； 合成橡胶","a rubber ball","橡皮球"],["legal","/ˈligl/","adj.","法律的， 法定的","What the company has done is perfectly legal.","公司所做的这一切完全合法。"],["underwear","/ˈʌndɚwɛr/","n.","内衣","You just need to take a change of underwear.","你只需带一套换洗的内衣。"],["talk","/tɔk/","v/n.","谈话，议论；谈话， 会谈； 演讲","I could hear Sarah and Andy talking in the next room.","我听到萨拉和安迪在隔壁讲话。"],["reply","/rɪˈplai/","n&vi.","回答， 答复","I asked Clive where he was going, but he didn’t reply.","我问克莱夫到哪儿去，但他没有回答。"],["train","/tren/","v/n.","培训，训练；火车","a highly trained workforce","训练有素的劳动力"],["parcel","/ˈpɑrsl/","n.","包裹","The parcel was delivered last week.","那个邮包上周送到了。"],["test","/tɛst/","n&vt.","测试， 考查， 试验","Did you get a good mark in the test?","你这次测验成绩好吗？"],["journey","/ˈdʒɝ​nɪ/","n.","旅行， 路程","the friends they made on the journey","他们在旅途中交下的朋友"],["count","/kaʊnt/","v.","数； 计算； 有价值","I was amazed at the number of plants - I counted 147.","我对植物的数量之多感到惊讶，我数了有147棵。"],["graph","/ɡræf/","n.","图表， 曲线图","Martin showed me a graph of their recent sales.","马丁给我看了他们最近销售情况的图表。"],["upwards","/ˈʌpwəd(z)/","adv.","向上， 往上","Pointing upwards, he indicated a large nest high in the tree.","他朝上指指，示意树上高处有个大鸟窝。"],["feast","/fist/","n.","盛宴； 节日； 令人愉悦的事情","a wedding feast","婚筵"],["contradictory","/ˌkɒntrəˈdɪktəri/","adj.","相互矛盾的；不一致的","Customs officials have made a series of contradictory statements about the equipment.","海关官员们对于这种设备做出了一系列相互矛盾的陈述。"],["take","/tek/","v.","拿走； 接受， 接纳","Will you take the job?","你接受这份工作吗？"],["accompany","/əˈkʌmpəni/","vt.","陪伴， 伴随； 伴奏","Children under 14 must be accompanied by an adult.","14岁以下儿童必须有成人陪同。"],["petrol","/ˈpɛtrəl/","n.","汽油","unleaded petrol","无铅汽油"],["beneficial","/ˌbenɪˈfɪʃl/","adj.","有益的， 受益的","a drug that has a beneficial effect on the immune system","有益于免疫系统的一种药物"],["blame","/blem/","n&vt.","责备， 责怪","Don’t blame me – it’s not my fault.","别来怪我——又不是我的错。"],["final","/ˈfaɪnl/","adj/n.","最后的；决赛； 期末考试","The final episode will be shown tonight.","最后一集将于今晚播出。"],["some","/sʌm/","pron/adj.","若干， 一些；一些，若干；有些；某一","I’ve just made a pot of coffee. Would you like some?","我刚煮了一壶咖啡，你想喝点吗？"],["squeeze","/skwiz/","v/n.","压榨， 挤；紧握，捏","She smiled as he squeezed her hand.","他捏了捏她的手，她笑了。"],["blank","/blæŋk/","adj/n.","空的；茫然的；空格， 空白， 空白处","Leave the last page blank .","最后一页留空。"],["rather","/ˈræðɚ/","adv.","相当， 宁可","I grew up in rather unusual circumstances.","我在相当不寻常的环境中长大。"],["importance","/ɪmˈpɔrtns/","n.","重要性","He was full of his own importance (= he behaved in an annoying way which showed that he thought he was very important ).","他自以为很了不起。"],["session","/ˈsɛʃən/","n.","会议； 开庭","Board members met in closed session (= with nobody else present ) .","委员会成员举行了闭门会议。"],["back","/bæk/","adv/adj/n.","回；向后；后面的；背后， 后部； 背","I’ll be back in a minute.","我马上回来。"],["worthy","/wɜði/","adj.","值得的； 相称的","Leeds United were worthy winners of the competition.","利兹联队是比赛当之无愧的获胜者。"],["endless","/ˈɛndlɪs/","adj.","无止境的； 没完没了的","an endless stream of visitors","川流不息的游客"],["training","/ˈtrenɪŋ/","n.","培训","Police drivers have to undergo intensive training .","警察驾驶员都得接受强化训练。"],["expectation","/ˌekspekˈteɪʃn/","n.","预料； 期望","Having raised expectations (= made people more hopeful ), he went on to help only a few people.","他唤起了大家的希望，但接着只是帮助了几个人。"],["mist","/mɪst/","n.","雾","We could just see the outline of the house through the mist.","薄雾中我们只能看到房子的轮廓。"],["miss","/mɪs/","v.","错过； 想念","I’m absolutely starving – I missed lunch.","我饿坏了——我没吃上午饭。"],["pound","/paʊnd/","n.","磅； 英镑","Moira weighs about 130 pounds .","莫伊拉的体重约为130磅。"],["load","/lod/","n.","担子， 货物","We got a load of complaints about the loud music.","很多人向我们投诉音乐太响。"],["bite","/baɪt/","v/n.","咬，叮；咬； 一口","The dog bit him and made his hand bleed.","那只狗把他的手咬出血了。"],["ferry","/ˈfɛri/","n.","渡船","They had recrossed the River Gambia by ferry.","他们乘船又一次渡过了冈比亚河。"],["disgusting","/dɪsˈɡʌstɪŋ/","adj.","令人讨厌的","Rubbish was piled everywhere – it was disgusting.","垃圾堆得到处都是，很恶心。"],["ignore","/ɪɡˈnɔr/","vt.","不理睬； 忽视","You can’t ignore the fact that many criminals never go to prison.","你不能无视很多罪犯从未获刑的事实。"],["loaf","/lof/","n.","一条","a loaf of bread","一条面包"],["reception","/rɪˈsɛpʃən/","n.","接待","She was unsure of her reception after everything that had happened.","发生了这些事后，她对自己是否还受欢迎没把握。"],["applaud","/əˈplɔd/","v.","鼓掌， 喝彩","The audience applauded loudly.","观众掌声雷动。"],["just","/dʒʌst/","adv/adj.","刚才，恰好；只是，仅；公正的","A good strong cup of coffee is just what I need right now.","我现在正需要喝一杯浓浓的咖啡。"],["outward","/ˈaʊtwɚd/","adv/adj.","向外，在外；向外的， 外出的","The top door opened outward.","最上面的门向外开着。"],["notice","/ˈnotɪs/","v/n.","注意到；通告，注意","He noticed a woman in a black dress sitting across from him.","他看到有位黑衣女子坐在他的对面。"],["yummy","/ˈjʌmi/","adj.","美味的","Yes, thanks. It's yummy!","是的，谢谢。它是美味的！"],["holy","/ˈholi/","adj.","神圣的","the holy city of Varanasi","圣城瓦拉纳西"],["relax","/rɪˈlæks/","v.","放松， 轻松","I just want to sit down and relax.","我只想坐下来休息一下。"],["relay","/rɪˈle/","n.","接力；","the 100 metres relay","一百米接力赛"],["custom","/ˈkʌstəm/","n.","习惯， 习俗","He awoke early, as was his custom.","他很早醒来，这是他的习惯。"],["length","/lɛŋθ/","n.","长， 长度","We measured the length and width of the living room.","我们量了客厅的长和宽。"],["permission","/pɚˈmɪʃən/","n.","允许， 许可， 同意","He asked permission to leave the room.","他请求离开房间的许可。"],["grand","/ɡrænd/","adj.","宏伟的， 盛大的","a grand country house","豪华的乡间大宅"],["schedule","/ˈskedʒʊl/","n/vt.","时刻表；安排， 排定","Then make a schedule or chart of your time .","然后作出一个时间表或图表，你的时间。"],["eastwards","/ˈistwɚdz/","adv.","向东","The ship continued sailing eastwards.","船继续向东行驶。"],["print","/prɪnt/","v.","印刷","Over five million copies of the paper are printed every day.","这份报纸每日印量超过五百万。"],["rewind","/ˌriːˈwaɪnd/","v.","重绕； 回转","Would you please rewind the thread onto the reel?","请你把这些线重新绕在线轴儿上好吗?。"],["although","/ɔlˈðo/","conj.","虽然， 尽管","Although in poor health, she continued to carry out her duties.","尽管身体不好，她仍继续执行任务。"],["material","/məˈtɪrɪəl/","n.","材料， 原料； 物质","materials like wood or stone","木材或石头之类的材料"],["approximately","/əˈprɑksɪmətli/","adv.","近似地， 大约","",""],["encouragement","/ɪnˈkɝɪdʒmənt/","n.","鼓励， 支持， 促进； 起激励作用的事物","With encouragement, Sally is starting to play with the other children.","萨莉受到了鼓励，开始和其他孩子玩起来。"],["universe","/ˈjunɪvɝs/","n.","宇宙","Einstein's equations showed the universe to be expanding.","爱因斯坦的方程式表明宇宙正在扩大。"],["biochemistry","/ˈbaɪoˈkɛmɪstri/","n.","生物化学","...the effects of air pollutants on the biochemistry of plants or animals.","…大气污染物对植物或动物生化过程的影响。"],["iron","/ˈaɪɚn/","v/n.","熨烫；铁；熨斗","Have you ironed my shirt?","我的衬衫你熨过了吗？"],["idiom","/ˈɪdɪəm/","n.","习语， 成语","the new musical idiom","新的音乐风格"],["blanket","/ˈblæŋkɪt/","n.","毛毯， 毯子","I like that nice blanket.","我喜欢那条漂亮的毯子。"],["hug","/hʌɡ/","v/n.","紧抱，拥抱；拥抱","We stood there crying and hugging each other.","我们站在那里哭着互相拥抱。"],["explain","/ɪkˈsplen/","vt.","解释， 说明","He carefully explained the procedure.","他仔细解释了程序。"],["envy","/ˈɛnvi/","n&v.","嫉妒， 羡慕","I really envy you and Ian, you seem so happy together.","我真是羡慕你和伊恩，你俩在一起看起来多幸福。"],["discount","/dɪsˈkaʊnt/","n.","折扣","They are often available at a discount.","它们经常可以以折扣价买到。"],["construct","/kənˈstrʌkt/","vt.","构筑； 建造","There are plans to construct a new road bridge across the river.","有计划要建造一条新的跨河公路桥。"],["hope","/hop/","n&v.","希望","I do hope everything goes well.","我真心希望一切顺利。"],["attempt","/əˈtɛmpt/","vt&n.","试图， 尝试","Weather conditions prevented them from attempting the jump.","天气状况使他们无法尝试跳伞。"],["soon","/sun/","adv.","不久， 很快， 一会儿","It will be dark soon.","天很快就要黑了。"],["division","/dəˈvɪʒən/","n.","除， 除法； 分开， 分割； 分界线","the traditional division of labour (= the way that particular tasks are shared ) between husband and wife","夫妻之间传统的分工"],["tablet","/ˈtæblɪt/","n.","药片","She took a couple of headache tablets .","她吃了几片头痛药。"],["hook","/hʊk/","n/vt.","钩子；钩住， 用钩子挂","Tom hung his coat on the hook behind the door.","汤姆把外套挂在门后的衣钩上。"],["balance","/ˈbæləns/","v/n.","使平衡； 权衡；平衡","Job losses in manufacturing were balanced by job increases in the service sector.","制造业职位减少了，而服务行业就业机会却增加了，正好相抵。"],["bend","/bɛnd/","v.","弯曲； 弯腰， 屈身","Lee bent and kissed her.","李俯下身来亲她。"],["action","/ˈækʃən/","n.","行动","The government must take action (=  do something  ) now to stop the rise in violent crime.","政府现在必须采取行动遏止暴力犯罪的上升。"],["lock","/lɑk/","n/vt.","锁；锁， 锁上","I’m sorry, there isn’t a lock on the bathroom door.","对不起，浴室门上没有锁。"],["stadium","/ˈstedɪəm/","n.","体育场","the new Olympic Stadium","新的奥林匹克体育场"],["fear","/fɪr/","n&v.","害怕， 恐惧， 担忧","She finally ran away for fear that he would kill her.","她最后逃走了，唯恐他会杀她。"],["appreciation","/ə/","n.","欣赏； 评论； 感激","He was presented with a watch in appreciation of his long service.","他获赠一块手表，作为对其长期服务的感谢。"],["electrical","/ɪˈlɛktrɪkl/","adj.","与电有关的， 电气的","The fire was caused by an electrical fault.","大火是电力故障引起的。"],["statue","/ˈstætʃu/","n.","雕像","Churchill’s statue stands outside the parliament building.","丘吉尔的塑像矗立在议会大厦外。"],["sense","/sɛns/","n.","感觉， 意识","Cats have a very acute sense of hearing (= very good, so that they can hear even the smallest sound ) .","猫的听觉非常敏锐。"],["cream","/krim/","n.","奶油； 乳脂","fresh cream","鲜奶油"],["sensitive","/ˈsɛnsətɪv/","adj.","敏感的； 灵敏的； 易被惹恼的","a very sensitive child","一个很敏感的小孩"],["being","/ˈbiɪŋ/","n.","生物， 人； 存在","a law that first came into being in 1912","于1912年制定的一条法律"],["vacant","/ˈvekənt/","adj.","空的， 空白的","Only a few apartments were still vacant.","只有几套公寓仍然空着。"],["afford","/əˈfɔrd/","vt.","买得起； 有时间做； 承担得起； 提供","The room affords a beautiful view over the city.","这房间可以俯瞰城市美景。"],["birthplace","/ˈbɝθˈples/","n.","出生地， 故乡","Stratford-upon-Avon was Shakespeare’s birthplace.","埃文河畔的斯特拉特福是莎士比亚的出生地。"],["dustbin","/ˈdʌstbɪn/","n.","垃圾箱","A bomb planted in a dustbin exploded early today.","一枚安置在一个垃圾桶内的炸弹今天清早爆炸了。"],["impression","/ɪmˈprɛʃən/","n.","印象， 感觉","When we looked around the school we got a very good impression.","我们参观了学校，对它的印象很好。"],["interval","/ˈɪntɚvl/","n.","间歇， 间隔； 幕间休息","He left the room, returning after a short interval with a message.","他离开房间，过了一会儿就带回来一条消息。"],["evaluate","/ɪˈvæljʊˈet/","vt.","评价； 估计","You should be able to evaluate your own work.","你应该能够评估自己的工作。"],["status","/ˈstetəs/","n.","身份， 地位","These documents have no legal status in Britain.","这些文件在英国并无法律效力。"],["upset","/ʌpˈsɛt/","adj/vt.","心烦的，苦恼的；使苦恼","You’re not still upset with me, are you?","你不是还在生我的气吧？"],["dot","/dɑt/","n.","点， 圆点","a pattern of dots","圆点图案"],["deliver","/dɪˈlɪvɚ/","vt.","投递  ； 交付， 给","He delivered a strong warning about the dangers facing the government.","他就政府所面临的危险发出了强烈警告。"],["tailor","/ˈtelɚ/","v/n.","定做；裁缝","",""],["stamp","/stæmp/","n.","[C] 邮票","a 29-cent stamp","一枚 29 美分的邮票"],["skip","/skɪp/","vi.","跳过； 跳读","I decided to skip the first chapter.","我决定跳过第一章。"],["phenomenon","/fəˈnɑmɪnən/","n.","现象","Homelessness is not a new phenomenon .","无家可归已不是什么新现象。"],["mention","/ˈmɛnʃən/","vt/n.","提到，说起；提及","Was my name mentioned at all?","我的名字被提到过吗？"],["mad","/mæd/","adj.","发疯的； 生气的","You make me so mad !","你真把我气坏了！"],["barbecue","/ˈbɑrbɪkju/","n.","烤肉野餐","We had a barbecue on the beach.","我们在海滩上烧烤。"],["file","/faɪl/","n.","文件， 档案","We will keep your details on file (= store them for later use ) .","我们将把你的详细资料存档。"],["laundry","/ˈlɔndri/","n.","洗衣店； 要洗的衣服","She did the laundry (= washed the clothes etc ) and hung it out to dry.","她洗了衣服，然后挂出去晾干。"],["member","/ˈmɛmbɚ/","n.","成员， 会员","The majority of union members voted in favour of a strike.","大多数工会成员投票赞成罢工。"],["brewery","/ˈbruəri/","n.","啤酒厂， 酿酒厂","The Muller family have been making specialist beers at their brewery in Munster for 200 years.","马勒家族已经在他们位于明斯特的啤酒厂专门从事啤酒酿制达200年之久。"],["accumulate","/əˈkjumjəlet/","vt.","堆积， 积累","It is unjust that a privileged few should continue to accumulate wealth.","少数特权阶级继续积聚财富，这是不公平的。"],["crime","/kraɪm/","n.","罪， 罪行","He insisted that he had not committed any crime.","他坚持说自己没有犯任何罪行。"],["stand","/stænd/","vi/vt/n.","站立；承担，忍受；站； 台","It looks like we’ll have to stand – there are no seats left.","看来我们只能站着——没有座位了。"],["surround","/səˈraʊnd/","vt.","围绕， 包围","He glared at the people who surrounded the tent.","他怒视着围住帐篷的那些人。"],["together","/təˈɡɛðɚ/","adv.","一起， 共同","We’ve very much enjoyed working together .","我们在一起工作非常开心。"],["pavement","/ˈpevmənt/","n.","人行道","A small group of journalists waited on the pavement outside her house.","有一小群记者守候在她家外面的人行道上。"],["cigarette","/ˌsɪɡəˈrɛt/","n.","香烟","a packet of cigarettes","一包香烟"],["may","/me/","modal verb/n.","可能，也许；山楂花","I may be late, so don’t wait for me.","我可能会迟到，所以别等我。"],["could","/kəd/","modal verb.","能，会，可以〔can 的过去式〕","By the time she was eight, she could read Greek and Latin.","她八岁时就会读希腊文和拉丁文了。"],["forward","/ˈfɔrwɚd/","adv/adj.","向前， 前进；早的；前进的","He leaned forward , his elbows resting on the table.","他身体前倾，胳膊肘撑在桌子上。"],["bent","/bɛnt/","n/adj.","爱好，嗜好；弯曲的；决心的","a bent nail","弯曲的钉子"],["strike","/straɪk/","vt.","罢工；侵袭；敲；","In many countries, the police are forbidden to strike.","在很多国家，警察是禁止罢工的。"],["health","/hɛlθ/","n.","健康， 卫生","I’m worried about my husband’s health.","我担心我丈夫的健康状况。"],["positive","/ˈpɑzətɪv/","adj.","积极的； 肯定的","the power of positive thinking","正向思考的力量"],["favourite","/ˈfevərɪt/","adj/n.","特别喜爱的；特别喜爱的人","a child’s favourite toy","孩子最喜欢的玩具"],["bless","/blɛs/","vt.","保佑， 降福","He’s always willing to help. Bless him!","他一向乐于助人，愿上帝保佑他！"],["menu","/ˈmɛnju/","n.","菜单","Could we have the menu, please?","请把菜单给我们，好吗？"],["Pacific","/pəˈsɪfɪk/","adj.","太平洋的","...the tiny Pacific island of Pohnpei.","...波纳佩的太平洋小岛。"],["able","/ˈebl/","adj.","有能力的； 有才干的， 有本事的","one of my more able students","我班上能力比较强的学生之一"],["mend","/mɛnd/","v.","修理， 修补","My father used to mend our shoes.","我父亲过去常为我们修补鞋子。"],["return","/rɪˈtɝn/","v/n.","归还，返回；返回， 来回","It was forty five minutes before she returned.","过了45分钟她才回来。"],["mail","/mel/","n/vt.","邮政，邮递；〈美〉 邮寄","You shouldn’t read other people’s mail.","你不应该看别人的信件。"],["conscience","/ˈkɑːnʃəns/","n.","道德心， 良心","Well, at least I can face them all with a clear conscience (= the knowledge that you have done nothing wrong ) .","好吧，至少我可以问心无愧地面对他们所有人。"],["subject","/ˈsʌbdʒɪkt/","n.","题目， 主题； 学科； 主语； 主体","Paul has strong opinions on most subjects.","保罗在大多数问题上观点激烈。"],["use","/juz/","n.","利用； 应用","an exit for use in emergencies","紧急出口"],["bonus","/ˈbonəs/","n.","奖金， 红利","Long-term savers qualify for a cash bonus.","长期储户可获现金红利。"],["feel","/fil/","vi/v/vt.","摸索，寻找；觉得； 摸起来；感觉；触摸；认为","She felt his forehead. Perhaps he had a temperature.","她摸了摸他的额头，他可能发烧了。"],["main","/meɪn/","adj.","主要的","The main reason for living in Spain is the weather.","居住在西班牙的主要原因是天气。"],["thrill","/θrɪl/","n/vt.","激动，兴奋；刺激；使激动； 使胆战心惊","Winning first place must have been quite a thrill.","赢得第一名肯定让人非常激动。"],["serve","/sɝv/","vt.","服务， 招待； 服役","There was only one girl serving customers .","只有一个女孩在接待顾客。"],["cassette","/kəˈsɛt/","n.","[C]卡式盒； 暗盒","",""],["smile","/smaɪl/","n&v.","微笑","her smiling face","她的笑脸"],["fine","/faɪn/","adj/vt.","好的；晴朗的；健康的；处…以罚金","‘How are you?’ ‘Fine, thanks, how are you?’","“你好吗？”“很好，谢谢，你呢？”"],["find","/faɪnd/","vt.","找到， 发现； 感到","I can’t find the car keys.","我找不到汽车钥匙。"],["host","/host/","n/vt.","主人；节目主持人；招待； 主持","Our host greeted us at the door.","主人在门口迎接我们。"],["accelerate","/əkˈsɛləˌret/","vt.","加速， 促进","measures to accelerate the rate of economic growth","加快经济增长速度的措施"],["grain","/ɡren/","n.","谷物， 谷类","big sacks of grain","大袋大袋的粮食"],["international","/ˌɪntəˈnæʃnəl/","adj.","国际的","the response of the international community","国际社会的反响"],["maid","/med/","n.","女仆； 少女","a kitchen maid","厨房女佣人"],["credit","/ˈkrɛdɪt/","n.","信用； 信赖； 贷方","The store agreed to let him have credit.","商店同意他赊购。"],["oxygen","/ˈɑksɪdʒən/","n.","氧； 氧气","The human brain needs to be without oxygen for only four minutes before permanent damage occurs.","人脑缺氧只需4分钟就会造成永久性损伤。"],["regardless","/rɪˈɡɑrdləs/","adv.","不管， 不顾； 不加理会","Despite her recent surgery she has been carrying on regardless.","尽管她最近动了手术，她却一直在不顾一切地继续工作。"],["terrible","/ˈtɛrəbl/","adj.","可怕的； 糟糕的","The hotel was absolutely terrible.","这家宾馆糟糕透了。"],["combine","/kəmˈbaɪn/","v.","联合， 结合","Diets are most effective when combined with exercise.","节食和锻炼相结合是最有效的。"],["upward","/ˈʌpwɚd/","adv.","向上， 往上","They climbed upward along the steep cliffs surrounding the village.","他们沿着环绕村庄的陡峭悬崖向上爬。"],["waste","/west/","vt/n.","浪费；废弃物； 粪便","Leaving the heating on all the time wastes electricity.","让暖气整天开着是浪费电力。"],["citizen","/ˈsɪtɪzn/","n.","公民， 市民","We need our schools to teach students to be good citizens.","我们需要学校把学生培养为好公民。"],["occur","/əˈkɝ/","vi.","发生， 出现","A third of accidental deaths occur in the home.","有三分之一的意外死亡发生在家里。"],["comedy","/ˈkɑmədi/","n.","喜剧","a career in stand-up comedy","单口喜剧表演职业"],["pleasant","/ˈplɛznt/","adj.","令人愉快的， 舒适的","It had been a pleasant evening.","那是个愉快的夜晚。"],["difficult","/ˈdɪfəkəlt/","adj.","难的； 艰难的； 不易相处的","a difficult question","难解的问题"],["pressure","/ˈprɛʃɚ/","n.","压； 压力； 压强","They are putting pressure on people to vote yes.","他们正在向民众施加压力，要求他们投赞成票。"],["sort","/sɔrt/","v/n.","分类，拣选；种类， 类别","The eggs are sorted according to size.","这些鸡蛋是按大小分类的。"],["fill","/fɪl/","v.","填空； 装满； 充满","He poured her a drink, then filled his own glass.","他给她倒了一杯，然后将自己的杯子斟满。"],["dentist","/ˈdɛntɪst/","n.","牙科医生","Visit your dentist twice a year for a checkup.","每年看两次牙医做检查。"],["numb","/nʌm/","adj.","麻木的","My fingers were so numb I could hardly write.","我的手指麻木得几乎没法写字。"],["feed","/fid/","v.","喂  ， 饲  ； 吃","Have you fed the cat?","你喂猫了吗？"],["forget","/fɚˈɡɛt/","v.","忘记， 忘掉","I’m sorry, I’ve forgotten your name.","对不起，我忘记你的名字了。"],["professor","/prəˈfɛsɚ/","n.","教授","Professor Barclay","巴克利教授"],["convenient","/kənˈvinjənt/","adj.","便利的， 方便的","Mail-order catalogs are a convenient way to shop.","使用邮购目录是一种方便的购物方式。"],["specialist","/ˈspɛʃəlɪst/","n.","专家， 专科医生； 专家； 专业人员","a heart specialist","心脏专科医生"],["compass","/ˈkʌmpəs/","v/n.","包围；指南针","a map and compass","地图和指南针"],["background","/ˈbækɡraʊnd/","n.","背景","Students with a background in chemistry will probably find the course easier.","学过化学的学生可能会觉得这门课程容易些。"],["true","/tru/","adj.","真正的， 确实的； 正确的","No, honestly, it’s a true story .","不，真的，这是一个真实的故事。"],["adolescent","/ˌædəˈlesnt/","adj/n.","青春期的；[C]青少年","It is important that an adolescent boy should have an adult in whom he can confide.","一个青春期男孩应该有一个他能倾吐心声的成年人，这是很重要的。"],["valley","/ˈvæli/","n.","山谷， 溪谷","the San Fernando Valley","圣费尔南多山谷"],["position","/pəˈzɪʃən/","n.","位置； 职位","Our hotel was in a superb central position near St Mark’s Square.","我们的酒店处于极佳的中心位置，在圣马克广场附近。"],["present","/prɪˈzɛnt/","adj/n/vt.","当前的；出席的；礼物， 赠品；赠送； 介绍","the present situation of the millions of people who are suffering poverty and disease","遭受贫困和疾病折磨的数百万人民的现状"],["laughter","/ˈlæftɚ/","n.","笑， 笑声","Foster joined in the laughter.","福斯特也跟着笑了起来。"],["since","/sɪns/","prep.","自从…以来，自从…之后","We’ve been waiting here since two o’clock.","我们从两点钟开始就在这里等了。"],["patent","/ˈpætnt/","n.","专利权","He wants to take out a patent on his new type of dustbin.","他想为他的新型垃圾桶取得专利。"],["belong","/bɪˈlɔŋ/","vi.","属， 附属","The house had belonged to her family for three or four generations.","这座房子属于她家已有三四代了。"],["soul","/sol/","n.","灵魂， 心灵","the immortality of the soul","灵魂的不灭"],["dangerous","/ˈdendʒərəs/","adj.","危险的","laws about dangerous dogs","有关危险犬类的法律"],["certificate","/sɚˈtɪfɪkɪt/","n.","证明， 证明书","a degree certificate","学位证书"],["mess","/mɛs/","v/n.","弄乱；凌乱","He scratched his head and messed his hair even more.","他挠挠头，把头发弄得更乱了。"],["sour","/ˈsaʊɚ/","adj.","酸的","Rachel sampled the wine. It was sour.","雷切尔尝了尝葡萄酒，是酸的。"],["delete","/dɪˈlit/","vt.","删除","His name was deleted from the list.","他的名字从名单上删掉了。"],["stain","/sten/","n.","污点， 瑕疵","Remove stains by soaking in a mild solution of bleach.","用温和的漂白溶液浸泡以去除污渍。"],["breath","/brɛθ/","n.","气息， 呼吸","Slow down, I need to catch my breath.","慢一点，我要喘口气。"],["transform","/trænsˈfɔrm/","v.","转变， 转换","Increased population has transformed the landscape.","人口的增加使景观发生了变化。"],["advise","/ədˈvaɪz/","vt.","忠告， 劝告， 建议","She needed someone to advise her.","她需要有个人给她出主意。"],["repeat","/rɪˈpit/","vt.","重说， 重做； 重复","Can you repeat your question?","你能重复一遍你的问题吗？"],["physical","/ˈfɪzɪkl/","adj.","身体的； 物理的； 客观存在的","She was in constant physical pain.","她一直感到身上疼痛。"],["make","/mek/","vt.","制造， 做； 使成为","I’m going to show you how to make a box for your tools.","我来教你怎么做一个箱子存放工具。"],["microwave","/ˈmaɪkrəˈwev/","n.","微波","I’ll heat it up in the microwave.","我来把它用微波炉热一热。"],["rooster","/ˈrustɚ/","n.","公鸡","",""],["brochure","/broˈʃʊr/","n.","小册子","a holiday brochure","度假手册"],["master","/ˈmæstɚ/","vt/n.","精通，掌握；主人； 硕士","the skills needed to master a new language","掌握一门新语言所需的技能"],["extraordinary","/ɪkˈstrɔrdənerɪ/","adj.","非常的； 非凡的","It took an extraordinary amount of work.","这费了相当多的功夫。"],["witness","/ˈwɪtnɪs/","v/n.","目击，作证；证人， 目击者","Several residents claim to have witnessed the attack.","几位居民称目击了袭击事件。"],["conventional","/kənˈvɛnʃənl/","adj.","惯例的， 传统的； 常规的","Internet connections through conventional phone lines are fairly slow.","通过传统的电话线来连接因特网速度很慢。"],["regulation","/ˌrɛɡjəˈleʃən/","n.","规则， 规章","There seem to be so many rules and regulations these days.","如今好像条条框框很多。"],["due","/du/","adj.","预期的； 约定的","Any money due you will be sent by cheque through the post.","应该支付给你的款项将会以支票邮寄给你。"],["ripen","/ˈraɪpən/","v.","成熟","The apples were ripening on the trees.","树上的苹果都熟了。"],["puzzle","/ˈpʌzl/","v/n.","迷惑， 困扰；难题；谜","a question that continues to puzzle scientists","一直困扰科学家的问题"],["evident","/ˈɛvɪdənt/","adj.","明显的， 显然的","Bob ate his lunch with evident enjoyment.","显然鲍勃吃午饭吃得津津有味。"],["accommodation","/ə/","n.","住处；工作场所","The price for the holiday includes flights and accommodation.","度假的价格包括机票和住宿。"],["authentic","/ɔˈθɛntɪk/","adj.","真的， 可信的","an authentic work by Picasso","毕加索的真迹"],["socket","/ˈsɑkɪt/","n.","插座， 插孔； 孔， 穴","a headphone socket","耳机插口"],["biscuit","/ˈbɪskɪt/","n.","饼干","a packet of chocolate biscuits","一包巧克力饼干"],["fence","/fɛns/","n.","栅栏， 篱笆","Villagers say the fence would restrict public access to the hills.","村民们说栅栏将限制公众进入山区。"],["breast","/brɛst/","n.","胸部； 胸怀","Dick cradled her photograph against his breast.","迪克把她的照片轻轻拥在胸前。"],["mercy","/ˈmɝsi/","n.","怜悯","",""],["annoy","/əˈnɔɪ/","vt.","使烦恼， 使生气； 骚扰","What annoyed him most was that he had received no apology.","最令他生气的是没人向他道歉。"],["inform","/ɪnˈfɔrm/","v.","通知， 告诉","They decided to inform the police.","他们决定通知警察。"],["depend","/dɪˈpɛnd/","vi.","依靠， 指望； 取决于","He depended on his writing for his income.","他靠写作谋生。"],["commit","/kəˈmɪt/","v.","犯  ， 干","Women commit fewer crimes than men.","女性犯罪比男性少。"],["about","/əˈbaʊt/","adv/prep.","大约；到处，周围；关于； 在附近， 在周围","I live about 10 miles away.","我住的地方离这里十英里左右。"],["scream","/skrim/","v/n.","尖叫，尖声喊叫；尖叫","After the first few shots, people started screaming.","几声枪响过后，人们开始尖叫起来。"],["sorrow","/sɑro/","n.","悲伤， 悲痛","the family’s joys and sorrows","这家人的喜与悲"],["cure","/kjʊr/","n&v.","治疗， 医好","The new treatment effected a miraculous cure.","这种新疗法产生了奇迹般的疗效。"],["danger","/ˈdendʒɚ/","n.","危险","Danger! No boats beyond this point.","危险！船只不可越过此处。"],["crash","/kræʃ/","v&n.","碰撞； 坠毁","The jet crashed after take-off.","这架喷气式飞机起飞后就坠毁了。"],["cover","/ˈkʌvɚ/","n/vt.","盖子；罩；封面；覆盖； 掩盖； 包括； 报道","His photo’s on the cover of ‘Newsweek’ again.","他的照片又登上《新闻周刊》的封面了。"],["firm","/fɝm/","adj/n.","坚固的； 坚定的；公司，企业","The sofa cushions are fairly firm.","沙发的坐垫很硬。"],["character","/ˈkærɪktɚ/","n.","字符； 性格","He has a cheerful but quiet character.","他的性格乐观文静。"],["reflect","/rɪˈflɛkt/","vt.","反射， 反映","The drop in consumer spending reflects concern about the economy.","消费支出的下降反映出人们对经济的担忧。"],["contribution","/ˌkɒntrɪˈbjuːʃn/","n.","贡献； 捐款","a campaign contribution","竞选捐款"],["above","/əˈbʌv/","adv/adj/prep.","在上面；上面的，上述的；上文的；在…上面，在…上方；多于，大于","Our office is above the hairdresser’s.","我们的办公室在理发店上面。"],["fire","/ˈfaɪr/","n/vt.","火，火灾；点火； 射击； 解雇","The warehouse was completely destroyed by fire.","仓库全给烧毁了。"],["stick","/stɪk/","v/n.","黏住；坚持；木棒， 木棍","So you should stick to it.","所以你要坚持训练哟。"],["orbit","/ˈɔrbɪt/","n.","运行轨道","Mars and Earth have orbits which change with time.","火星和地球的轨道随着时间而发生改变。"],["band","/bænd/","n.","乐队； 带子； 镶边","The band was playing old Beatles songs.","乐队正在演奏披头士的老歌。"],["height","/haɪt/","n.","高， 高度","Sam’s about the same height as his sister now.","萨姆现在身高和他姐姐差不多了。"],["spray","/spreɪ/","v/n.","喷洒；水雾，喷雾","A sprayer hooked to a tractor can spray five gallons onto ten acres.","挂在拖拉机上的喷雾器用五加仑液量能喷洒十英亩地。"],["distinguish","/dɪˈstɪŋɡwɪʃ/","v.","区分， 辨别","Could he distinguish right from wrong?","他能辨别是非吗？"],["outer","/ˈaʊtɚ/","adj.","外部的","Remove the tough outer leaves before cooking.","烹煮之前先把外面的老叶子去掉。"],["invent","/ɪnˈvɛnt/","vt.","发明， 创造","Alexander Graham Bell invented the telephone in 1876.","亚历山大 · 格雷厄姆 · 贝尔于1876年发明了电话。"],["fluent","/ˈfluənt/","adj.","流利的， 流畅的","He spoke in fluent Italian.","他用流利的意大利语讲话。"],["wonderful","/ˈwʌndɚfəl/","adj.","极好的","The cold, misty air felt wonderful on his face.","那凉凉的雾气使他脸上感觉好极了。"],["shortcoming","/ˈʃɔrtkʌmɪŋ/","n.","[C] 缺点， 短处","Peter was painfully aware of his own shortcomings.","彼得痛苦地认识到了自己的短处。"],["haircut","/ˈhɛrkʌt/","n.","理发","Do you like my new haircut?","你喜欢我的新发型吗？"],["howl","/haʊl/","v.","嚎叫， 嚎哭","The dogs howled all night.","那些狗整夜嘷叫。"],["something","/ˈsʌmθɪŋ/","pron.","某事； 某物","There’s something in my eye.","我眼睛里有什么东西。"],["benefit","/ˈbɛnɪfɪt/","n/vt.","利益，好处；使受益","I never had the benefit of a university education.","我从未受过大学教育。"],["flood","/flʌd/","v/n.","淹没， 泛滥；洪水","Towns and cities all over the country have been flooded.","全国各地的城镇都被淹没了。"],["quality","/ˈkwɑləti/","n.","质量； 品质","Much of the land was of poor quality.","很多地的土质很差。"],["intention","/ɪnˈtɛnʃən/","n.","计划， 意图， 目的","They went into town with the intention of visiting the library.","他们进了城，打算参观图书馆。"],["booth","/bʊθ/","n.","岗；  亭或小隔间","a voting booth","投票间"],["rude","/rud/","adj.","无礼的， 粗鲁的， 粗暴的","a rude remark","粗鲁的话"],["enthusiastic","/ɪn/","adj.","热心的， 热情的","an enthusiastic supporter of reform","改革的热心支持者"],["symptom","/ˈsɪmptəm/","n.","症状","One of the most common symptoms of schizophrenia is hearing imaginary voices.","精神分裂症最常见的症状之一是幻听。"],["funeral","/ˈfjunərəl/","n.","葬礼","The funeral will be held at St. Martin’s Church.","葬礼将在圣马丁教堂举行。"],["unique","/jʊˈnik/","adj.","唯一的， 独特的","a unique opportunity to study these rare creatures","研究这些珍稀动物的难得机会"],["except","/ɪkˈsɛpt/","prep.","除…之外","They were all there except me.","除了我以外他们都在那里。"],["ministry","/ˈmɪnɪstri/","n.","部门","...the Ministry of Justice.","…司法部。"],["religious","/rɪˈlɪdʒəs/","adj.","宗教的； 虔诚的","I don’t share her religious beliefs .","她的宗教信仰和我的不同。"],["shelter","/ˈʃɛltɚ/","n.","掩蔽； 隐蔽处","The men took shelter in a bombed-out farmhouse.","那些男人躲在一间被炸毁的农舍里。"],["fact","/fækt/","n.","事实， 现实","",""],["examine","/ɪgˈzæmɪn/","v.","检查， 诊察","A team of divers was sent down to examine the wreck.","一组潜水员被送到水下检查沉船。"],["scan","/skæn/","v.","细看； 浏览； 扫描","She scanned through the paper.","她浏览了一下报纸。"],["fundamental","/ˌfʌndəˈmentl/","adj.","基础的， 基本的","We have to tackle the fundamental cause of the problem.","我们必须解决问题的根本原因。"],["association","/ə/","n.","联合； 联盟； 结交， 交往； 协会","the Association of Master Builders","建筑师协会"],["believe","/bɪˈliv/","vt.","相信； 认为","You shouldn’t believe everything you read.","你不应尽信书上看来的东西。"],["remember","/rɪˈmɛmbɚ/","v.","记得； 纪念","Do you remember Rosa Davies?","你记得罗莎·戴维斯吗？"],["outline","/ˈaʊtlaɪn/","n/vt.","大纲，轮廓；要点，概要；描绘轮廓； 略述","a research proposal outline","研究计划梗概"],["fade","/fed/","v.","褪色； 使消退； 枯萎","All colour fades – especially under the impact of direct sunlight.","所有颜色都会褪色–尤其是在直射阳光的影响下。"],["unless","/ənˈlɛs/","conj.","如果不， 除非","Unless some extra money is found, the theatre will close.","要是不能找到更多资金，剧院将要关闭。"],["glance","/ɡlæns/","v&n.","扫视， 匆匆一看","Trevor and I exchanged a glance.","特雷弗和我相互瞥了一眼。"],["free","/fri/","adj.","自由的， 空闲的； 免费的","Admission is free for children under 9.","九岁以下儿童免费入场。"],["equality","/ɪˈkwɑləti/","n.","平等， 同等， 均等","...equality of the sexes.","…性别平等。"],["mix","/mɪks/","v.","混合， 搅拌","Oil and water don’t mix.","油和水不相融。"],["ought","/ɔt/","aux/vi.","应该，应当；大概","All of us ought to go.","我们大家都应该去。"],["dictation","/dɪkˈteʃən/","n.","听写","I hate doing French dictations .","我讨厌做法语听写。"],["crayon","/kreən/","n.","蜡笔； 蜡笔画","",""],["honour","/ˈɔnə/","vt/n.","尊敬，给予荣誉；荣誉， 光荣","In a marriage, you need to honour one another.","婚姻中双方应该互相尊重。"],["bother","/ˈbɑðɚ/","vt.","烦扰， 打扰","Danny, don’t bother Ellen while she’s reading.","丹尼，埃伦看书的时候不要去打扰她 。"],["expression","/ɪkˈsprɛʃən/","n.","表情； 表达法， 表达方式","Student leaders are demanding greater freedom of expression (= the right to say what you think without being punished ).","学生领袖要求得到更多的言论自由。"],["middle","/ˈmɪdl/","adj/n.","中部的， 中间的， 中级的；中间，当中","driving in the middle lane of the motorway","在高速公路的中间车道上行驶"],["childhood","/ˈtʃaɪldhʊd/","n.","幼年时代， 童年","I had a very happy childhood.","我的童年很快乐。"],["though","/ðo/","conj&adv.","虽然， 可是， 尽管","Two heart attacks in a year. It hasn’t stopped him smoking, though.","一年里心脏病发作了两次，可是那也没让他把烟戒掉。"],["thorough","/ˈθʌrəʊ/","adj.","彻底的","The doctor gave him a thorough check-up.","医生给他做了一次全面的体检。"],["appeal","/əˈpil/","n&v.","呼吁， 请求","The girl’s family have made a public appeal for help to try and catch her killer.","那名遇害女孩的家人吁请公众协助捉拿凶手。"],["everyday","/ˈɛvrɪde/","adj.","日常的","the problems of everyday life","日常生活中的问题"],["stay","/ste/","v/n.","保持，停止，阻止；逗留","Rollings will stay as chairman this year.","罗林斯今年将继续担任主席一职。"],["appear","/əˈpɪr/","vi.","出现； 看来， 似乎","Police have found what appear to be human remains.","警方发现了疑似人体遗骸的东西。"],["face","/fes/","n/vt.","脸；面容；表情；面子；正面；面向； 面对， 朝； 正视； 面临","She had a beautiful face.","她面容秀美。"],["abandon","/əˈbændən/","vt.","放弃","How could she abandon her own child?","她怎么能抛弃自己的孩子呢？"],["congratulation","/kən/","n.","祝贺，恭贺","letters of congratulation","祝贺信"],["inspire","/ɪnˈspaɪɚ/","v.","鼓舞， 激励； 启示","We need someone who can inspire the team.","我们需要一个能鼓舞团队士气的人。"],["afraid","/əˈfred/","adj.","害怕的， 恐惧的","There’s no need to be afraid.","没有必要害怕。"],["progress","/ˈprɑɡrɛs/","vi/n.","进展； 进行；进步， 上进","I asked the nurse how my son was progressing.","我询问护士我儿子身体恢复得如何。"],["geometry","/dʒɪˈɑmətri/","n.","几何学","...the very ordered way in which mathematics and geometry describe nature.","…数学和几何学描述自然的条理性。"],["invite","/ɪnˈvaɪt/","vt.","邀请； 招待","I’m afraid I wasn’t invited.","恐怕我没有受到邀请。"],["open","/ˈopən/","adj/v.","公开的；开着的；打开； 公开","He threw the door open and ran down the stairs.","他猛地打开门，往楼下跑去。"],["devote","/dɪˈvot/","vt.","奉献； 致力； 专心","He decided to devote the rest of his life to scientific investigation.","他决定把余生奉献给科学研究。"],["agent","/ˈedʒənt/","n.","代理商","Our agent in Rio deals with all our Brazilian business.","我们在里约热内卢的业务代表处理我们在巴西的全部业务。"],["treat","/trit/","vt.","对待， 看待； 治疗","It was difficult to treat patients because of a shortage of medicine.","由于缺少药物，很难给病人治病。"],["abortion","/əˈbɔrʃən/","n.","流产； 堕胎","She decided to have an abortion .","她决定做人工流产。"],["bishop","/ˈbɪʃəp/","n.","主教","the Bishop of Durham","达勒姆郡的主教"],["suffering","/ˈsʌfərɪŋ/","n.","痛苦，苦难","the suffering of the refugees after the war","战后难民所遭受的苦难"],["afterward","/ˈæftərwərd/","adv.","后来","Shortly afterward, police arrested four suspects.","之后不久，警方逮捕了４名嫌疑犯。"],["reputation","/ˌrepjuˈteɪʃn/","n.","名誉， 名声","Alice Munro has a reputation for being a very depressing writer.","艾丽斯•门罗有文风抑郁的名声。"],["project","/prəˈdʒɛkt/","n.","项目， 工程","The project aims to provide an analysis of children’s emotions.","该计划旨在对儿童情绪作出分析。"],["inside","/ˈɪnˈsaɪd/","adv/prep.","在里面， 在内部；在…里面，在…之内","The jewels were locked away inside the safe.","珠宝锁入了保险箱。"],["independence","/ˌɪndɪˈpendəns/","n.","独立","The country has made great advances since independence.","该国自独立以来发展迅速。"],["presentation","/ˌpreznˈteɪʃn/","n.","演示， 演出； 呈现， 展示","We will begin a series of presentations to help the public fully understand our system.","我们将进行一系列的说明，帮助公众充分了解我们的制度。"],["whenever","/wɛnˈɛvɚ/","conj.","无论何时","They were always there by you, whenever you needed them.","无论何时你需要他们，他们总是在你身边。"],["dynasty","/ˈdaɪnəsti/","n.","朝代， 王朝","The Habsburg dynasty ruled in Austria from 1278 to 1918.","哈布斯堡王朝在1278至1918年间统治奥地利。"],["bark","/bɑrk/","v/n.","〔狗〕吠叫；狗叫声，吠声","I barked my shin against the step.","我在台阶上蹭破了胫部。"],["greedy","/ˈgridi/","adj.","贪婪的","a greedy and selfish society","一个贪婪自私的社会"],["awkward","/ˈɔkwɚd/","adj.","笨拙的； 难使用的","I hoped he would stop asking awkward questions .","我希望他不要再问令人难堪的问题。"],["bare","/bɛr/","adj/vt.","赤裸的；使赤裸；露出","a ragged child with bare feet","一个衣衫褴褛、光着脚的小孩"],["ruin","/ˈruɪn/","v.","毁坏；毁灭","This illness has ruined my life.","这个病毁掉了我的生活。"],["mutton","/ˈmʌtn/","n.","羊肉","...a leg of mutton.","…一条羊腿。"],["celebrate","/sɛləˌbret/","v.","庆祝","It’s Dad’s birthday and we’re going out for a meal to celebrate.","今天是爸爸的生日，我们打算出去吃饭庆祝一下。"],["admirable","/ˈædmərəbl/","adj.","令人钦佩的； 极好的","an admirable achievement","令人钦佩的成就"],["please","/pliz/","v/int.","使人高兴， 令人满意；请","a business that wants to please its customers","希望让顾客满意的一家公司"],["look","/lʊk/","vi/n.","看， 瞧； 看起来； 注意；[C]看，瞧","We sneaked out while Jessie’s mom wasn’t looking.","我们趁杰茜的妈妈没有看到，偷偷地溜了出去。"],["offshore","/ˌɒfˈʃɔː/","adj&adv.","近海的， 向海的","offshore oil fields","近海油田"],["fortnight","/ˈfɔrtnaɪt/","n.","两星期","a fortnight’s holiday","十四天的假期"],["scar","/skɑr/","n.","伤疤","He had a long, curved scar on his right cheek.","他的右脸上有一道弯弯的长疤。"],["mountainous","/ˈmaʊntənəs/","adj.","多山的","the mountainous coast of Wales","威尔士多山的海岸"],["inspect","/ɪnˈspɛkt/","vt.","检查； 审视","I got out of the car to inspect the damage.","我下车查看损坏情况。"],["campaign","/kæmˈpen/","vi/n.","参加活动； 作战；战役；竞选活动","Jones ran a good campaign.","琼斯的活动搞得很成功。"],["vital","/ˈvaɪtl/","adj.","重大的， 生死攸关的","The port is vital to supply relief to millions of drought victims.","这个港口至关重要，给数百万旱灾民提供救济物资。"],["conflict","/ˈkɑnflɪkt/","n.","斗争， 冲突","the threat of industrial conflict in the coalfields","煤田发生劳资纠纷的风险"],["allow","/əˈlaʊ/","vt.","允许， 准许","We don’t allow diving in the pool.","泳池内禁止跳水。"],["rough","/rʌf/","adj.","粗糙的； 粗略的","Her hands were rough from hard work.","她的双手因为干重活而变得很粗糙。"],["knock","/nɑk/","n&v.","敲； 打； 击","I knocked and knocked but nobody answered.","我把门敲了又敲，但无人回应。"],["mass","/mæs/","n.","众多，大量；","The war is strongly supported by the mass of the population.","这场战争得到了大多数人的有力支持。"],["rule","/rul/","n/vt.","规则，规定；统治；统治； 支配","There are no hard and fast rules (= clear and definite rules ) about what to wear to classes.","对于上课着装并没有硬性规定。"],["proper","/ˈprɑpɚ/","adj.","恰当的， 合适的","Everything was in its proper place (= where it should be ) .","每样东西都放在恰当的位置。"],["update","/ˌʌpˈdeɪt/","vt&n.","现代化； 更新","plans to update manufacturing procedures","更新生产流程的计划"],["amateur","/ˈæmətər/","adj/n.","业余爱好的；业余爱好者","...professional athletes and amateur runners.","…专业运动员和业余赛跑运动员。"],["poisonous","/ˈpɔɪzənəs/","adj.","有毒的； 有害的； 致命的","Some mushrooms are extremely poisonous.","一些蘑菇有剧毒。"],["condemn","/kənˈdɛm/","vt.","谴责， 声讨","Politicians were quick to condemn the bombing.","政治家们立即对爆炸事件进行了谴责。"],["assistance","/əˈsɪstəns/","n.","援助， 帮助","We offer financial assistance to students.","我们向学生提供经济援助。"],["bitter","/ˈbɪtɚ/","adj.","有苦味的； 痛苦的； 严酷的","Enjoy the beer’s bitter taste as you slowly drink it.","慢慢地喝这啤酒，细细品尝它的苦味。"],["speed","/spid/","v/n.","加速；速度","An ambulance sped her to the hospital.","一辆救护车把她快速送往医院。"],["gesture","/ˈdʒɛstʃɚ/","n.","姿势； 手势","Luke made an obscene gesture with his finger.","卢克用手指做了一个下流的手势。"],["admit","/ədˈmɪt/","v.","承认； 准许","‘Okay, so maybe I was a little bit scared,’ Jenny admitted.","“行了，也许我是有点害怕。”珍妮承认道。"],["common","/ˈkɑmən/","adj.","普通的； 公共的； 共有的","Heart disease is one of the commonest causes of death.","心脏病是最常见的死因之一。"],["interest","/ˈɪntrəst/","n/vt.","兴趣，趣味；利息；使产生兴趣","I watched the first few episodes, but soon lost interest.","我看了前几集，但很快就失去了兴趣。"],["wonder","/ˈwʌndɚ/","v/n.","想知道；对…感到惊讶；奇迹","What are they going to do now, I wonder ?","我想知道，他们现在打算怎么办呢？"],["sleepy","/ˈslipi/","adj.","想睡的， 困倦的， 瞌睡的","The warmth from the fire made her feel sleepy.","暖洋洋的炉火使她昏昏欲睡。"],["sneeze","/sniz/","n&vi.","打喷嚏","She started coughing and sneezing.","她开始咳嗽、打喷嚏。"],["bath","/bɑːθ/","n.","[C] 洗澡； 浴室； 澡盆","After a week of camping, I really needed a bath.","我露营了一个星期，实在得洗个澡了。"],["every","/ˈɛvri/","adj.","每一， 每个的； 每…","His every utterance will be scrutinized.","他说的每句话都会被细查。"],["mask","/mæsk/","v/n.","戴面具； 掩饰；口罩，面罩；遮盖物","Dina lit a cigarette, trying to mask her agitation.","黛娜点燃了一支烟，试图掩饰她的不安。"],["thermos","/ˈθɝməs/","n.","热水瓶","How about a thermos to keep the tea warm?","热水瓶怎么样？可以给茶保温。"],["summary","/ˈsʌməri/","n.","[C] 摘要， 概要","A brief summary is given on a separate sheet.","摘要另写一页。"],["apply","/əˈplaɪ/","v.","申请； 应用","We need to apply for planning permission to build a garage.","我们建车库需要申请规划许可。"],["overlook","/ˌəuvəˈluk/","vt.","俯瞰； 远眺","Our room overlooks the ocean.","我们的房间可以俯视大海。"],["politician","/ˌpɒləˈtɪʃn/","n.","政治家","politicians who are trying to get the minority vote","努力争取少数族群选票的政治家"],["taxpayer","/ˈtæks/","n.","纳税人","The proposal could cost the taxpayer (= all ordinary people who pay tax ) another £18m a year.","这个提议也许又要让纳税人一年多花1,800万英镑。"],["indeed","/ɪnˈdid/","adv.","确实， 实在","The blood tests prove that Vince is indeed the father.","验血证明文斯确实是父亲。"],["seagull","/ˈsiɡʌl/","n.","海鸥","The sound of seagull carry her back to childhood holidays by the sea.","她听到海鸥的叫声就回忆起童年时在海边度假的情景。"],["artificial","/ˌɑːtɪˈfɪʃl/","adj.","人造的； 非天然的","artificial flowers","假花"],["disagree","/ˌdɪsəˈgriː/","vi.","意见不一致， 持不同意见","The statements of several witnesses disagree.","几名证人的证词不一致。"],["comment","/ˈkɑmɛnt/","v/n.","评论； 注释；评论","So far, Mr. Cook has not commented on these reports.","到目前为止，库克先生还未对这些报告进行过评论。"],["step","/stɛp/","v/n.","走；跨步；脚步； 台阶","Mr. Ives? Please step this way (= walk in the direction I am showing you ) .","是艾夫斯先生吗？请这边走。"],["forever","/fɚˈɛvɚ/","adv.","永远地， 永恒地","I wanted that moment to last forever .","我希望那一刻成为永远。"],["mark","/mɑːk/","v/n.","做记号， 标记；标记；分数","I’ve marked the pages you need to look at.","我把你需要看的几页做了记号。"],["base","/bes/","n/vt.","根据地；底部；以…为基础， 基于…","India has a good scientific research base.","印度有良好的科研基础。"],["employ","/ɪmˈplɔɪ/","vt.","雇用","The factory employs over 2,000 people.","这家工厂雇用了2,000多名员工。"],["trend","/trɛnd/","n.","倾向， 趋势； 时尚","The current trend is towards more part-time employment.","当前的趋势是雇用更多的兼职人员。"],["achievement","/əˈtʃivmənt/","n.","[U] 完成， 达到； [C] 成就， 成绩","His great achievement is to make all the players into a united team.","他的伟大成就在于把所有选手组织成一支团结的队伍。"],["whole","/hol/","adj.","完整的， 所有的","You have your whole life ahead of you!","你有一辈子要过呢！"],["fair","/fɛr/","adj/n.","公平的；晴朗的；白皙的；集市， 展览会","Why does Eric get to go and I don’t? It’s not fair!","为什么埃里克能去我不能？这不公平！"],["during","/ˈdʊrɪŋ/","prep.","在…期间， 在…过程中","During the summer she worked as a lifeguard.","夏天她当过救生员。"],["balcony","/ˈbælkənɪ/","n.","阳台； 包厢","Has your flat got a balcony?","你的公寓有阳台吗？"],["revolution","/ˈrɛvəˈlʊʃən/","n.","革命， 变革","the French Revolution of 1789","1789年法国大革命"],["mop","/mɑp/","v/n.","用拖把拖地；拖把","She carried on mopping the floor.","她继续用拖把拖地。"],["consist","/kənˈsɪst/","vi.","由…组成","My diet consisted almost exclusively of chocolate-covered cookies and glasses of milk.","我的饮食几乎只包含裹上巧克力的曲奇饼和一杯杯牛奶。"],["preparation","/ˌprepəˈreɪʃn/","n.","准备， 预备； 准备工作， 准备措施","This dish is good for dinner parties because much of the preparation can be done ahead of time.","这道菜适合宴会，因为很多准备工作可以事先做好。"],["relation","/rɪˈleʃən/","n.","关系； 亲属","The price the meat is sold for bears no relation to (= is not connected to ) the price the farmer receives.","肉的售价和农民拿到的价格无关。"],["reliable","/rɪˈlaɪəbl/","adj.","可靠的","a birth control method that is cheap and reliable","既便宜又可靠的避孕方法"],["loss","/lɔs/","n.","丧失； 损耗","The company is closing down two of its factories, leading to 430 job losses .","公司要关闭其中的两家工厂，这将造成430人失业。"],["relate","/rɪˈlet/","v.","有关； 涉及","I don’t understand how the two ideas relate.","我不明白这两个观点有什么联系。"],["typhoon","/taɪˈfʊn/","n.","台风","They have received notice of a typhoon approaching.","他们已收到台风即将来临的预报。"],["decoration","/ˌdekəˈreɪʃn/","n.","装饰， 修饰； 勋章","Christmas decorations","圣诞节装饰物"],["eggplant","/ˈɛɡplænt/","n.","茄子","I have eggplant and tomatoes.","我吃茄子和西红柿。"],["zip","/zɪp/","v/n.","拉开拉链，拉上拉链；拉链","‘I’ll see you tomorrow,’ said John, zipping his jacket.","“明天见。”约翰边说边拉上外套的拉链。"],["profession","/prəˈfɛʃən/","n.","职业； 专业","people who work in the professions","从事专业性工作的人"],["still","/stɪl/","adv/adj.","仍然， 还；静止的，平静的","I still haven’t finished painting the spare room.","我还没粉刷完那间空房间。"],["worn","/wɔrn/","adj.","破烂的， 损坏的","a worn patch on the carpet","地毯上一小块磨破的地方"],["arise","/əˈraɪz/","vi.","起来， 升起； 出现","A crisis has arisen in the Foreign Office.","外交部出现了危机。"],["dizzy","/ˈdɪzi/","adj.","头晕目眩的","The heat and the champagne made him feel dizzy .","高温和香槟酒使他感到眩晕。"],["work","/wɝk/","v/n.","工作； 运作； 奏效；工作；著作","Sally isn’t working tomorrow.","萨莉明天不上班。"],["lose","/luz/","vt.","失去， 丢失","I’ve lost my appetite.","我已经没有了胃口。"],["agree","/əˈɡri/","v.","同意； 应允","Teenagers and their parents rarely agree.","十几岁的孩子跟父母意见很少一致。"],["fail","/fel/","v.","失败； 不及格； 衰退","It looks likely that the peace talks will fail.","看来和平谈判可能会失败。"],["toward","/tɔrd/","prep.","向， 朝， 对于","",""],["enjoyable","/ɪnˈdʒɔɪəbl/","adj.","愉快的； 有趣的","Games can make learning more enjoyable.","游戏可以寓教于乐。"],["anyone","/ˈɛnɪˈwʌn/","pron.","任何人， 无论谁","Anyone could win tonight.","今晚任何人都可能赢。"],["convince","/kənˈvɪns/","vt.","使确信， 使信服","Her arguments didn’t convince everyone, but changes were made.","她的论点不能说服每个人，但还是引起了一些变化。"],["pride","/praɪd/","v/n.","自豪， 自夸；自豪，骄傲","a restaurant that prides itself on speed of service","以服务速度为骄傲的餐馆"],["emperor","/ˈɛmpərɚ/","n.","皇帝","I am napoleon, I am emperor… burned it!","我就是拿破仑，我就是皇帝…烧掉它！"],["word","/wɝd/","n.","单词； 言语； 消息， 音讯","Write an essay of about five hundred words.","写一篇约500字的文章。"],["theory","/ˈθiəri/","n.","理论","Freudian theory has had a great influence on psychology.","弗洛伊德理论对心理学产生过巨大影响。"],["broadcast","/ˈbrɔdkæst/","v/n.","广播；广播节目","The interview was broadcast live across Europe.","这次采访向整个欧洲进行了现场直播。"],["love","/lʌv/","n/vt.","爱；热爱；爱情；爱好；爱， 热爱； 很喜欢","What these kids need is love and support.","这些孩子需要的是关心和支持。"],["extension","/ɪkˈstɛnʃən/","n.","伸展， 延伸","Donald’s been given an extension to finish his thesis.","唐纳德获准延期完成他的论文。"],["signature","/ˈsɪgnətʃɚ/","n.","签名","Her signature is totally illegible (= cannot be read ) .","她的签字完全无法辨认。"],["steep","/stip/","adj.","险峻的， 陡峭的","The road became rocky and steep.","路变得崎岖陡峭起来。"],["seize","/siz/","v.","抓住","Suddenly he seized my hand.","他突然抓住我的手。"],["literary","/lɪtərɛri/","adj.","文学的","a literary prize","文学奖"],["architect","/ˈɑrkɪtɛkt/","n.","建筑师； 设计师","James Madison was the principal architect of the constitution.","詹姆斯·麦迪逊是该宪法的主设计师。"],["forehead","/ˈfɔrˈhɛd/","n.","前额","...the lines on her forehead.","…她前额上的皱纹。"],["enjoy","/ɪnˈdʒɔɪ/","v.","欣赏， 享受…之乐趣； 喜欢","Sandra enjoys her job in the city.","桑德拉很喜欢她在城里的这份工作。"],["privilege","/ˈprɪvəlɪdʒ/","n.","特权， 特别待遇","He had no special privileges and was treated just like every other prisoner.","他不享受特权，待遇和任何其他犯人一样。"],["fireworks","/ˈfaɪr/","n.","烟火","What else ___ you ___(do)? –I ____(watch)the fireworks and dragon dances in.","你还做了什么？-我在街上观看了烟花和舞龙。"],["substitute","/ˈsʌbstɪtut/","vt.","替换","Michael Owen had to be substituted after 20 minutes on the field.","迈克尔·欧文上场 20 分钟后，不得不被换下。"],["foreign","/ˈfɔrən/","adj.","外国的","foreign students","外国学生"],["across","/əˈkrɔs/","prep.","横过， 穿过","",""],["uniform","/junəˌfɔrm/","n.","制服","The police wear dark blue uniforms.","警察穿深蓝色制服。"],["fall","/fɔl/","v/n.","落，降落；跌倒；秋季","The tree was about to fall.","那棵树快要倒下了。"],["identity","/aɪˈdɛntəti/","n.","身份； 一致","The identity of the killer is still unknown.","凶手的身份仍未查明。"],["violate","/ˈvaɪəlet/","vt.","违反， 干扰","34 protesters were arrested for violating criminal law.","34名抗议者因违反刑法而被逮捕。"],["federal","/ˈfɛdərəl/","adj.","中央的 ， 联邦的","Switzerland is a federal republic.","瑞士是一个联邦共和国。"],["event","/ɪˈvɛnt/","n.","事件， 大事； 竞赛","one of the most important events in the history of mankind","人类历史上最重大的事件之一"],["academy","/əˈkædəmi/","n.","学院","the American Academy of Arts and Letters","美国艺术和文学学会"],["wherever","/wɛrˈɛvɚ/","conj.","无论何处； 任何地方","He would keep in touch with us wherever he was .","他无论在什么地方，总是与我们保持联系。"],["reward","/rɪˈwɔrd/","n.","奖赏； 报答； 报酬； 回报","The school has a system of rewards and punishments to encourage good behaviour.","学校有奖惩制度以鼓励良好行为。"],["include","/ɪnˈklud/","vt.","包含， 包括","Does the price include postage?","这个价格包含邮费吗？"],["alongside","/əˈlɔŋˈsaɪd/","adv&prep.","在旁边； 沿着","A car drew up alongside .","一辆车在旁边停了下来。"],["swallow","/ˈswɑlo/","vt/n.","吞下；咽下；燕子","He swallowed the last of his coffee and asked for the bill.","他喝完最后一口咖啡，要求结账。"],["agency","/ˈedʒənsi/","n.","代理处， 经销处","a UN agency responsible for helping refugees","负责为难民提供帮助的联合国机构"],["abstract","/ˈæbstrækt/","adj/n.","抽象的；抽象；概要","By the age of seven, children are capable of thinking in abstract terms .","儿童到了七岁就具有抽象思维的能力。"],["agenda","/əˈdʒɛndə/","n.","议程","The Republicans have stuck to their conservative agenda.","共和党人坚持自己的保守议题。"],["opinion","/əˈpɪnjən/","n.","看法， 见解","When choosing an insurance policy it’s best to get an independent opinion.","选择保险时，最好听听专家的独立意见。"],["altogether","/ˌɔːltəˈgeðə/","adv.","总共","There were five people altogether.","总共有五个人。"],["appearance","/əˈpɪrəns/","n.","出现， 露面； 容貌","It was his first public appearance since the election.","这是选举后他首次公开露面。"],["culture","/ˈkʌltʃɚ/","n.","文化","We speak Danish at home so that the boys don’t lose touch with their language and culture.","我们在家说丹麦语，这样男孩子们就不会脱离他们的语言和文化。"],["devotion","/dɪˈvoʃən/","n.","奉献， 奉献精神","...devotion to the cause of the people and to socialism.","…对于人民的事业和社会主义的献身。"],["prefer","/prɪˈfɝ/","vt.","宁愿  ； 更喜欢","This type of owl prefers a desert habitat.","这种猫头鹰更喜欢沙漠的生活环境。"],["perfect","/ˈpɝfɪkt/","adj.","完美的， 极好的","His English was perfect.","他的英语很地道。"],["butcher","/ˈbʊtʃər/","vt/n.","屠宰，残杀；肉店； 屠夫","Pigs were butchered, hams were hung to dry from the ceiling.","猪被宰杀了，火腿吊在屋顶下风干。"],["float","/flot/","v.","漂浮， 浮动","I looked up at the clouds floating in the sky.","我仰望着天上的浮云。"],["pole","/pol/","n.","杆， 电线杆； 极","a telephone pole","电话线杆"],["minority","/maɪˈnɔrəti/","n.","少数； 少数民族","Gaelic is still spoken in Ireland by a tiny minority.","爱尔兰仍有极少数人在说盖尔语。"],["tight","/taɪt/","adj&adv.","紧的","tight jeans","紧身牛仔裤"],["space","/spes/","n.","空白处； 空地； 空间； 太空","How much space is there on each disk?","每张磁盘有多大容量？"],["reference","/ˈrɛfrəns/","n.","涉及； 参考； 证明书","a comprehensive list of references","详尽的参考书目清单"],["arrange","/əˈrendʒ/","vt.","安排， 布置","Contact your local branch to arrange an appointment.","请联络当地分部安排预约。"],["from","/frʌm/","prep.","从； 从…起； 距； 来自","How do you get from here to Colchester?","从这里到科尔切斯特怎么走？"],["alley","/ˈæli/","n.","小巷； 弄堂； 胡同","The alley led to the railway bridge.","这条小巷通往铁路桥。"],["discover","/dɪˈskʌvɚ/","vt.","发现， 找到","The body was discovered in a field.","尸体是在一块田地里找到的。"],["bench","/bɛntʃ/","n.","长凳； 工作台","We sat on a park bench.","我们坐在公园的长椅上。"],["commitment","/kəˈmɪtmənt/","n.","承诺， 许诺； 保证； 献身； 投入","Are you ready to make a long-term commitment ?","你是否准备好作出长久的承诺？"],["excite","/ɪkˈsaɪt/","vt.","刺激； 使兴奋， 使激动","His playing is technically brilliant, but it doesn’t excite me.","他的演奏技巧娴熟，但并不让我激动。"],["rhyme","/raɪm/","v/n.","押韵； 作诗；韵，押韵","The song has rhyming couplets (= pairs of lines that end in words that rhyme ) .","这首歌有同韵的对句。"],["spade","/sped/","n.","铲子； 纸牌中的黑桃","the queen of spades","黑桃王后"],["revision","/rɪˈvɪʒən/","n.","复习， 温习； 修订","I know I haven’t done enough revision for tomorrow’s exam.","我知道我对明天的考试准备不足。"],["qualification","/ˌkwɒlɪfɪˈkeɪʃn/","n.","资格， 条件； 资格证书","He left school without any qualifications.","他离校时没有拿到任何文凭。"],["collision","/kəˈlɪʒən/","n.","碰撞； 冲突","",""],["bridegroom","/ˈbraɪdɡrum/","n.","新郎","Her bridegroom is a handsome young man.","她的新郎是一个英俊的年轻人。"],["repair","/rɪˈpɛr/","vt/n.","修理，修补；纠正；恢复；修理， 修补","Dad was up the ladder, repairing the roof.","爸爸在梯子上修补屋顶。"],["advice","/ədˈvaɪs/","n.","忠告， 劝告， 建议","You should have followed my advice.","你真该听我的建议。"],["frequent","/ˈfrikwənt/","adj.","经常的， 频繁的","Trains rushed past at frequent intervals .","火车频频驶过。"],["insure","/ɪnˈʃʊr/","v.","确保； 给…保险","Have you insured the contents of your home?","你给家庭财产投保了吗？"],["elder","/ˈɛldɚ/","adj/n.","年长的；长者， 前辈","Sarah is the elder of the two.","两人当中萨拉年纪较长。"],["error","/ˈɛrɚ/","n.","错误","an error message","出错信息"],["windy","/ˈwɪndi/","adj.","多风的","It’s too windy for a picnic.","风太大，不适合野餐。"],["Oceania","/ˌəuʃiˈɑːniə/","n.","大洋洲","Oceania is a separate landmass, but it is separated from Asia by very shallow water.","大洋洲是一块单独的陆地，但它与亚洲之间只隔着很浅的海域。"],["public","/ˈpʌblɪk/","adj/n.","公共的，公众的，国家的；公众","We have to show that publishing this story is in the public interest (= helpful or useful to ordinary people ) .","我们必须证明刊登这篇报道有利于公众。"],["spend","/spɛnd/","vt.","度过； 花费","I can’t afford to spend any more money this week.","这星期我没有能力花更多的钱了。"],["barbershop","/ˈbɑrbɚˈʃɑp/","n.","理发店","a barbershop quartet","男声四重唱"],["track","/træk/","n.","小道； 足迹； 轨道","To run a mile, you have to run four circuits of the track.","跑一英里要绕跑道四圈。"],["value","/ˈvælju/","n/vt.","价值，益处；估价， 评价","the nutritional value of cereal","谷类食物的营养价值"],["foggy","/ˈfɔːɡi/","adj.","有雾的， 多雾的","a foggy day in November","11月的一个雾天"],["quantity","/ˈkwɑntəti/","n.","数量","Your work has improved in quantity and quality this term.","这学期你的作业在完成数量和质量上都有提高。"],["fortune","/ˈfɔrtʃən/","n.","财产； 运气","I had the good fortune to work with a brilliant head of department.","我有幸与一位出色的部门主管共事。"],["advantage","/ədˈvæntɪdʒ/","n.","优点， 好处","Younger workers tend to be at an advantage (=  have an advantage  ) when applying for jobs.","年轻点的工人申请工作时往往处于优势地位。"],["instead","/ɪnˈstɛd/","adv.","代替， 顶替","You probably picked up my keys instead of yours.","你可能没拿你的钥匙而错拿了我的。"],["rush","/rʌʃ/","vi.","冲， 奔跑","A small girl rushed past her.","一个小女孩从她身边匆匆经过。"],["command","/kəˈmænd/","n&v.","命令","Shoot when I give the command .","我一下命令就开枪。"],["expensive","/ɪkˈspɛnsɪv/","adj.","昂贵的， 高消费的","the most expensive restaurant in town","城里最贵的餐馆"],["cloudy","/ˈklaʊdi/","adj.","多云的， 阴天的","a cloudy night with some light rain","伴有些许小雨的多云的夜晚"],["compulsory","/kəmˈpʌlsərɪ/","adj.","必修的； 义务的","the threat of compulsory redundancies","强制性裁员的威胁"],["trade","/tred/","n/vt.","贸易；买卖","international trade agreements","国际贸易协定"],["dessert","/dɪˈzɝt/","n.","甜点， 甜食","She had homemade ice cream for dessert.","她吃了些自制冰淇淋当餐后甜点。"],["round","/raʊnd/","adv/adj/prep.","转过来；圆的， 球形的；环绕一周，围着","When he turned round I recognised him immediately.","他转过身来，我立即认出了他。"],["ambassador","/æmˈbæsədɚ/","n.","大使","...the German ambassador to Poland.","…德国驻波兰大使。"],["non-stop","/ˈnɔnˈstɔp/","adj&adv.","不停的， 不断的","Many U.S. cities now have nonstop flights to Aspen.","很多美国城市现在都有飞往亚斯本的直飞航班。"],["temple","/ˈtɛmpl/","n.","庙宇， 寺院","We visited the ruins of the temple.","我们参观了那个庙宇的遗迹。"],["growth","/ɡroθ/","n.","生长； 增长","measures to stimulate economic growth","刺激经济增长的措施"],["vague","/veɡ/","adj.","含糊的， 不清楚的","The governor gave only a vague outline of his tax plan.","州长只是含糊地大致说了一下他的税务计划。"],["communist","/kɑmjʊnɪst/","adj/n.","共产党的， 共产主义的；共产主义者","a communist country","共产主义国家"],["fare","/fɛr/","n.","费用， 票","He could barely afford the fare.","他几乎付不起车费。"],["temporary","/ˈtempəreri/","adj.","暂时的， 临时  的","temporary pain relief","疼痛的暂时缓解"],["desperate","/ˈdɛspərət/","adj.","令人绝望的； 不顾一切的","I had no money left and was desperate.","我身无分文，已经走投无路了。"],["unrest","/ʌnˈrɛst/","n.","不安； 骚动","There is growing unrest throughout the country.","全国各地日益动荡不安。"],["kangaroo","/ˌkæŋgəˈruː/","n.","大袋鼠","What that kangaroo did to this courtyard .","那袋鼠在这院子做了什么。"],["accuracy","/ˈækjərəsi/","n.","准确性","He passes the ball with unerring accuracy.","他传球准确无误。"],["awful","/ˈɔfl/","adj.","糟糕的， 可怕的","The weather was awful.","天气很糟糕。"],["handy","/ˈhændi/","adj.","便利的； 手边的； 附近的","I always keep my gun handy just in case.","我总是随身带着枪以防万一。"],["urge","/ɝdʒ/","vt.","催促， 力劝","The charity urged quick action.","慈善机构敦促迅速采取行动。"],["via","/ˈvaɪə/","prep.","经， 经过， 经由","We flew to Athens via Paris.","我们经由巴黎飞往雅典。"],["score","/skɔ/","v/n.","得分；[Ｃ]得分，分数；二十；许多，很多","Great cheers went up when he scored in the final minute of the game.","当他在比赛的最后一分钟得分时，人群爆发出了雷鸣般的欢呼。"],["poor","/pʊər/","adj.","贫穷的， 可怜的； 差的","The soil in this area is very poor.","这一地区土壤很贫瘠。"],["graduate","/ˈɡrædʒuˌet/","v/n.","毕业；毕业生； 研究生","When the boys graduated from high school, Ann moved to a small town in Vermont.","男孩们中学毕业后安迁到了佛蒙特州的一座小镇。"],["visual","/ˈvɪʒʊəl/","adj.","视力的， 视觉的","Artists translate their ideas into visual images.","画家把自己的思想转换成视觉画面。"],["absent","/ˈæbsnt/","adj.","缺席的， 不在的","The dull, absent look on her face implied boredom.","她脸上呆滞、茫然的神情说明她觉得无聊了。"],["rag","/ræɡ/","n.","破布， 抹布","He wiped his boots dry with an old rag.","他用一块旧布把他的靴子擦干。"],["because","/bɪˈkɔz/","conj.","因为","We didn’t enjoy the day because the weather was so awful.","那天我们很不尽兴，因为天气实在太糟。"],["near","/nɪr/","adv/adj/prep.","附近， 邻近；近的；在…附近，靠近","They live near London.","他们住在伦敦附近。"],["educate","/ˈɛdʒuket/","v.","教育， 培养","The Ormerod School educates handicapped children.","奥默罗德学校的教育对象为残疾儿童。"],["ashamed","/əˈʃemd/","adj.","惭愧的， 害臊的， 羞耻的","Everyone cries sometimes – it’s nothing to be ashamed of.","每个人都会有哭的时候——没什么好难为情的。"],["appendix","/əˈpɛndɪks/","n.","附录， 附属品； 阑尾","Christine had to go into hospital to have her appendix out (=  have it removed  ) .","克里丝蒂娜不得不去医院切除阑尾。"],["instruct","/ɪnˈstrʌkt/","v.","指示； 教导； 通知","Eva went straight to the hotel, as instructed (= as she had been told ).","伊娃按照指示径直去了宾馆。"],["excellent","/ˈɛksələnt/","adj.","极好的， 优秀的","an excellent suggestion","极好的建议"],["fairly","/ˈfɛrli/","adv.","相当； 还算； 公正地","The house had a fairly large garden.","那幢房子有个不小的花园。"],["handwriting","/ˈhændˈraɪtɪŋ/","n.","书法","The address was in Anna's handwriting.","这个地址是安娜的笔迹。"],["raw","/rɔ/","adj.","生的； 未加工的","raw meat","生肉"],["merchant","/ˈmɝtʃənt/","adj/n.","商业的， 商人的；商人，生意人","There's been a big reduction in the size of the merchant fleet in recent years.","近年来商船队的数量大为缩减。"],["retell","/ˌriːˈtel/","vt.","重讲， 重复， 复述","Lucilla often asks her sisters to retell the story.","陆希拉经常叫她的姐姐们重讲那个故事。"],["ray","/re/","n.","光辉， 光线","The room darkened as a cloud hid the sun’s rays.","一朵云挡住了阳光，房间暗了下来。"],["version","/ˈvɝʒn/","n.","译文； 版本","the human version of mad cow disease","疯牛病的人类变体"],["exam","/ɪgˈzæm/","n.","考试， 测试； 检查","At the end of each level, there’s an exam.","在每一级别结束时都有一次考试。"],["stop","/stɑp/","vt/n.","停止；阻止；停；  站","The government tried to stop publication of the book.","政府企图阻止这本书出版。"],["nationality","/ˌnæʃəˈnæləti/","n.","国籍； 民族","people of the same nationality","同国籍的人"],["guess","/ɡɛs/","v.","猜， 猜测； 认为","I’d say he’s around 50, but I’m only guessing.","我想他50岁左右，不过也只是猜测。"],["adolescence","/ˌædəˈlesns/","n.","青春期","Some young people suddenly become self-conscious and tongue-tied in early adolescence.","一些年青人在青春期早期突然变得害羞结舌。"],["aboard","/əˈbɔrd/","prep&adv.","在船上， 上船","They finally went aboard the plane.","他们终于登上了飞机。"],["institute","/ˈɪnstɪtut/","v/n.","建立， 设立；协会；学院","research institutes","研究所"],["poster","/ˈpostɚ/","n.","海报， 广告","A team of volunteers were putting up posters .","一队志愿者正在张贴海报。"],["shortly","/ˈʃɔrtli/","adv.","不久","Ms Jones will be back shortly.","琼斯女士很快就会回来。"],["appropriate","/əˈproprɪət/","adj.","适当的","The timing of the announcement was particularly appropriate .","通告发布的时机很合适。"],["criterion","/kraɪˈtɪriən/","n.","标准， 规则","the criteria we use to select candidates","我们挑选候选人的标准"],["least","/list/","n.","最少， 最少量","At least he didn’t lie to me.","至少他没跟我撒谎。"],["immediately","/ɪˈmidɪətli/","adv.","立即","Mix in the remaining ingredients and serve immediately.","拌入余下的食材，立即上桌。"],["symphony","/ˈsɪmfəni/","n.","交响乐","Bruckner’s Fifth Symphony","布鲁克纳的《第五交响曲》"],["optimistic","/ˌɒptɪˈmɪstɪk/","adj.","乐观的","Andrew took a more optimistic view.","安德鲁抱有更为乐观的想法。"],["sleep","/slip/","n&vi.","睡觉","I usually sleep on my back.","我一般仰卧着睡觉。"],["vocabulary","/vəˈkæbjəlɛri/","n.","词汇， 词汇表","Teachers were impressed by his vocabulary.","他的词汇量给老师们留下了深刻的印象。"],["refuse","/riˈfjʊz/","v.","拒绝， 不愿","She asked him to leave, but he refused.","她叫他走，但他不肯。"],["aspect","/ˈæspɛkt/","n.","方面； 外表","The storm outside gave the room a sinister aspect.","外面的暴风雨使房间里变得阴森可怕。"],["aggressive","/əˈɡrɛsɪv/","adj.","侵略的； 咄咄逼人的","an aggressive form of breast cancer","一种侵袭性乳腺癌"],["close","/kloz/","adv/adj/v.","近， 靠近；近的；亲密的；关， 关闭","an attempt to close the gap between the rich and poor","缩小贫富差距的努力"],["sweep","/swip/","vt.","扫除， 打扫","Bert swept the path in front of the house.","伯特清扫了屋前的小路。"],["website","/ˈwebsaɪt/","n.","网站","For more information on weight loss and healthy eating, visit our website.","有关减肥和健康饮食的更多信息，请访问我们的网站。"],["learn","/lɝn/","vi/vt.","学，学习；得知，获悉；学， 学习， 学会， 得知","What’s the best way to learn a language?","学习语言的最佳方法是什么？"],["swing","/swɪŋ/","v/n.","挥舞，摆动；秋千","Let your arms swing as you walk.","边走边摆动双臂。"],["ridiculous","/rɪˈdɪkjələs/","adj.","荒谬的， 可笑的","That’s a ridiculous idea!","那主意很荒唐！"],["severe","/səˈvɪr/","adj.","严重的","His injuries were quite severe.","他的伤势很严重。"],["spin","/spɪn/","vt/n.","纺纱；旋转；旋转","The plane’s propellers were spinning.","飞机的螺旋桨在快速旋转。"],["grocery","/ˈɡrosəri/","n.","杂货； 食品； 食品杂货店","They run a small grocery store.","他们经营一家小食品杂货店。"],["communism","/ˈkɑmjʊˈnɪzəm/","n.","共产主义","...the ultimate triumph of communism in the world.","…共产主义在全世界的最终胜利。"],["spit","/spɪt/","v.","吐唾沫； 吐痰","Nick rolled down his window and spat.","尼克摇下窗子，啐了口唾沫。"],["anniversary","/ˌænɪˈvɜːsəri/","n.","周年纪念","Jack and Kim celebrated their twentieth wedding anniversary in January.","1月，杰克和金庆祝了他们的结婚20周年纪念日。"],["register","/ˈrɛdʒɪstɚ/","v/n.","登记， 注册；记录，登记簿","The tanker is registered in Rotterdam.","这艘油轮是在鹿特丹登记的。"],["couple","/ˈkʌpl/","n.","夫妇；  对，  双","a newly married couple","一对新婚夫妇"],["communicate","/kəˈmjunɪket/","v.","交际； 传达 ； 通信","We communicated mostly by e-mail.","我们主要是用电子邮件沟通。"],["eager","/ˈigɚ/","adj.","渴望的， 热切的","He’s a bright kid and eager to learn.","他是个聪明的孩子，热爱学习。"],["evidence","/ˈɛvɪdəns/","n.","证据","Murrow’s evidence was enough to convict Hayes of murder.","默罗的证词足以证明海斯犯了谋杀罪。"],["republic","/rɪˈpʌblɪk/","n.","共和国","the former Federal Republic of Germany","前德意志联邦共和国"],["official","/əˈfɪʃəl/","adj/n.","官方的， 政府的； 公务的；官员；高级职员","an official investigation into the causes of the explosion","对此次爆炸事件原因的官方调查"],["acid","/ˈæsɪd/","adj.","酸的","a juicy apple with a slightly acid flavour","一个多汁、略带酸味的苹果"],["assessment","/əˈsɛsmənt/","n.","估价； 评价","a reading assessment test","阅读评估测试"],["post","/post/","n/vt.","岗位，职位；邮政，邮寄，邮件；投寄； 邮寄； 发布","I applied for the post and was asked to attend an interview.","我申请了那个职位，被要求参加面试。"],["agricultural","/ˌægrɪˈkʌltʃərəl/","adj.","农业的","Farmers struggling for survival strip the forests for agricultural land.","为生存而挣扎的农民们把森林伐光来作农业用地。"],["leave","/liv/","v.","离开； 留下； 遗忘","My baby gets upset when I leave the room.","我一离开房间宝宝就会不安。"],["duck","/dʌk/","v/n.","躲避； 浸入水中；鸭子","If she hadn’t ducked, the ball would have hit her.","如果她没有弯腰躲闪的话，那个球就可能击中她了。"],["cottage","/ˈkɑtɪdʒ/","n.","小屋； 村舍； 小别墅","a country cottage","乡间小屋"],["tiresome","/ˈtaɪɚsəm/","adj.","令人厌烦的， 讨厌的","the whole tiresome business of filling out the forms","填写表格这套烦人事"],["finish","/ˈfɪnɪʃ/","v.","结束， 做完","You can’t go anywhere until you’ve finished your homework.","没完成家庭作业前你哪儿也不能去。"],["discrimination","/dɪ/","n.","歧视","laws to prevent discrimination","防止歧视的法律"],["female","/ˈfimel/","adj/n.","女性的，雌性的；女性， 女人","female voters","女性选民"],["melon","/ˈmɛlən/","n.","甜瓜","...some juicy slices of melon.","…几片多汁的甜瓜。"],["swift","/swɪft/","adj.","快的， 迅速的","My letter received a swift reply.","我的信很快就得到了回复。"],["add","/æd/","v.","添加， 增加","If the mixture seems dry, add water.","如果混合物看上去干，加点水。"],["minister","/ˈmɪnɪstɚ/","n.","部长； 牧师","a senior Cabinet minister","资深的内阁部长"],["need","/nid/","v/vt/n.","必须；需要modal；需要， 需求","He needs to see a doctor straightaway.","他有必要马上去看医生。"],["cruel","/kruəl/","adj.","残忍的， 残酷的； 无情的","The prisoner was a hard cruel man.","这个囚犯残酷无情。"],["erupt","/ɪˈrʌpt/","v.","喷发， 爆发","Violence erupted after police shot a student during the demonstration.","警察向示威人群中的一名学生开枪，暴乱随之发生。"],["shade","/ʃed/","n.","阴凉处， 树荫处","a plant that needs a lot of shade","喜阴植物"],["often","/ˈɔ:fn/","adv.","经常地","She often works at the weekend.","她周末经常要上班。"],["gather","/ˈɡæðɚ/","v.","聚集； 采集","A crowd gathered to watch the fight.","一群人聚拢来围观打架。"],["insist","/ɪnˈsɪst/","v.","坚持， 坚决认为","Stay for supper – I insist!","留下来吃晚餐——一定的！"],["article","/ˈɑrtɪkl/","n.","文章； 东西； 冠词","The paper’s leading article (=  the main article  ) described the government as weak.","该报社论称政府软弱。"],["respect","/rɪˈspɛkt/","n/vt.","尊敬，尊重；方面；尊敬， 尊重","The boys showed a complete lack of respect for authority.","这些男孩子根本无视权威。"],["ache","/ek/","vi/n.","疼痛；痛， 疼痛","His feet were aching from standing so long.","他站了那么久，双脚隐隐作痛。"],["loose","/lus/","adj.","松散的； 宽松的","a loose floorboard","松动的地板"],["therefore","/ˈðɛrfɔr/","adv.","因此， 所以","Their car was bigger and therefore more comfortable.","他们的车大些，所以更舒适些。"],["exchange","/ɪksˈtʃendʒ/","n&v.","交换； 交流； 兑换","Four of my cassettes for your Madonna CD is a fair exchange.","我用四盒磁带换你的麦当娜激光唱片很公平。"],["adjustment","/əˈdʒʌstmənt/","n.","调整， 调节； 校正","a period of adjustment","一段调整期"],["hesitate","/ˈhɛzətet/","v.","犹豫， 踌躇","Some parents hesitate to take these steps because they suspect that their child is exaggerating.","一些家长迟迟不肯采取这些措施，因为他们怀疑自己的孩子在夸大其词。"],["hardly","/ˈhɑrdli/","adv.","几乎不","My parents divorced when I was six, and I hardly knew my father.","我六岁时父母离婚，我对父亲几乎一无所知。"],["bored","/bɔrd/","adj.","无聊的， 厌烦的","He was easily bored.","他很容易感到厌烦。"],["trust","/trʌst/","vt&n.","相信， 信任， 信赖","At first there was a lack of trust between them.","起初，他们之间缺乏信任。"],["income","/ˈɪnkʌm/","n.","收入， 所得","low-income families","低收入家庭"],["private","/ˈpraɪvɪt/","adj.","私人的； 私营的； 秘密的","Morris has a private jet.","莫里斯拥有一架私人喷气式飞机。"],["technical","/ˈtɛknɪkl/","adj.","技术的， 工艺的","Our staff will be available to give you technical support .","有我们的员工向你提供技术支持。"],["companion","/kəmˈpænɪən/","n.","同伴， 同事","For ten years he had been her constant companion .","十年来他一直陪伴她左右。"],["choose","/tʃuz/","vt.","选择； 决定","It took us ages to choose a new carpet.","我们挑选新地毯花了很长时间。"],["directory","/dəˈrɛktəri/","n.","姓名地址录； 公司名录","I couldn’t find your number in the telephone directory.","我在电话簿上找不到你的电话号码。"],["peaceful","/ˈpisfəl/","adj.","和平的， 安宁的","We had a peaceful afternoon without the children.","孩子们不在，我们度过了一个宁静的下午。"],["prevent","/priˈvɛnt/","v.","防止， 阻止","The rules are intended to prevent accidents.","这些规定旨在预防事故。"],["behave","/bɪˈhev/","v.","表现； 行为得体","She behaved in a very responsible way .","她表现得很有责任心。"],["accomplish","/əˈkɑmplɪʃ/","vt.","完成， 达到","We have accomplished all we set out to do.","所有计划要做的事情，我们都已完成。"],["disturbing","/dɪˈstɝbɪŋ/","adj.","令人不安的； 引起烦恼的","a disturbing increase in the crime rate","令人不安的犯罪率增幅"],["engine","/ˈɛndʒɪn/","n.","发动机， 引擎","Is the engine running smoothly?","发动机运转平稳吗？"],["photographer","/fəˈtɑgrəfɚ/","n.","摄影师","a fashion photographer","时装摄影师"],["end","/ɛnd/","v/n.","结束，终止；终点； 结束","I think we’ll end there for today.","我看我们今天就到这儿吧。"],["mistake","/mɪˈstek/","v/n.","弄错；错误","She mistook my meaning entirely.","她完全误解了我的意思。"],["pour","/pɔr/","v.","倾泻， 不断流出","He got up and poured himself another drink.","他站起身来，给自己又倒了一杯。"],["message","/ˈmɛsɪdʒ/","n.","消息， 留言； 要旨","I got a message you were trying to reach me.","我得到了一条留言，说你在设法联系我。"],["praise","/prez/","n&vt.","赞扬， 表扬","Jane was praised by her teacher.","简受到了老师的表扬。"],["significance","/sɪɡˈnɪfɪkəns/","n.","意义， 重要性","Ideas about the social significance of religion have changed over time.","有关宗教的社会意义的观念已随时间的流逝发生了改变。"],["special","/ˈspɛʃəl/","adj.","特别的； 专门的","a special place in the classroom for reading","教室里的阅读专区"],["scissors","/ˈsɪzɚz/","n.","剪刀","a pair of scissors","一把剪刀"],["environment","/ɪnˈvaɪrənmənt/","n.","环境","Some of these chemicals are very damaging to the environment.","这些化学品中有些对环境非常有害。"],["truth","/trʊθ/","n.","事实； 真理","How do we know you’re telling us the truth?","我们怎么知道你告诉我们的是真话？"],["clone","/klon/","n&v.","克隆， 无性繁殖","...the world's first human clone.","…世界上第一个克隆人。"],["betray","/bɪˈtre/","vt.","出卖， 背叛","He felt that she had betrayed him.","他感觉她背叛了自己。"],["pronounce","/prəˈnaʊns/","v.","发音","How do you pronounce your name?","你的名字怎么念？"],["family","/ˈfæməlɪ/","n.","家； 家人","Do you know the family next door?","你认识隔壁那家人吗？"],["swear","/swɛr/","v.","发誓， 诅咒","Don’t swear in front of the children.","不要在孩子们面前说粗话。"],["gift","/ɡɪft/","n.","赠品； 礼物； 天赋， 才能","The earrings were a gift from my aunt.","这副耳环是我姑姑送给我的礼物。"],["atmosphere","/ˈætməsfɪr/","n.","气氛； 大气","The hotel had a lovely relaxed atmosphere .","那家宾馆的气氛轻松愉快。"],["decorate","/ˈdɛkəret/","v.","装饰， 修饰","The bathroom is decorated in green and yellow.","浴室里是用绿色和黄色装潢的。"],["education","/ˌedʒuˈkeɪʃn/","n.","教育， 培养","She also hopes her children will get a good education.","她也希望她的孩子可以受到良好的教育。"],["occupation","/ˌɒkjuˈpeɪʃn/","n.","职业， 工作； 占领， 占据","Please state your name, address and occupation.","请写明你的姓名、地址和职业。"],["tendency","/ˈtɛndənsi/","n.","[C] 倾向， 趋势","children with aggressive or anti-social tendencies","具有攻击性倾向或反社会倾向的儿童"],["slim","/slɪm/","adj.","苗条的， 纤细的","a slim young woman","身材苗条的年轻女子"],["arithmetic","/əˈrɪθmətɪk/","n.","算术","...teaching the basics of reading, writing and arithmetic.","…教授读、写、算的基本知识。"],["caption","/ˈkæpʃən/","n.","标题； 字幕","The local paper featured me standing on a stepladder with a caption, \"Wendy climbs the ladder to success.\"","当地的报纸刊登了一幅我站在活梯上的特写，下面写着：“温迪登上了成功之梯。”"],["rid","/rɪd/","vt.","使…摆脱","The proposals are an attempt to rid the country of political corruption.","这些提议是使该国摆脱政治腐败的一种尝试。"],["moral","/ˈmɔrəl/","adj/n.","道德的，精神的；道德； 寓意","It is easy to have an opinion on a moral issue like the death penalty for murder.","对于判谋杀犯死刑这种涉及伦理道德的问题，有个观点并非难事。"],["number","/ˈnʌmbɚ/","n.","数字， 号码； 数量","They wrote various numbers on a large sheet of paper.","他们在一张大纸上写下了很多不同的数字。"],["explode","/ɪkˈsplod/","v.","爆炸； 爆发","The device was thrown at an army patrol but failed to explode.","炸弹投向了陆军巡逻队，但没有爆炸。"],["greengrocer","/ˈɡrinɡrosɚ/","n.","蔬菜水果商","Elsa is telephoning the greengrocer. The plumber is putting a new seat on the toilet bowl.","埃尔莎在给蔬菜水果商打电话，管子工在马桶上装了一个新座垫。"],["punish","/ˈpʌnɪʃ/","vt.","惩罚， 处罚","Smacking is not an acceptable way of punishing a child.","要惩罚孩子，不应该用打的方式。"],["casual","/ˈkæʒʊəl/","adj.","偶然的， 不经意的； 非正式的； 临时的","Jean felt more comfortable in casual clothes .","琼穿上便服感到更舒服。"],["decline","/dɪˈklaɪn/","v.","下降； 衰败； 倾斜； 谢绝","Offered the position of chairman, Smith declined, preferring to keep his current job.","对担任主席的邀约，史密斯拒绝了，他宁愿留在现在的职位上。"],["narrow","/ˈnæro/","adj.","狭窄的","The stairs were very narrow.","楼梯非常狭窄。"],["judge","/dʒʌdʒ/","v/n.","判断，评价；裁判， 法官","You should never judge a person by their looks.","决不要以貌取人。"],["similar","/ˈsɪməlɚ/","adj.","相似的， 像","We have similar tastes in music.","我们对音乐的品位相近。"],["contradict","/ˈkɑntrəˈdɪkt/","v.","同…矛盾， 同…抵触","The witness statements contradict each other and the facts remain unclear.","目击者的说法互相矛盾，真相依然未明。"],["Catholic","/kæθəlɪk/","adj.","天主教的","...the Catholic Church.","…天主教会。"],["shape","/ʃep/","n/vt.","形状，外形；使成形； 制造， 塑造","What shape is the table?","那张桌子是什么形状的？"],["nothing","/ˈnʌθɪŋ/","pron.","没有东西， 没有什么； 无关紧要的东西","Nothing ever happens in this town.","这镇上从来都不会发生什么特别的事。"],["headmistress","/ˌhɛdˈmistrəs/","n.","女校长","She is the deputy headmistress of the school.","她是那所学校的代理校长。"],["anyhow","/ˈɛnɪˈhaʊ/","adv.","不管怎样","",""],["whistle","/ˈwɪsl/","v/n.","鸣笛， 吹口哨；口哨声；汽笛声","Adam whistled happily on his way to work.","亚当在上班路上愉快地吹着口哨。"],["handle","/ˈhændl/","vt/n.","处理；柄， 把手","I handled most of the paperwork.","大部分文书工作是我做的。"],["chain stores","","n.","连锁店","Competing with the chain stores of the mall, there is now a collection of stalls selling African and Asian food.","现在有许多商店与商场里的连锁商店竞争卖亚非特产。"],["crossing","/ˈkrɔsɪŋ/","n.","十字路口； 人行横道","You must give way to any pedestrians on the crossing.","必须让人行横道上的行人先行。"],["tough","/tʌf/","adj.","结实的； 棘手的","It was a tough race.","比赛打得很艰难。"],["exit","/ˈɛɡzɪt/","n.","出口","We made for the nearest exit.","我们走向最近的出口。"],["system","/ˈsɪstəm/","n.","体系， 系统","an alarm system","警报系统"],["giraffe","/dʒəˈræf/","n.","长颈鹿","I/ you/ we/ they like giraffe.","我/你/我们/他们喜欢长颈鹿。"],["spot","/spɑt/","n/vt.","斑点，污点；场所，地点；沾上污渍， 弄脏； 认出， 发现","a nice quiet spot on the beach","海滩上一个安静的好地方"],["aid","/ed/","v/n.","帮助；援助，救护；辅助器具","an index to aid the reader","方便读者的索引"],["other","/ˈʌðɚ/","pron&adj.","其他的， 另外的","They were just like any other young couple.","他们那时就和其他任何年轻夫妇一样。"],["aim","/em/","v/n.","计划； 瞄准； 针对；目的","Denver aimed his gun but did not shoot.","丹佛举枪瞄准，但是没有射击。"],["against","/əˈɡɛnst/","prep.","对着； 反对","Every council member voted against the proposal.","每位市政会委员都对该提案投了反对票。"],["confident","/ˈkɑnfɪdənt/","adj.","自信的； 确信的","Despite her disability, Philippa is very confident.","菲莉帕虽然有残疾，却很自信。"],["cell","/sɛl/","n.","细胞； 蜂房； 电池","cancer cells","癌细胞"],["swell","/swɛl/","v.","肿胀， 增大","Her ankle was already starting to swell.","她的脚踝已经开始肿起来了。"],["courage","/ˈkɝrɪdʒ/","n.","勇气， 胆略","Sue showed great courage throughout her illness.","休在生病期间表现出了极大的勇气。"],["local","/ˈloʊkl/","adj.","当地的， 地方的","local hospital","当地医院"],["remind","/rɪˈmaɪnd/","vt.","提醒， 使记起","Yes, I’ll be there. Thanks for reminding me.","是的，我会去那里的。 谢谢提醒。"],["crew","/krʊ/","n.","全体人员","The plane crashed, killing two of the crew and four passengers.","飞机坠毁，造成两名机组人员和四名乘客死亡。"],["valid","/ˈvælɪd/","adj.","有效的","a valid credit card","有效信用卡"],["defeat","/dɪˈfit/","vt.","击败； 战胜","They hoped to defeat the enemy at sea.","他们希望在海上击败敌人。"],["spear","/spɪr/","n.","矛","After the rehearsal, the weary mechanic repaired the gears with shears and spear.","排练完后，疲倦的机修工用剪刀和矛修理了齿轮装置。"],["encourage","/ɪnˈkɝrɪdʒ/","vt.","鼓励， 激励","I want to thank everyone who has encouraged and supported me.","我要感谢每一位鼓励和支持过我的人。"],["electronic","/ɪˌlɛkˈtrɑnɪk/","adj.","电子的","electronic games","电子游戏"],["vacation","/veˈkeʃən/","n.","假期， 休假","We’re planning a vacation in Europe.","我们正计划去欧洲度假。"],["speak","/spik/","v.","说， 讲； 谈话； 发言","I was so shocked I couldn’t speak.","我震惊得说不出话来。"],["share","/ʃɛr/","v/n.","分享，共同使用；一份； 股份","We don’t have enough books so you’ll have to share.","我们书不够，所以你们得合着用。"],["bureaucratic","/ˌbjuərəˈkrætɪk/","adj.","官僚政治的","Bureaucratic delays are inevitable.","官僚主义所致的延误是不可避免的。"],["sacred","/ˈsekrɪd/","adj.","宗教的； 庄严的， 神圣的","a sacred vow","神圣的誓言"],["elegant","/ˈɛləgənt/","adj.","文雅的， 雅致的","a tall, elegant young woman","身材高挑、举止优雅的年轻女子"],["outcome","/ˈaʊtˈkʌm/","n.","结果， 成果","People who had heard the evidence at the trial were surprised at the outcome.","在审判过程中听过证词的人都对此结果感到吃惊。"],["curriculum","/kəˈrɪkjələm/","n.","课程","Languages are an essential part of the school curriculum.","语言是学校课程中必不可少的部分。"],["satisfaction","/ˌsætɪsˈfækʃn/","n.","满意","She got great satisfaction from helping people to learn.","她在帮助人们学习的过程中得到很大的满足。"],["sharp","/ʃɑrp/","adj.","尖锐的； 敏锐的； 整点的","Make sure you use a good sharp knife.","你一定要用锋利的好刀。"],["powerful","/ˈpaʊɚfl/","adj.","强有力的， 强大的； 有影响力的","He was one of the most powerful men in Bohemia.","他是波希米亚最有权势的人物之一。"],["slip","/slɪp/","v/n.","溜；滑动；片， 纸片； 滑倒","Ben slipped quietly out of the room.","本悄悄地溜出了房间。"],["future","/ˈfjutʃɚ/","n.","将来","Does this school have a future?","这所学校有前途吗？"],["anchor","/ˈæŋkɚ/","v/n.","抛锚；停泊；锚","Three tankers were anchored in the harbor.","三艘油轮停泊在港口。"],["acquaintance","/əˈkwentəns/","n.","相识， 熟人","She was a casual acquaintance of my family in Vienna.","她是我们家在维也纳的一个交情不深的朋友。"],["novelist","/ˈnɑvlɪst/","n.","小说家","The key to success as a romantic novelist is absolute belief in your story.","一个浪漫派小说家成功的关键在于对自己故事的绝对信念。"],["royal","/ˈrɔɪəl/","adj.","王室的， 皇家的； 第一流的","the royal palace","王宫"],["shake","/ʃek/","vt.","使摇动； 震动","She shook him to wake him up.","她摇摇他，想把他叫醒。"],["eyesight","/ˈaɪsaɪt/","n.","视力， 视觉","He had a problem with his eyesight.","他的视力有问题。"],["semicircle","/ˈsɛmɪsɝkl/","n.","半圆","They sit cross-legged in a semicircle and share stories.","他们盘着腿围成半圆坐在一起讲故事。"],["screen","/skrin/","n.","幕， 荧光屏","a computer with an 18-inch colour screen","带18英寸彩色屏幕的电脑"],["autonomous","/ɔˈtɑnəməs/","adj.","自治的","They proudly declared themselves part of a new autonomous province.","他们自豪地宣布自己是新自治省的一部分。"],["referee","/ˌrefəˈriː/","n.","仲裁人， 调解人； 裁判员","His headmaster agreed to act as his referee.","他的校长同意做他的推荐人。"],["trial","/ˈtraɪəl/","n.","审判； 试验","The trial is due to start next week.","审理定于下周开始。"],["correspond","/ˌkɒrəˈspɒnd/","vi.","通信； 一致； 相当； 协调","The two halves of the document did not correspond.","这份文件的前后两部分不相符。"],["undertake","/ˌʌndəˈteɪk/","vt.","承担； 保证","She undertook the task of monitoring the elections.","她承担了监督选举的任务。"],["insect","/ˈɪnsɛkt/","n.","昆虫","an insect bite","昆虫的叮咬"],["buffet","/bəˈfe/","n.","自助餐","a cold buffet","冷餐会"],["entrance","/(forv.)ɪnˈtræns/","n.","入口； 入场； 入学许可","the initial interview for entrance to the Civil Service","报考公务员的面试初试"],["pregnant","/ˈprɛɡnənt/","adj.","怀孕的","care for pregnant women","孕妇保健"],["all","/ɔl/","adj&pron&adv.","全部","You shouldn’t be sitting here by yourself, all alone.","你不应该一个人孤零零地坐在这儿。"],["always","/ˈɔlwez/","adv.","总是； 一直； 永远","Always lock your bicycle to something secure.","每次都要把自行车锁在牢固的物体上。"],["border","/ˈbɔrdɚ/","n.","边缘； 边境， 国界","writing paper with a black border","饰有黑边的信纸"],["below","/bɪˈlo/","adv/prep.","在下面；在…下面","an animal that lives below ground","生活在地下的动物"],["already","/ɔlˈrɛdi/","adv.","已经","The design of the new house is similar to those that have already been built.","新房的设计与那些已建好的房子相似。"],["touch","/tʌtʃ/","v/n/vt.","触摸，接触；接触；联系；感动","She reached out to touch his arm.","她伸手去碰他的胳膊。"],["shall","/ʃəl/","modal verb.","〔某事〕必定，一定〔发生〕","The truth shall make you free.","真理必令你们得自由。"],["admission","/ədˈmɪʃən/","n.","准许进入； 承认","Reese, by his own admission , lacks the necessary experience.","里斯自己也承认缺乏必要的经验。"],["real","/ˈriəl/","adj.","真实的， 确实的","There is a real danger that the disease might spread.","这种疾病确实有蔓延的危险。"],["expense","/ɪkˈspɛns/","n.","费用， 支出","He borrowed £150,000 and used the money for legal expenses.","他借了15万英镑用于支付律师费。"],["unit","/ˈjunɪt/","n.","单元； 单位","a Russian army unit","俄罗斯陆军分队"],["yell","/jɛl/","vt.","大叫， 呼喊","‘Help me!’ she yelled hysterically.","“救救我！”她歇斯底里地大叫。"],["contemporary","/kənˈtɛmpərɛri/","adj.","当代的； 同时代的","She writes a lot of contemporary music for people like Whitney Houston.","她为惠特尼·休斯敦等人创作大量当代音乐作品。"],["collect","/kəˈlɛkt/","v.","收集， 搜集","After 25 years of collecting recipes, she has compiled them into a cookbook.","她搜集了25年食谱，把它们编成一本烹饪书。"],["dusty","/ˈdʌsti/","adj.","尘土般的； 尘土多的","They started strolling down the dusty road in the moonlight.","他们开始在月光下满是尘土的道路上漫步。"],["amusement","/əˈmjuzmənt/","n.","娱乐， 消遣","What do you do for amusement in this town?","你们镇上有什么消遣？"],["boundary","/ˈbaʊndri/","n.","边界， 分界线","National boundaries are becoming increasingly meaningless in the global economy.","在全球经济中，国界已经变得越来越没有意义。"],["shame","/ʃem/","n.","遗憾的事； 羞愧","She felt a deep sense of shame.","她深感羞耻。"],["rob","/rɑb/","v.","抢夺， 抢劫","They killed four policemen while robbing a bank.","他们抢劫一家银行的时候杀了4名警察。"],["outing","/ˈaʊtɪŋ/","n.","远足； 郊游","One evening, she made a rare outing to the local night club.","一天晚上，她难得地去了一趟当地的夜总会。"],["trick","/trɪk/","n.","[C] 诡计， 把戏","Pretending he doesn’t remember is an old trick of his.","假装不记得是他的老花招了。"],["favour","/ˈfevɚ/","n.","恩惠； 好感； 帮助","I've come to ask you to do me a favour.","我是来请你帮我一个忙的。"],["around","/əˈraʊnd/","adv/prep.","在周围；在附近；大约；掉头；在…周围； 绕着","The whole family was sitting around the dinner table.","全家人围坐在饭桌旁。"],["pollute","/pəˈlut/","vt.","污染","beaches polluted by raw sewage","受未经处理的污水污染的海滩"],["disappoint","/ˈdɪsəˈpɔɪnt/","v.","失望","I hated to disappoint her.","我不愿意让她失望。"],["rot","/rɑt/","v.","腐烂， 腐败","Candy will rot your teeth.","吃糖会腐蚀牙齿。"],["construction","/kənˈstrʌkʃən/","n.","建造， 建设； 建筑物","a road construction project","道路修建计划"],["predict","/prɪˈdɪkt/","v.","预言； 预报","Sales were five percent lower than predicted.","销售额比预期低5%。"],["row","/ro/","v/n.","划船；排，行","Jenny used to row at college (= as a sport ) .","珍妮以前在大学里经常参加划船运动。"],["universal","/ˈjʊnəˈvɝsl/","adj.","普遍的， 全体的","free universal healthcare","免费的全民保健制度"],["abroad","/əˈbrɔd/","adv.","到国外； 在国外","I’ve never lived abroad before.","我以前从未在国外生活过。"],["frontier","/frʌnˈtɪr/","n.","国境， 边界； 前线","a novel about a family’s struggle on the American frontier","描写一家人在美国边远地区奋斗的小说"],["subjective","/səbˈdʒɛktɪv/","adj.","主观的","As a critic, he is far too subjective.","作为评论家，他过于主观。"],["deliberately","/dɪˈlɪbərətli/","adv.","故意地","He deliberately upset her.","他故意惹她不开心。"],["seaweed","/ˈsiˈwid/","n.","海草， 海藻","...seaweed washed up on a beach.","…被冲上海滩的海草。"],["drawer","/drɔr/","n.","抽屉","She took a file from her desk drawer .","她从书桌的抽屉里拿出了一个文件夹。"],["transport","/ˈtrænspɔrt/","n/vt.","运输； 传送器；运输， 传送","commuters who travel on public transport","乘坐公共交通车辆上下班的人"],["specific","/spɪˈsɪfɪk/","adj.","特殊的； 明确的","games suitable for specific age groups","适合特定年龄组的游戏"],["any","/ˈɛni/","pron/adj.","任何一个； 任何一些；任何的；一些","",""],["application","/ˌæpləˈkeʃən/","n.","申请； 申请书","We receive hundreds of job applications each year.","我们每年收到数百封求职信。"],["freezing","/ˈfrizɪŋ/","adj.","冻结的； 极冷的","It’s freezing in this house. Can’t I turn on the heating?","房子里冷极了，我不可以开暖气吗？"],["punctuation","/ˈpʌŋktʃʊˈeʃən/","n.","标点符号","He was known for his poor grammar and punctuation.","他以很差的语法和标点符号使用而出名。"],["acre","/ˈekɚ/","n.","英亩； 田地","They own 200 acres of farmland.","他们拥有200英亩农田。"],["whisper","/ˈwɪspɚ/","n&v.","低语， 私语","You don’t have to whisper, no one can hear us.","你不必轻声轻语，没人听得到我们说话。"],["appetite","/ˈæpəˌtaɪt/","n.","食欲， 胃口","Her husband always had a huge appetite.","她丈夫向来胃口极大。"],["until","/ənˈtɪl/","prep&conj.","直到…为止， 在…以前","The ticket is valid until March.","这张票的有效期一直到 3 月份。"],["dull","/dʌl/","adj.","单调无味的； 阴暗的； 迟钝的","Outside the weather was hazy and dull.","外面薄雾朦胧，天色灰暗。"],["clumsy","/ˈklʌmzi/","adj.","笨拙的","A clumsy waiter spilled wine all over her new skirt.","一名笨手笨脚的服务员把葡萄酒洒得她新裙子上到处都是。"],["reason","/ˈrizən/","v/n.","说服， 劝说；理由，原因","She has reason to feel guilty.","她有理由感到内疚。"],["thought","/θɔt/","n.","思考， 思想； 念头","It’s an interesting thought.","这想法很有趣。"],["accurate","/ˈækjərət/","adj.","正确的， 准确的","The brochure tries to give a fair and accurate description of each hotel.","该手册尽量公正、准确地介绍每一家酒店。"],["ring","/rɪŋ/","v/n.","响；打电话；电话铃声； 环形物","He left Washington with the president’s praises ringing in his ears.","他离开了华盛顿，总统的赞扬还在他耳际回响。"],["taste","/test/","n/v.","喜爱，爱好，口味；有…的味道","That gave me a taste for reading.","那使我有了读书的喜好。"],["anywhere","/ˈɛnɪwɛr/","adv.","任何地方","Sit anywhere you like.","你随便坐吧。"],["bargain","/ˈbɑrɡɪn/","v/n.","讨价还价；便宜货，廉价货","They prefer to bargain with individual clients, for cash.","他们更愿意同个人客户洽谈，做现金交易。"],["identification","/aɪˌdentɪfɪˈkeʃn/","n.","辨认， 鉴定； 身份证明","Do you have any identification?","你有什么身份证明文件吗？"],["jam","/dʒæm/","v/n.","阻塞；果酱； 阻塞","He jammed his foot on the accelerator and the car sped off.","他使劲踩下油门，汽车飞驰而去。"],["annual","/ˈænjuəl/","adj.","一年一次的， 每年的","The school trip has become an annual event.","学校组织的旅行成了一年一度的活动。"],["gentle","/ˈdʒɛntl/","adj.","温柔的， 柔和的","Arthur was a very gentle, caring person.","阿瑟是一个非常温柔体贴的人。"],["cheers","/tʃɪrz/","int.","干杯","",""],["boil","/bɔɪl/","v.","沸腾， 烧开； 煮","Put the spaghetti into plenty of boiling salted water.","把意大利面放入大量煮沸的盐水中。"],["sneaker","/ˈsnikɚ/","n.","胶底运动鞋","a pair of white sneakers","一双白色的运动鞋"],["lightning","/ˈlaɪtnɪŋ/","n.","闪电","Two farmworkers were struck by lightning (= hit by lightning ).","两个农民遭闪电击中。"],["remain","/rɪˈmen/","vi/v.","余下，留下；保持， 仍是","The refugees were allowed to remain in the UK.","难民获准留在英国。"],["shabby","/ˈʃæbi/","adj.","破旧的， 衣衫褴褛的； 不公正的， 不讲理的； 低劣的","Hugh’s jacket was old and shabby.","休的夹克衫又旧又破。"],["amaze","/əˈmez/","vt.","惊奇， 惊叹， 震惊","Dave amazed his friends by suddenly getting married.","戴夫突然结婚，令朋友们非常吃惊。"],["demand","/dɪˈmænd/","n&v.","要求， 需要","Production is still increasing faster than demand.","生产仍比需求增长快。"],["envelope","/ˈenvələup/","n.","信封","envelopes and stamps","信封和邮票"],["slow","/sloʊ/","adj/v.","缓慢的；放慢速度， 减缓","The car was travelling at a very slow speed.","汽车正以非常慢的速度行驶。"],["turkey","/ˈtɝki/","n.","火鸡","roast turkey","烤火鸡"],["grade","/ɡred/","n.","等级； 学年； 成绩， 分数","The best grades of tea are expensive.","最上等的茶叶价格很贵。"],["deposit","/dɪˈpɑzɪt/","n&v.","存 ； 堆积","...underground deposits of gold and diamonds.","…黄金和钻石的地下矿床。"],["tasty","/ˈtesti/","adj.","味道好的","a simple but tasty meal","简单而可口的饭菜"],["telescope","/ˈtɛləˌskop/","n.","望远镜","What is the range of this telescope?","这架望远镜的有效距离多大?。"],["flash","/flæʃ/","v/n.","闪光，  闪现；闪，闪光，转瞬间","Lightning flashed overhead.","头顶上电光闪闪。"],["skillful","/ˈskɪlfəl/","adj.","熟练的； 技艺精湛的； 灵巧的","",""],["continent","/ˈkɑntɪnənt/","n.","大陆， 大洲","the continents of Asia and Africa","亚洲及非洲大陆"],["accuse","/əˈkjuz/","vt.","控告， 谴责","The professor stands accused of (=  has been accused of  ) stealing his student’s ideas and publishing them.","那位教授被指控剽窃学生的观点拿去发表。"],["maybe","/ˈmebi/","adv.","可能， 大概， 也许","Maybe it’s all just a big misunderstanding.","也许这只是一个很大的误会。"],["another","/əˈnʌðɚ/","pron/adj.","另一个；另一；别的","We have another hypothesis as well.","我们提出了另一种假说。"],["guarantee","/ˌgærənˈtiː/","vt&n.","保证， 担保","The bank will only lend me money if my parents guarantee the loan.","只有我父母作担保，银行才会给我贷款。"],["algebra","/ˈældʒɪbrə/","n.","代数学","",""],["recommend","/ˈrɛkəˈmɛnd/","v.","推荐","I recommend the butter chicken - it’s delicious.","我推荐黄油焗鸡，非常好吃。"],["acquire","/əˈkwaɪr/","vt.","获得； 学到","Manning hoped to acquire valuable works of art as cheaply as possible.","曼宁希望以尽可能低的价格买到有价值的艺术品。"],["worth","/wɝθ/","adj.","值得的； 价值…","You should not deprecate your own worth.","你不应该贬低你自己的价值。"],["helicopter","/ˈhɛlɪkɑptɚ/","n.","直升机","You can helicopter to the island.","你可以乘坐直升机去那个岛。"],["ripe","/raɪp/","adj.","成熟的， 熟的","Those tomatoes aren’t ripe yet.","那些番茄还没熟。"],["where","/hweə(r)/","adv&conj.","那儿； 何处","Where others might have been satisfied, Dawson had higher ambitions.","别人或许这样就满足了，可道森却有更大的雄心。"],["disabled","/dɪsˈebld/","adj.","残疾的","a support group for parents of disabled children","帮助残障儿童父母的援助团"],["watermelon","/ˈwɔtɚmɛlən/","n.","西瓜","How do you eat watermelon?","你可以怎么吃西瓜呢？"],["arm","/ɑrm/","v/n.","以…装备， 武装起来；手臂；支架","Dave has a broken arm .","戴夫手臂断了。"],["popular","/ˈpɑpjəlɚ/","adj.","流行的， 受欢迎的； 大众的","Hilary was popular at school.","希拉里在学校里很受欢迎。"],["broken","/ˈbrokən/","adj.","弄坏了的， 破碎的","Mind the broken glass.","当心碎玻璃。"],["outwards","/ˈaʊtwɚdz/","adv/adj.","向外，在外；向外的， 外出的","The door opens outwards.","这门是朝外开的。"],["vice","/vaɪs/","prep/n.","副， 次； 代替；恶习；缺陷","Smoking is my only vice.","吸烟是我唯一的恶习。"],["poison","/ˈpɔɪzn/","n.","毒药","Belladonna and red arsenic are deadly poisons .","颠茄和雄黄都是致命的毒物。"],["silly","/ˈsɪli/","adj.","傻的，愚蠢的","Stop asking silly questions.","别再问傻问题了。"],["liberation","/ˌlɪbəˈreɪʃn/","n.","解放","",""],["fortunate","/ˈfɔrtʃənət/","adj.","幸运的， 侥幸的","By a fortunate coincidence, a passer-by heard her cries for help.","所幸正巧有个过路人听到了她的呼救。"],["wrinkle","/ˈrɪŋkl/","n.","皱纹","Her face was a mass of wrinkles.","她的脸上布满皱纹。"],["tour","/tʊr/","n.","[C] 参观， 观光， 旅行","We met on a coach tour in Italy.","我们是在意大利乘长途客车旅游时相识的。"],["persuade","/pɚˈswed/","v.","说服， 劝说； 使相信","He was fairly easily persuaded .","他很轻易就被说服了。"],["call","/kɔl/","n/vt.","叫；电话；称呼； 呼唤； 叫； 给…打电话","It’s cheaper to make calls after 6 pm.","下午6点以后打电话便宜些。"],["consensus","/kənˈsɛnsəs/","n.","一致意见","The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.","欧盟财政部长会议未能就一体化的进度达成共识。"],["such","/sʌtʃ/","adv/pron/adj.","那么，如此；人， 事物；这样的，那样的","I have the confidence because I have such ability!","我有信心，因为我有这样的能力！"],["calm","/kɑm/","adj/v.","镇静的，沉着的；镇静， 沉着","Glen was calm and composed at the funeral.","格伦在葬礼上表现得平静而镇定。"],["boring","/ˈbɔrɪŋ/","adj.","令人厌烦的","Her husband is about the most boring person I’ve ever met.","她丈夫可以说是我见过的最无聊的人。"],["classic","/ˈklæsɪk/","adj.","经典的， 一流的","The Coca-Cola bottle is one of the classic designs of the last century.","可口可乐瓶是上个世纪的经典设计之一。"],["kick","/kɪk/","v&n.","踢","He kicked the door hard.","他用力踢门。"],["absolute","/ˈæbsəlut/","adj.","完全的， 绝对的","I have absolute confidence in her.","我对她充满信心。"],["ask","/æsk/","v.","询问； 要求","‘What’s your name?’ she asked.","“你叫什么名字？”她问道 。"],["canteen","/kænˈtiːn/","n.","餐厅； 食堂","Rennie had eaten his supper in the canteen.","伦尼已在食堂吃过晚饭。"],["describe","/dɪˈskraɪb/","vt.","描写， 叙述","The police asked her to describe the man.","警察叫她描述一下那名男子。"],["suck","/sʌk/","v.","吸， 吮","Don’t suck your thumb, dear.","不要吮大拇指，宝贝。"],["dilemma","/dəˈlɛmə/","n.","进退两难的局面","a moral dilemma","道德上进退两难的窘境"],["wealthy","/ˈwɛlθi/","adj.","富有的","the wealthy nations of the world","世界上的富国"],["strength","/strɛŋθ/","n.","力量， 力气","I’m trying to build up my strength .","我在努力增强体力。"],["dusk","/dʌsk/","n.","黄昏","The street lights go on at dusk.","街灯在黄昏时亮起来。"],["administration","/əd/","n.","管理； 行政部门","We’re looking for someone with experience in administration.","我们正在寻找一个有管理经验的人。"],["run","/rʌn/","vi.","跑， 奔跑； 褪色； 经营， 管理","For a while, she ran a restaurant in Boston.","有一段时间她在波士顿开餐馆。"],["challenging","/ˈtʃælɪndʒɪŋ/","adj.","具有挑战性的","Teaching young children is a challenging and rewarding job.","幼儿教育是一项具有挑战性和有意义的工作。"],["research","/ˈrisɝtʃ/","n.","研究， 调查","Gould was helped in his researches by local naturalists.","古尔德在研究过程中得到了当地博物学家的帮助。"],["debate","/dɪˈbet/","n&v.","讨论， 辩论","the gun-control debate in the US","美国有关控制枪支的争论"],["view","/vju/","n.","看法； 景色","In my view, the country needs a change of government.","依我看，这个国家需要换个政府。"],["either","/ˈiðɚ/","determiner/adv.","〔两者中的〕任何一个；也(不)","There’s tea or coffee – you can have either.","有茶和咖啡，你可任选一种。"],["furniture","/ˈfɝnɪtʃɚ/","n.","〈总称〉 家具","I helped him choose the furniture for his house.","我帮他挑选房子里用的家具。"],["jet","/dʒɛt/","v/n.","喷射；喷气式飞机； 喷射","The president will be jetting off to Germany today.","总统今天要乘喷气式飞机去德国。"],["donate","/ˈdonet/","v.","捐赠， 赠送","people who volunteer to donate blood","自愿献血者"],["helpful","/ˈhɛlpfl/","adj.","有帮助的， 有益的","Thank you for your advice; it’s been very helpful.","谢谢你的建议，它非常有用。"],["dust","/dʌst/","n.","灰尘， 尘土","All the furniture was covered in dust .","所有的家具都蒙上了灰尘。"],["worry","/ˈwʌrɪ/","v&n.","担忧， 烦恼","The heat didn’t seem to worry him.","酷热似乎并没有让他烦恼。"],["cater","/ˈketɚ/","v.","投合； 备办食物","We cater to an exclusive clientele.","我们满足一个特殊客户群的需求。"],["imagine","/ɪˈmædʒɪn/","v.","想象， 设想","‘A very complicated subject, I imagine,’ said Edwin.","“一个非常复杂的问题，我猜想。”埃德温说。"],["attractive","/əˈtræktɪv/","adj.","迷人的， 有吸引力的","an attractive young woman","妩媚动人的年轻女子"],["superb","//suːˈpɜːrb//","adj.","庄重的， 华丽的， 极好的","The food was superb.","食物好吃极了。"],["might","/maɪt/","modal verb/n.","可以〔用于礼貌地提出建议〕；力量；威力；权力","If you need more information, you might try the Internet.","如果你需要更多的信息，可以试试因特网。"],["bleed","/blid/","v.","出血， 流血","Your nose is bleeding.","你的鼻子流血了。"],["catalogue","/ˈkætəlɔɡ/","n.","目录","a mail order catalog","邮购商品目录"],["whatever","/wətˈɛvɚ/","conj&pron.","无论什么","This means that whatever you develop with these two libraries does not have to be open source, but can be proprietary.","这意味着，无论您使用这两个库开发什么软件，该软件不必是开放源码的，可以是专有的。"],["decrease","/dɪˈkris/","v.","减小， 减少","The number of people who have the disease has decreased significantly in recent years.","近年来，这种病的患者人数明显下降。"],["camp","/kæmp/","n&vi.","野营， 宿营","Let’s go back to camp – it’s getting dark.","我们回营地吧，天快黑了。"],["difficulty","/ˈdɪfɪkəlti/","n.","困难， 费力； 异议","If you have any difficulties, give me a call.","如果你遇到困难，就给我打电话。"],["volunteer","/ˌvɒlənˈtɪə/","v/n.","自愿；志愿者","I volunteered my services as a driver.","我主动提出来当司机。"],["everywhere","/ˈɛvrɪwɛr/","adv.","到处","I’ve looked everywhere but I can’t find the map.","我到处都找过了，但就是找不到地图。"],["clothing","/ˈkloðɪŋ/","n.","〈总称〉 衣服","basic necessities such as food and clothing","食物和衣服这类基本的生活必需品"],["aloud","/əˈlaʊd/","adv.","大声地； 出声地","When we were children, our father read aloud to us.","当我们是孩子时，我们的父亲大声地朗读给我们听。"],["thunderstorm","/ˈθʌndɚstɔrm/","n.","雷暴， 雷雨交加","There is a severe thunderstorm warning for some parts of the Southeast.","东南部的地区会有严重的雷暴雨警告。"],["mourn","/mɔrn/","v.","哀痛； 哀悼","Hundreds of people gathered to mourn the slain president.","成百上千人聚集在一起悼念遇刺的总统。"],["next","/nɛkst/","adv/adj/n.","随后，然后，下一步；最近的；紧挨着的，隔壁的；下一次；下一个人","With John here, you never know what will happen next.","有约翰在这里，你永远都不会知道接下来会发生什么事。"],["blind","/blaɪnd/","adj.","瞎的， 盲的","Her mother groped for the back of the chair, her eyes blind with tears.","她妈妈摸索着椅背，她的眼睛被眼泪遮住了视线。"],["nod","/nɑd/","v&n.","点头","I asked her if she was ready to go, and she nodded.","我问她是否已准备好出发，她点了点头。"],["string","/strɪŋ/","n.","细绳， 线， 带","Her key hung on a string around her neck.","她的钥匙穿了根绳子挂在脖子上。"],["import","/ˈɪmpɔt/","n.","进口， 输入","a ban on beef imports","禁止进口牛肉"],["distance","/ˈdɪstəns/","n.","距离","Measure the distance between the two points.","量出两点之间的距离。"],["occupy","/ˈɑkjupaɪ/","vt.","占领， 占据","He occupies the house without paying any rent.","他住在这幢房子里，没有付一分钱房租。"],["submit","/səbˈmɪt/","vt.","提交， 递交","They submitted their reports to the chancellor yesterday.","他们昨天向财政大臣提交了他们的报告。"],["boom","/buːm/","v/n.","发出隆隆声； 兴隆， 使繁荣；繁荣；隆隆声","Business was booming , and money wasn’t a problem.","生意非常兴隆，钱已不是问题。"],["abolish","/əˈbɑlɪʃ/","vt.","废止； 废除","Slavery was abolished in the US in the 19th century.","美国于19世纪废除了奴隶制。"],["absence","/ˈæbsns/","n.","不在， 缺席； 没有","In the absence of any evidence, the police had to let Myers go.","警察没有证据，只好把迈尔斯放了。"],["nearly","/ˈnɪrli/","adv.","将近； 几乎","It took nearly two hours to get here.","到这里花了将近两小时。"],["attract","/əˈtrækt/","v.","吸引； 引起","I’m not usually attracted to blondes.","我一般不喜欢金发女子。"],["show","/ʃo/","v.","给…看，出示，","The man grinned, showing bad teeth.","那男人咧着嘴笑，露出一口坏牙。"],["edition","/ɪˈdɪʃən/","n.","版， 版本","a paperback edition","平装本"],["cautious","/ˈkɔʃəs/","adj.","小心的， 谨慎的","a cautious driver","一位谨慎的司机"],["disappear","/ˈdɪsəˈpɪr/","vi.","消失","At this point the path seemed to disappear altogether (= disappear completely ) .","小路到这里好像完全消失了。"],["perfume","/pɚˈfjum/","n.","香味； 香水","She was wearing the perfume that he’d bought her.","她擦了他买给她的香水。"],["shot","/ʃɑt/","n.","射击， 开枪， 开炮， 射击声； 子弹； 拍摄","He pulled out his rifle and fired three shots.","他拽出步枪开了三枪。"],["conclusion","/kənˈkluʒn/","n.","[C] 结论； 结束","These are the report’s main conclusions.","这些就是这篇报告的主要结论。"],["nor","/nɔr/","conj.","也不","He can neither read nor write (= he cannot read or write ).","他既不会读也不会写。"],["central","/ˈsɛntrəl/","adj.","中心的， 中央的； 主要的","He lives in central London.","他住在伦敦市中心。"],["defend","/dɪˈfɛnd/","vt.","保护， 防御","a struggle to defend our homeland","保卫我们祖国的斗争"],["arrive","/əˈraɪv/","vi.","到达， 达到","Give me a call to let me know you’ve arrived safely.","打个电话给我，告诉我你已平安到达。"],["memorial","/məˈmɔrɪəl/","adj/n.","纪念的；纪念碑，纪念物","A memorial service is being held for her at St. Paul's Church.","一场为她举行的纪念仪式正在圣保罗教堂举行。"],["wag","/wæɡ/","v.","摇动， 摆动","‘You naughty girl!’ Mom said, wagging her finger at me.","“你这个调皮的丫头！”妈妈对我摇了摇手指说道。"],["race","/res/","v/n.","赛跑， 比赛；种族；比赛","In the 10 years I raced in Europe, 30 drivers were killed.","我在欧洲参赛的10年间，有30名车手身亡。"],["introduce","/ˌɪntrəˈdus/","vt.","介绍； 引进","Have you two been introduced? Tom, this is Greg.","有人给你们俩互相介绍了吗？汤姆，这位是格雷格。"],["greet","/ɡrit/","vt.","问候， 向…致敬","She liked to be home to greet Steve when he came in from school.","当史蒂夫从学校回来时，她喜欢在家迎接他。"],["sculpture","/ˈskʌlptʃɚ/","n.","雕塑  ， 雕像","...stone sculptures of figures and animals.","…人物及动物石雕。"],["bond","/bɑnd/","v/n.","黏合； 结合；联结；联结物","It takes less than ten minutes for the two surfaces to bond.","用不了十分钟两个表面就会黏合起来。"],["way","/we/","n.","道路； 方法； 作风","There are several different ways we can tackle this problem.","我们可以用几种不同的方法处理这个问题。"],["target","/ˈtɑrɡɪt/","n.","目标， 对象； 靶子","There is no target date for completion of the new project.","这个新的项目何时完工没有预定日期。"],["wax","/waks/","n.","蜡， 蜡状物","wax crayons","蜡笔"],["grey","/ɡre/","adj.","灰色的； 灰白的","an old lady with grey hair","头发灰白的老太太"],["what","/hwɒt/","pron&adj&conj.","什么","What are you doing?","你在做什么？"],["urban","/ˈɝbən/","adj.","城市的， 市内的","unemployment in urban areas","城市地区的失业状况"],["guidance","/ˈgaɪdns/","n.","引导， 指导","a missile with a sophisticated electronic guidance system","有精密电子制导系统的导弹"],["refer","/rɪˈfɝ/","v.","谈到， 提到","In his speech, he referred to a recent trip to Canada.","在他的讲话中，他提到了最近的加拿大之行。"],["nervous","/ˈnɝvəs/","adj.","紧张不安的， 神经质的","I wish you’d stop looking at me like that. You’re making me nervous.","我希望你不要再那样看着我了，你让我紧张。"],["duty","/ˈdʊti/","n.","责任； 义务； 税","I promise I will do my duty .","我保证会尽到我的责任。"],["risk","/rɪsk/","n/vt.","冒险，风险；冒…的危险","It was a risk, sending a letter to my house.","将信寄到我家是冒险。"],["flame","/flem/","n.","火焰， 光辉","Flames poured out of the windows of the building.","火焰从大楼窗口冒出来。"],["rise","/raɪz/","n.","上升， 上涨","She watched the steady rise and fall of his chest.","她看着他的胸膛均匀地一起一伏。"],["play","/ple/","v/n.","玩；打；播放；玩耍； 戏剧","Kids were playing and chasing each other.","孩子们在互相追逐嬉闹。"],["delicate","/ˈdɛlɪkɪt/","adj.","精巧的， 精致的","a plate with a delicate pattern of leaves","有精致树叶图案的碟子"],["fancy","/ˈfænsi/","adj/n/vt.","奇特的；空想的；空想，假想；想象， 空想","Harry took me to a fancy restaurant for our anniversary.","哈里带我去了一家豪华餐厅，庆祝我们的结婚纪念日。"],["bounce","/baʊns/","v.","使反弹； 跳跃","My father would burst into the kitchen bouncing a tennis ball.","我父亲会拍打着网球闯进厨房。"],["tissue","/ˈtɪʃu/","n.","薄的纱织品； 薄纸；  组织","As we age we lose muscle tissue.","随着年纪的增大，我们会失去一些肌肉组织。"],["decide","/dɪˈsaɪd/","v.","决定， 下决心","Has anything been decided yet?","已经作出什么决定了吗？"],["rent","/rɛnt/","v/n.","租用； 出租；租金","Most students rent rooms in their second year.","大多数学生到二年级时租房居住。"],["when","/hwen/","adv/conj.","在那时；什么时候；当…的时候","Leonard was nine when his father died.","父亲去世时伦纳德九岁。"],["nearby","/ˌnɪəˈbaɪ/","adv/adj.","在附近；附近的","He might easily have been seen by someone who lived nearby.","他可能很容易被住在附近的人看到。"],["carpenter","/ˈkɑːrpəntər/","n.","木匠","Think of yourself as the carpenter. Think about your house.","把你当做一个木匠，好好想想你的房子。"],["modest","/ˈmɑdɪst/","adj.","谦虚的， 谦逊的","You’re too modest! You’ve been a huge help to us.","你太谦虚了！你帮了我们大忙呢。"],["cast","/kæst/","vt/n.","扔，抛；演员表","Sparks leapt as he cast more wood on the fire.","他往火里投进更多的木块，火星四处飞溅。"],["anxious","/ˈæŋkʃəs/","adj.","忧虑的； 焦急的","She gave me an anxious look.","她焦急地看了我一眼。"],["fan","/fæn/","n.","迷， 狂热的爱好者、 支持者； 风扇","Groups of football fans began heading towards the ground.","成群结队的球迷开始向球场走去。"],["slice","/slaɪs/","n.","片， 薄片","pizza slices","比萨块"],["far","/fɑr/","adj&adv.","远的","He started to explain, but he didn’t get far (= he did not succeed in saying very much ) before Mary interrupted him.","他开始解释起来，但没说几句就被玛丽打断了。"],["frost","/frɔst/","n.","霜","the risk of frost damage to crops","庄稼遭受霜冻灾害的危险"],["catch","/kætʃ/","vt.","接住； 捉住； 赶上； 染上","Anton caught malaria in Mali, and nearly died.","安东在马里染上疟疾，差点丢了性命。"],["fax","/fæks/","n.","传真","Did you get my fax?","你收到我的传真了吗？"],["plan","/plæn/","n&v.","计划， 打算","His plan is to get a degree in economics and then work abroad for a year.","他计划先取得经济学学位，然后去国外工作一年。"],["cash","/kæʃ/","n/vt.","现金，现钞；兑现","Cash was taken during a burglary of the apartment.","在一次公寓盗窃案中现金被盗。"],["case","/kes/","n.","情况； 病例； 案件； 容器","We tend to think of these people as untrustworthy, but that is not the case.","我们往往会认为这些人不可靠，但事实并非如此。"],["generation","/ˈdʒɛnəˈreʃən/","n.","代， 一代","Like most of my generation, I had never known a war.","和我们这一代的大多数人一样，我并没有经历过战争。"],["give","/ɡɪv/","v.","给， 付出","They say they’re not willing to give any more than they’ve already offered.","他们说就给原定的这些钱，不愿意再多给了。"],["double","/ˈdʌbl/","adj/v/n.","两倍的；双重的；加倍；两个；双打","a double sink","双水槽"],["downtown","/ˈdaʊnˈtaʊn/","n&adj.","市区 ， 闹市区","",""],["trunk","/trʌŋk/","n.","树干； 大箱子","He left his bicycle leaning against a tree trunk .","他把他的自行车斜靠在树干上。"],["stainless","/ˈsteɪnlɪs/","adj.","无污染的； 无瑕疵的； 不锈的","stainless steel",""],["explicit","/ɪkˈsplɪsɪt/","adj.","清楚的； 直率的","The contrast could not have been made more explicit.","这个对比再清楚不过了。"],["rely","/rɪˈlaɪ/","vi.","依赖， 依靠； 信任","They relied heavily on the advice of their professional advisers.","他们非常依赖专业顾问的建议。"],["phone","/fon/","v/n.","打电话；电话； 电话机","I’ll phone you this evening.","今晚我会给你打电话。"],["slide","/slaɪd/","v/n.","滑行，滑动；幻灯片； 滑道","He slid open the door of the glass cabinet.","他滑开玻璃柜的门。"],["comfortable","/ˈkʌmfɚtəbl/","adj.","舒服的； 安逸的； 舒服自在的","I was so comfortable and warm in bed I didn’t want to get up.","床上又舒服又暖和，我都不想起来。"],["waist","/west/","n.","腰部， 腰围","The skirt was too big around the waist.","那条裙子腰围太大。"],["style","/staɪl/","n.","风格， 时尚","an attempt to use Japanese management style in a European business","将日本的管理方式用于欧洲企业的尝试"],["jungle","/ˈdʒʌŋɡl/","n.","丛林， 密林","the Amazon jungle","亚马孙丛林"],["flesh","/flɛʃ/","n.","肉， 肉体","a freshwater fish with firm white flesh","一种肉色雪白、肉质紧实的淡水鱼"],["suit","/sut/","vt/n.","适合；一套","Whatever your reason for borrowing, we have the loan that suits your needs .","不管您因何贷款，我们都会有满足您需要的贷款。"],["grill","/ɡrɪl/","n.","烤架； 烤肉","Pop it under the grill for five minutes.","把它放在烤架下烤五分钟。"],["care","/kɛr/","v/n.","介意，在乎；在意；关心；照料； 保护； 小心","‘He looked angry.’ ‘ I don’t care !’","“他好像很生气。”“我不管！”"],["damage","/ˈdæmɪdʒ/","n&v.","毁坏， 损害","These chemicals have been found to cause serious environmental damage.","经发现，这些化学物质会造成严重的环境破坏。"],["guard","/ɡɑrd/","v/n.","保卫，看守；防护装置； 警戒","The Sergeant told Swift to guard the entrance.","中士叫斯威夫特守着入口。"],["settle","/ˈsɛtl/","vi/vt.","安家，定居；解决","When the children had settled, Miss Brown gave out the new reading books.","孩子们静下来后，布朗小姐给他们发新的故事书。"],["direct","/dəˈrɛkt/","adj/v.","直接的；直达的；指挥， 指导","Experienced users have direct access to the main data files.","高级用户可直接浏览主数据文档。"],["pattern","/ˈpætɚn/","n.","式样； 模式","Weather patterns have changed in recent years.","气候模式近年已经发生了变化。"],["exercise","/ˈɛksɚsaɪz/","v/n.","锻炼；[C]练习；[U]锻炼","It’s important to exercise regularly.","经常锻炼很重要。"],["labour","/ˈleibə/","n.","劳动， 劳力","The garage charges £30 an hour for labour.","汽车修理厂收取每小时30英镑的人工费。"],["gain","/ɡen/","v/n.","获得，挣得；收获","After gaining independence in 1957, it was renamed ‘Ghana’.","1957年获得独立后，该国改名为“加纳”。"],["vehicle","/ˈviəkəl/","n.","车辆","a description of the stolen vehicle","对被盗车辆的描述"],["hardship","/ˈhɑrdʃɪp/","n.","困难， 艰辛","an economic policy that caused great hardship for many people","造成许多人贫困的经济政策"],["confuse","/kənˈfjʊz/","vt.","使糊涂； 搞乱","I understand the text but the diagrams are confusing me.","文字我理解，但是图表把我弄糊涂了。"],["kilo","/ˈkilo/","n.","千克； 公斤","He'd lost ten kilos in weight.","他的体重已经减了10公斤。"],["freedom","/ˈfridəm/","n.","自由","People here like their freedom and privacy.","这里的人喜欢他们所拥有的自由与隐私权。"],["cushion","/ˈkʊʃən/","n.","垫子","a velvet cushion","天鹅绒垫子"],["scold","/skold/","vt.","责骂， 谴责","Do not scold the puppy, but simply and firmly say ‘no’.","不要责骂小狗，但要干脆利落地说“不”。"],["modern","/ˈmɑdɚn/","adj.","现代的， 近代的； 时尚的","Such companies must change if they are to compete in the modern world .","此类公司如果想在现代社会中与别人竞争，就必须有所改变。"],["physics","/ˈfɪzɪks/","n.","物理","...the laws of physics.","…物理学定律。"],["seldom","/ˈsɛldəm/","adv.","很少， 不常","Karen had seldom seen him so angry.","卡伦很少见他这么生气过。"],["physician","/fɪˈzɪʃən/","n.","医生","...your family physician.","…你的家庭医生。"],["protect","/prəˈtɛkt/","vt.","保护","Are we doing enough to protect the environment?","我们在保护环境方面做得够吗？"],["architecture","/ˈɑrkəˈtɛktʃɚ/","n.","建筑， 建筑学","He studied architecture at university.","他在大学里读的是建筑学。"],["souvenir","/ˌsuːvəˈnɪə/","n.","纪念品， 纪念物","a souvenir shop","纪念品商店"],["dial","/ˈdaɪəl/","v.","拨","I think I dialed the wrong number.","我想我拨错号码了。"],["stress","/strɛs/","n/vt.","压力；强调","Your headaches are due to stress.","你的头痛是压力造成的。"],["explore","/ɪkˈsplɔr/","v.","探险； 探索","Management need to explore ways of improving office security.","管理层需要探讨如何加强办事处的安全措施。"],["more","/mɔr/","adv/pron/adj.","更；更多的…； 另外的…；更多的","You’ll have to be more careful next time.","你下次要更小心一点。"],["wet","/wɛt/","adj.","湿的","I’ve washed your shirt but it’s still wet.","我把你的衬衫洗过了，不过现在还是湿的。"],["born","/bɔrn/","adj.","出生的","the skill of a born actor","天生的表演技巧"],["strawberry","/ˈstrɔbɛri/","n.","草莓","...strawberries and cream.","…奶油草莓。"],["electricity","/ɪˈlɛkˈtrɪsəti/","n.","电； 电流","The farm was very isolated, but it had electricity.","那个农场非常偏远，但有电力供应。"],["tentative","/ˈtɛntətɪv/","adj/n.","试验性的； 试探的；试验；假设","I passed on my tentative conclusions to the police.","我把我的初步结论递交给了警方。"],["climate","/ˈklaɪmɪt/","n.","气候； 风气； 环境气氛","Los Angeles’ warm dry climate","洛杉矶温暖干燥的气候"],["kill","/kɪl/","vt.","杀死， 弄死； 消磨","Why did she kill her husband?","她为什么杀死丈夫？"],["conductor","/kənˈdʌktɚ/","n.","管理人； 指导者； 售票员， 列车员； 乐队指挥","Wood is a poor conductor of heat.","木头导热性能差。"],["porridge","/ˈpɔrɪdʒ/","n.","稀饭， 粥","",""],["pleased","/plizd/","adj.","高兴的","Your Dad will be so pleased.","你爸爸会非常高兴的。"],["certain","/ˈsɝtn/","adj.","某些； 确定的， 无疑的； 一定会…","I felt certain that I’d passed the test.","我感觉自己肯定通过这次测验了。"],["woolen","/ˈwʊlɪn/","adj.","羊毛的， 羊毛制的","He had a red woolen muffler round his neck and his skin was rather reddish too.","他脖子上围了一个红色的羊毛围巾，他的皮肤也相当的暗红。"],["board","/bɔrd/","n/vt.","木板；布告牌；委员会；上","I’ll check the departure board for train times.","我去查一下开车时刻表，看看火车的时间。"],["statistics","/stəˈtɪstɪks/","n.","统计表， 数字， 数据","statistics for earnings by different age groups",""],["shut","/ʃʌt/","v/adj.","（使）关[合]上，（使）关闭；关闭的，关上的","Shut the window, Ellen!","埃伦，把窗关上！"],["arrest","/əˈrɛst/","vt&n.","逮捕， 拘留","He was arrested and charged with murder.","他遭到逮捕并被指控谋杀。"],["distinction","/dɪˈstɪŋkʃən/","n.","区别； 差别","There are obvious distinctions between the two wine-making areas.","这两个酿酒区之间有明显的不同。"],["widow","/ˈwɪdo/","n.","寡妇","an elderly widow who was attacked and robbed last month","上个月遭到行凶抢劫的一位寡居老妇"],["mature","/məˈtʃʊr/","adj.","成熟的， 成年的","Laura is very mature for her age .","相对她的年龄来说劳拉是很成熟的。"],["navy","/ˈnevi/","n.","海军","the British Navy","英国海军"],["disability","/ˌdɪsəˈbɪləti/","n.","残疾； 无能","Facilities for people with disabilities are still insufficient.","供残疾人使用的设施仍然不足。"],["fee","/fi/","n.","费， 费用","He paid his licence fee, and walked out with a brand-new driving licence.","他付了驾照费用，拿着一张全新的驾照走出来。"],["section","/ˈsɛkʃən/","n.","段； 部分； 部门","The plane’s tail section was found in a cornfield.","飞机的尾部在玉米田里找到了。"],["simple","/ˈsɪmpl/","adj.","简单的， 简易的","a simple but effective solution to the problem","对这个问题简单而有效的解决办法"],["used","/juzd/","adj.","用过的； 旧的， 二手的","a used tissue","用过的纸巾"],["influence","/ˈɪnfluəns/","n&vt.","影响","As a scientist, his influence was immense.","身为一名科学家，他的影响力极大。"],["mustard","/ˈmʌstɚd/","n.","芥末， 芥子粉","...a jar of mustard.","…一罐芥末酱。"],["percentage","/pɚˈsɛntɪdʒ/","n.","百分率； 比例","Interest rates fell by six percentage points (= 6% ) .","利息下降了6个百分点。"],["talent","/ˈtælənt/","n.","天才， 才能","He has a lot of talent , and his work is fresh and interesting.","他很有天赋，作品新颖有趣。"],["few","/fju/","pron/adj.","不多， 少数；不多的，少数的","This should not be an experience for the few.","这应该不只是少数人的经历。"],["otherwise","/ˈʌðɚwaɪz/","adv.","否则， 要不然","You’ll have to go now, otherwise you’ll miss your bus.","你现在就得走，要不然就赶不上公共汽车了。"],["negotiate","/nɪˈɡoʃɪet/","v.","谈判， 协商","His first aim is to get the warring parties back to the negotiating table (= discussing something ).","他的首要目标就是把交战各方拉回到谈判桌上。"],["hunt","/hʌnt/","v&n.","寻找； 狩猎， 猎取","the slopes where I hunted deer as a kid","我儿时猎鹿的山坡"],["package","/ˈpækɪdʒ/","n.","一包， 一袋， 一盒； 包裹","There’s a package here for a Miami Lakes address.","这里有一个寄往迈阿密湖的包裹。"],["pronunciation","/prə/","n.","发音","She gave the word its French pronunciation.","她给出了这个单词的法语发音。"],["kind","/kaɪnd/","adj/n.","善良的， 亲切的， 和蔼的， 仁慈的；[C]种；类","It wasn’t a very kind thing to say.","这么说可不太客气。"],["survival","/sɚˈvaɪvl/","n.","幸存； 生存","The doctors gave him a one in ten chance of survival .","医生说他有十分之一的生存希望。"],["strait","/stret/","n.","海峡","the Bering Strait","白令海峡"],["both","/boθ/","pron/adj.","两者都； 双方都；双方的","",""],["voyage","/ˈvɔɪɪdʒ/","n.","航行， 旅行","The voyage from England to India used to take six months.","过去从英格兰到印度要航行六个月。"],["important","/ɪmˈpɔrtnt/","adj.","重要的","a very important meeting","很重要的会议"],["nutrition","/nuˈtrɪʃən/","n.","营养","Nutrition and exercise are essential to fitness and health.","营养和运动是保持健康所必不可少的。"],["detective","/dɪˈtɛktɪv/","n.","侦探","She hired a detective to find out if her husband was having an affair.","她雇了一个私人侦探调查她丈夫是否有外遇。"],["phrase","/frez/","n.","短语， 习惯用语","Who first used the phrase ‘survival of the fittest’?","“适者生存”这一说法最早是谁说的？"],["personally","/ˈpə:sənəli/","adv.","就自己而言","Personally, I don’t think much of the idea.","就个人而言，我认为这个主意不怎么样。"],["outside","/ˌautˈsaɪd/","adv/adj/prep.","在外面，向外面，出界；外面的，外表的；在…外","It’s outside my experience, I’m afraid.","恐怕我没有这方面的经验。"],["passer-by","/ˈpæsəˈbaɪ/","n.","过客， 过路人","A passerby described what he saw moments after the car bomb had exploded.","一个过路人描述了汽车炸弹爆炸后瞬间他所看到的情景。"],["keep","/kip/","v.","保留；保存；使…保持某种状态； 保持， 继续","You can keep it. I don’t need it any more.","你留着吧，我不需要了。"],["effect","/ɪˈfɛkt/","n.","效果； 作用， 影响","the long-term effects of the drug","这种毒品的长期影响"],["affection","/əˈfɛkʃən/","n.","友爱； 爱情","She looked back on those days with affection .","她深情地回顾那些日子。"],["yoghurt","/ˈjogɚt/","n.","酸乳酪","",""],["skate","/sket/","vi.","溜冰， 滑冰","The children skated on the frozen pond.","孩子们在结冰的池塘上滑冰。"],["correction","/kəˈrɛkʃən/","n.","改正","I just need to make a few corrections , and then we can send it to the printer.","我只要修改几个地方，然后就可以把它发送到打印机。"],["embarrass","/ɪmˈbærəs/","vt.","使困窘， 使局促不安","He didn’t want to embarrass her by asking questions.","他不想提问让她尴尬。"],["who","/hu/","pron.","谁","Who locked the door?","谁锁的门？"],["weigh","/weɪ/","v.","称量； 重","The young birds weigh only a few grams.","雏鸟重量只有几克。"],["sponsor","/ˈspɑnsɚ/","n/vt.","赞助者；主办者；赞助； 主办","corporate sponsors","企业赞助商"],["acute","/əˈkjut/","adj.","尖锐的； 敏锐的； 严重的； 急性的","The housing shortage is more acute than first thought.","住房短缺情况比一开始想的要严重。"],["kindergarten","/ˈkɪndɚɡɑrtn/","n.","幼儿园","I to the kindergarten at the age of three.","在我记忆中，我三岁就被送去幼儿园了。"],["jog","/dʒɑɡ/","v.","慢跑","I go jogging every morning.","我每天早晨都去慢跑。"],["terrify","/ˈtɛrəˌfaɪ/","vt.","使人感到害怕， 使恐惧","Her husband’s violence terrified her.","丈夫的暴力行为让她感到害怕。"],["contribute","/kənˈtrɪbjut/","v.","捐款， 捐献","The three sons also contribute to the family business.","3个儿子也为家族企业做贡献。"],["faith","/feθ/","n.","信仰， 信念； 信任","People have lost faith in the government.","人们已失去了对政府的信心。"],["insert","/ˈɪnsɝt/","vt.","插入","He took a small key from his pocket and slowly inserted it into the lock.","他从衣袋里掏出一把小钥匙，然后缓缓地将其插入锁孔里。"],["why","/hwaɪ/","adv/interjection.","为什么；哎呀，嗨〔表示惊讶或突然意识到某事〕","Why are you crying?","你为什么哭？"],["remark","/rɪˈmɑrk/","n&v.","陈述， 评论","Unfortunately, a local journalist overheard the remark.","不巧一名当地记者无意中听到了这些话。"],["forbid","/fɚˈbɪd/","v.","禁止， 不许","Lack of space forbids listing the names of all those who contributed.","由于篇幅限制，无法列出所有捐款人的姓名。"],["microscope","/ˈmaɪkrəskop/","n.","显微镜","Can I borrow your microscope?","可以借你的显微镜吗?。"],["tortoise","/ˈtɔrtəs/","n.","乌龟","I saw a big sea tortoise .","我看见过一个大海龟。"],["candidate","/ˈkændɪˌdet/","n.","候选人","a presidential candidate","总统候选人"],["alone","/əˈlon/","adj.","单独的， 孤独的","She lives alone .","她一个人生活。"],["database","/ˈdetəbes/","n.","资料库， 数据库","customer details held on a database","存储在数据库内的客户详细信息"],["parallel","/ˈpærəlɛl/","adj/n.","平行的；平行线；类似","Lines AB and CD are parallel. AB","线与CD线平行。"],["patient","/ˈpeʃənt/","adj/n.","耐心的；病人","You’ll just have to be patient and wait till I’m off the phone.","你只能耐心点，等我打完电话。"],["reject","/rɪˈdʒɛkt/","vt.","拒绝","Sarah rejected her brother’s offer of help.","萨拉拒绝了她弟弟的帮助。"],["dialogue","/ˈdaɪəˌlɔɡ/","n.","对话","a boring movie full of bad dialog","充满差劲对白的乏味电影"],["diet","/ˈdaɪət/","v/n.","节食；饮食；节食","I've been dieting ever since the birth of my fourth child.","自从我第4个孩子出生以后，我就一直在节食。"],["profit","/ˈprɑfɪt/","v/n.","赢利， 获益于；利润，益处","No one was profiting inordinately from the war effort.","没有人在从战争中发大财。"],["win","/wɪn/","v.","赢得， 获胜","Who’s winning (= who is most successful at this point in the game )?","现在谁领先？"],["rest","/rɛst/","vi/n.","休息， 歇息；休息；剩余的部分，其余的人","If you’re tired, we’ll stop and rest for a while.","如果你累了，我们就停下来歇一会儿。"],["move","/muv/","v.","移动， 搬动， 搬家","Please keep the doors closed while the train is moving.","火车行驶时请保持车门关闭。"],["amount","/əˈmaʊnt/","vi/n.","总计；等于；数量","Consumer spending on sports-related items amounted to $9.75 billion.","消费者在体育相关用品上的消费总共达到了97.5亿美元。"],["handful","/ˈhænd/","n.","把； 少数， 少量","There were only a handful of people there.","那里只有几个人。"],["album","/ˈælbəm/","n.","照相簿； 集邮本； 签名纪念册","a photograph album","相册"],["electric","/ɪˈlɛktrɪk/","adj.","电的","an electric blanket","电热毯"],["yawn","/jɔn/","v.","打呵欠","Alan stretched and yawned.","艾伦伸伸懒腰，打了个呵欠。"],["say","/se/","v.","说， 讲","‘I’m so tired,’ she said.","“我太累了。”她说。"],["also","/ˈɔlso/","adv.","也","My girlfriend was also called Helen.","我的女朋友也叫海伦。"],["terminal","/tɝ​mənl/","n.","终点站； 终端","the airport’s passenger terminal","机场航站楼"],["enough","/ɪˈnʌf/","n&adj&adv.","足够  ； 充足","Are the carrots cooked enough?","胡萝卜煮熟了吗？"],["increase","/ˈɪnkris/","v/n.","增加， 繁殖；增加， 加大","The population increased dramatically in the first half of the century.","该世纪上半叶，人口大幅度增加。"],["differ","/ˈdɪfɚ/","vi.","不一致， 有区别","The two systems differ in many respects.","这两个系统在许多方面不同。"],["shine","/ʃaɪn/","v.","发光； 照耀","The sun was shining .","阳光照耀。"],["spread","/sprɛd/","n&v.","延伸， 展开； 传播","He shrugged and spread his hands.","他耸耸肩，摊开双手。"],["various","/ˈvɛrɪəs/","adj.","各种各样的， 不同的","The jacket is available in various colours.","这种夹克有好多种颜色可选。"],["attention","/əˈtɛnʃən/","n.","注意； 关心","My attention wasn’t really on the game.","我的注意力其实不在比赛上。"],["latter","/ˈlætɚ/","n.","后者","Where unemployment and crime are high, it can be assumed that the latter is due to the former.","如果某地失业率和犯罪率都很高，可以认为后者是前者造成的。"],["front","/frʌnt/","adj/n.","前面的；前部的；前面； 前部； 前线","Two of his front teeth had been knocked out.","他有两颗门牙被打落了。"],["visit","/ˈvɪzɪt/","n&v.","参观， 访问， 拜访","Eric went to Seattle to visit his cousins.","埃里克到西雅图去看望他的表兄弟。"],["clinic","/ˈklɪnɪk/","n.","诊所","an appointment at an outpatient clinic","门诊预约"],["customer","/ˈkʌstəmɚ/","n.","顾客， 主顾","We aim to offer good value and service to all our customers.","我们力求为所有的客户提供物有所值的商品和服务。"],["stupid","/ˈstupɪd/","adj.","愚蠢的， 笨的","stupid mistakes","愚蠢的错误"],["greeting","/ˈɡritɪŋ/","n.","祝贺； 问候； 致谢","I smiled a polite greeting, but the woman hardly acknowledged me.","我客气地笑着打了个招呼，可是那女人没有答理我。"],["bring","/brɪŋ/","vt.","拿来， 带来， 取来","Did you bring an umbrella?","你带伞了吗？"],["beddings","/ˈbɛdɪŋ/","n.","被褥","",""],["awake","/əˈwek/","v/adj.","唤醒；醒着的","It was midday when she awoke.","她醒来时已是中午。"],["kiss","/kɪs/","n/vt.","[C]吻，亲吻；吻， 亲吻","Do you remember your first kiss?","你记得你的初吻吗？"],["ban","/bæn/","vt/n.","禁止；取缔；禁令","Smoking is banned in the building.","大楼内禁止吸烟。"],["hamburger","/hæmbɝ​ɡɚ/","n.","汉堡包","A hamburger and a coke.","一个汉堡和一杯可乐。"],["fond","/fɑnd/","adj.","喜爱的， 爱好的","I’m not overly fond of cooking.","我不怎么喜欢烹饪。"],["fit","/fɪt/","v/adj.","适合；适合的， 健康的","The punishment should fit the crime.","罚需当罪。"],["offer","/ˈɔfɚ/","v&n.","提供； 提出； 出价","A number of groups offer their services free of charge.","一些团体免费提供服务。"],["robot","/ˈrobɑt/","n.","机器人","cars built by robots","机器人制造的汽车"],["bar","/bɑr/","n.","酒吧； 条， 横木； 栅栏","The ball hit the bar.","球打在球门的横梁上。"],["suffer","/ˈsʌfɚ/","v.","受苦， 遭受","At least he died suddenly and didn’t suffer.","至少他死得突然，没有遭罪。"],["fix","/fɪks/","v.","修理， 安装； 确定， 决定","He’s outside fixing the brakes on the car.","他在外面修理汽车的刹车。"],["neighbourhood","/nebɚˌhʊd/","n.","四邻， 邻近地区","She grew up in a quiet neighborhood of Boston.","她是在波士顿一个清静的街区里长大的。"],["complex","/ˈkɑmplɛks/","adj/n.","复杂的；联合的；联合体","a complex system of highways","复杂的公路网"],["draft","/dræft/","vt/n.","起草；草稿","Eva’s busy drafting her speech for the conference.","伊娃正忙着起草她的大会发言稿。"],["honest","/ˈɑnɪst/","adj.","诚实的， 正直的","He was a hard-working, honest man.","他勤奋老实。"],["pension","/ˈpɛnʃən/","n.","养老金","At what age can you start drawing your pension ?","从多少岁可以开始领取养老金？"],["assumption","/əˈsʌmpʃən/","n.","假设， 假定","You would be making an assumption that's not based on any fact that you could report.","你会做出不以你能报道的任何事实为依据的一种假设。"],["rank","/ræŋk/","n.","等级， 级别； 职衔， 军衔","He was sentenced to prison and stripped of his rank (= had his rank taken from him ) .","他被判入狱，并且被剥夺了军衔。"],["rubbish","/ˈrʌbɪʃ/","n.","垃圾； 废物","a rubbish bin","垃圾桶"],["addition","/əˈdɪʃən/","n.","增加； 加法","...simple addition and subtraction problems using whole numbers.","…运用整数的简单加法和减法题。"],["afterwards","/ˈæftɚwɚdz/","adv.","后来","Charles arrived shortly afterwards .","过了不多久，查尔斯来了。"],["sure","/ʃʊər/","adv/adj.","〈口语〉 的确， 一定， 当然；确信，肯定","‘Can you give me a ride to work tomorrow?’ ‘Sure.’","“明天我可以搭你的车去上班吗？”“当然可以。”"],["grow","/ɡro/","v.","种植；生长，发育； 渐渐变得， 变成","You’ve really grown since I last saw you.","你比我上次见到时长了不少啊。"],["carve","/kɑrv/","v.","刻； 雕刻","carved wooden chairs","木雕椅子"],["shrink","/ʃrɪŋk/","v.","收缩； 缩短","I’m worried about washing that shirt in case it shrinks.","我不太敢洗那件衬衫，怕它会缩水。"],["ancestor","/ˈænsɛstɚ/","n.","祖宗， 祖先","My ancestors were French.","我的祖先是法国人。"],["league","/lig/","n.","联盟， 社团","the National Socialist League","国家社会主义联盟"],["personal","/ˈpɝsənl/","adj.","个人的， 私人的","My personal view is that we shouldn’t offer him the job.","我个人认为我们不该给他这份工作。"],["angry","/ˈæŋgrɪ/","adj.","生气的， 愤怒的","I was angry because he hadn’t told me his plans.","我很生气，因为他没有告诉我他的计划。"],["former","/ˈfɔrmɚ/","adj.","以前的， 从前的；  前者","the former Soviet Union","前苏联"],["panic","/ˈpænɪk/","v/n.","惊恐，恐慌；惊慌， 恐慌","He started to panic when he saw the gun.","他看见枪就慌了起来。"],["fold","/fold/","v.","折叠； 合拢； 包围","Fold the paper along the dotted line.","沿虚线将纸折起来。"],["stewardess","/ˈstuərdəs/","n.","女乘务员， 空中小姐","",""],["as","/æz/","adv/conj/prep.","像…一样；当…时；正如；因为；尽管；作为，以…身份","She knows me as well as him.","她像了解他一样了解我。"],["delay","/dɪˈle/","n&v.","拖延","Sorry for the delay, Mr Weaver.","韦弗先生，很抱歉耽搁了一些时间。"],["at","/æt/","prep.","在…； 以…","They live at 18 Victoria Street.","他们住在维多利亚街18 号。"],["chemical","/ˈkɛmɪkl/","adj/n.","化学的；化学制品","the chemical composition of bleach","漂白剂的化学成分"],["turning","/ˈtɝnɪŋ/","n.","拐弯处， 拐角处","He must have taken a wrong turning in the dark.","他准是在黑暗中拐错弯了。"],["peace","/pis/","n.","和平； 安宁","The country is at peace with its neighbours for the first time in years.","这是多年来该国与其邻国第一次和平共处。"],["plant","/plænt/","vt/n.","种植；播种；植物","Residents have helped us plant trees.","居民们帮助我们种了树。"],["folk","/fok/","adj.","民间的","folk tales","民间故事"],["enquiry","/ɛnˈkwaɪri/","n.","询问","We are pleased to receive your enquiry.","我们很高兴收到您的询问函。"],["drive","/draɪv/","v.","驾驶， 开； 驱赶","the man driving the car","开车的男子"],["hurt","/hɝ​t/","v.","伤害","Was anyone hurt in the accident?","事故中有人受伤吗？"],["deal","/dil/","v/n.","处理；量， 数额； 交易","How could I deal with them before?","我以前是怎样处理它们的?。"],["abuse","/əˈbjus/","vt/n.","滥用；辱骂， 粗话","Williams abused his position as Mayor to give jobs to his friends.","威廉斯滥用市长权力，给不少朋友安排了工作。"],["prove","/pruv/","vi/vt.","证明是， 结果是， 原来是；证明，证实","You’re wrong, and I can prove it.","你错了，我可以证明。"],["homeland","/ˈhomlænd/","n.","祖国","Many are planning to return to their homeland.","很多人正计划回到自己的祖国去。"],["affect","/əˈfɛkt/","vt.","影响","the areas affected by the hurricane","受飓风影响的地区"],["deaf","/dɛf/","adj.","聋的","communication between deaf and hearing people","失聪者和听力正常者之间的交流"],["admire","/ədˈmaɪr/","vt.","钦佩； 羡慕","I really admire the way she brings up those kids all on her own.","我十分佩服她独力把那些孩子抚养大。"],["virus","/ˈvaɪrəs/","n.","病毒","children infected with the Aids virus","感染艾滋病病毒的儿童"],["amuse","/əˈmjuz/","vt.","使快乐， 逗乐","He made funny faces to amuse the children.","他做鬼脸逗孩子们开心。"],["see","/si/","v.","看见， 看到； 领会","The moment we saw the house, we knew we wanted to buy it.","我们一看到这房子就知道我们要买。"],["search","/sɝtʃ/","n&v.","搜寻， 搜查","A search found 46 websites.","搜索后找到46个网站。"],["furnished","/ˈfɝnɪʃt/","adj.","配备了家具的","We drank tea by lamplight in his sparsely furnished house.","我们在他这间没什么家具的房子里，我们在灯下喝茶。"],["responsibility","/rɪˌspɑːnsəˈbɪləti/","n.","责任","Kelly’s promotion means more money and more responsibility.","凯利获得提升，这意味着钱多了，责任也更大了。"],["sudden","/ˈsʌdn/","adj.","突然的","a sudden change in the weather","天气的突然变化"],["fool","/ful/","v/n.","欺骗； 做蠢事； 游手好闲；傻子，蠢人，白痴","Even art experts were fooled.","连艺术品专家也被骗了。"],["civil","/ˈsɪvl/","adj.","国内的； 平民的； 民事的","They were married in a civil ceremony in May.","他们在五月份举行了世俗婚礼。"],["by","/baɪ/","prep.","靠近； 到…时； 被； 由； 以…的标准","I was attacked by a dog.","我被一条狗袭击。"],["whom","/hum/","pron&conj.","谁","Do any other family members reside with you? Yes/No If yes, whom?","是否有其他家庭成员和你住一起？如果是，谁？"],["indicate","/ˈɪndɪket/","vt.","指出， 显示","The study indicates a connection between poverty and crime.","研究显示贫穷和犯罪有关联。"],["set","/sɛt/","vt/n.","设置，调整；树立；摆放；日落；一套； 设备","This debate should be set in an international context .","这场辩论应该放在国际大背景下来看。"],["charge","/tʃɑrdʒ/","v/n.","收费；指控；索价；充电；费用， 价钱","Even local nurseries charge $150 a week.","即便当地的托儿所每周也要收$150的费用。"],["contain","/kənˈten/","vt.","包含； 包括","The thieves stole a purse containing bank-notes.","小偷们偷到了一个里面有钞票的钱包。"],["outstanding","/ˈaʊtˈstændɪŋ/","adj.","突出的， 显著的； 杰出的","an outstanding example of a 13th-century castle","13世纪城堡的杰出典范"],["litter","/ˈlɪtɚ/","v.","乱丢杂物","",""],["oval","/ˈovl/","adv.","椭圆","Go and open the oval box on the sofa.","去并打开在沙发上的椭圆形的盒子。"],["procedure","/prəˈsidʒɚ/","n.","程序， 手续","",""],["familiar","/fəˈmɪljɚ/","adj.","熟悉的","a familiar tune","熟悉的曲调"],["biography","/baɪˈɑɡrəfi/","n.","传记","...recent biographies of Stalin.","…近年的斯大林传记。"],["breathe","/brið/","v.","呼吸","The room filled with smoke, and it was becoming difficult to breathe.","房间里全是烟，呼吸越来越困难。"],["applicant","/ˈæplɪkənt/","n.","申请人","We have had lots of applicants for these positions.","对这些职位我们已有了很多申请人。"],["battle","/ˈbætl/","n.","战斗； 战役","the Battle of Trafalgar","特拉法尔加战役"],["awesome","/ˈɔsəm/","adj.","可怕的； 引起敬畏的","an awesome responsibility","一项令人惊惧的责任"],["partner","/ˈpɑrtnɚ/","n.","搭档， 合作者","Clare’s my tennis partner.","克莱尔是我的网球搭档。"],["gifted","/ˈɡɪftɪd/","adj.","有天赋的， 有才华的","...one of the most gifted players in the world.","…世界上最有天赋的运动员之一。"],["visa","/ˈvizə/","n.","签证","I was still in New York, trying to get a visa to visit Russia.","我仍在纽约，正在办理去俄罗斯的签证。"],["zipper","/ˈzɪpə/","n.","拉链","...the metal zipper on his jacket.","…他的夹克上的金属拉锁。"],["Arctic","/ˈɑrktɪk/","n.","北极","...winter in the Arctic.","…北极的冬天。"],["unfit","/ʌnˈfɪt/","adj.","不适宜的， 不相宜的","She never gets any exercise – she must be really unfit.","她从不锻炼——身体一定很不好。"],["interview","/ˈɪntɚvju/","n&v.","采访； 会见； 面试","a portfolio of work presented at interview","在面试时呈递的工作成果样本"],["clarify","/ˈklærəfaɪ/","v.","澄清， 阐明","Reporters asked him to clarify his position (= say exactly what his beliefs are ) on welfare reform.","记者们要求他阐明他在福利改革问题上的立场。"],["beauty","/ˈbjuti/","n.","美， 美丽； 美人","her beauty and grace","她的美貌和优雅风姿"],["beg","/bɛɡ/","v.","请求， 乞求","She begged and pleaded with them until they finally agreed.","她一再恳求，后来他们终于同意了。"],["scare","/skɛr/","v.","惊吓， 威吓； 受惊","I don’t scare easily, you know.","你知道我不是那么容易给吓倒的！"],["do","/du/","v/vt.","用以构成疑问句及否定句；做，干","‘Will Kay come?’ ‘She may do.’","“凯来吗？” “或许吧。”"],["observe","/əbˈzɝv/","v.","观察； 遵守","Scientists have observed a drop in ozone levels over the Antarctic.","科学家已经观察到南极洲上方的臭氧浓度有所下降。"],["humorous","/ˈhjumərəs/","adj.","幽默的","humorous stories","诙谐的故事"],["garment","/ˈgɑrmənt/","n.","衣服， 外衣","She pulled the garment on and zipped it up.","她穿上衣服并拉好拉链。"],["rare","/rɛr/","adj.","罕见的， 稀有的","This species of plant is becoming increasingly rare.","这种植物越来越罕见。"],["useless","/ˈjusləs/","adj.","无用的","The doctor concluded that further treatment would be useless.","医生下了结论，进一步治疗是无益的。"],["which","/wɪtʃ/","pron.","哪一个； 哪一些","",""],["disadvantage","/ˌdɪsədˈvɑːntɪdʒ/","n.","不利条件； 弱点","Criminal behaviour can be linked to economic disadvantage.","犯罪行为可能会与经济困难有关。"],["garbage","/ˈɡɑrbɪdʒ/","n.","垃圾","Can you take out the garbage when you go?","你走的时候把垃圾带出去好吗？"],["mainland","/ˈmenlænd/","n.","大陆","flights between a Greek island and the mainland","希腊一海岛和本土之间的航班"],["downstairs","/ˈdaʊnˈstɛrz/","adv.","在楼下， 到楼下","Rosie ran downstairs to answer the door.","罗茜跑下楼去开门。"],["marble","/ˈmɑrbl/","n.","大理石","The columns were of white marble.","柱子是白色的大理石。"],["never","/ˈnɛvɚ/","adv.","决不， 从来没有","He’s never been to Australia.","他从未去过澳大利亚。"],["anxiety","/æŋˈzaɪəti/","n.","忧虑； 焦急","his feelings of anxiety","他焦虑的心情"],["piece","/pis/","n.","一块  ； 小的部分","We’re witnessing a piece of history in the making.","我们正在见证一段新的历史。"],["adjust","/əˈdʒʌst/","v.","适应； 调整， 调节","They’ll soon settle in – kids are very good at adjusting.","他们很快就会习惯的——小孩子适应能力很强。"],["carry","/ˈkærɪ/","v.","携带； 搬运； 背","You have to carry a pager so that they can call you in at any time.","你得带个传呼机，以便他们随时可以联系到你。"],["burst","/bɝst/","v.","突然发生； 爆炸","The door burst open and Tom ran into the room.","门突然打开，汤姆跑进了房间。"],["western","/ˈwɛstɚn/","adj.","西方的； 西部的","the western end of the bay","海湾的西端"],["debt","/dɛt/","n.","债务， 欠款","He had enough money to pay off his outstanding debts.","他有足够的钱偿还亏欠的债务。"],["little","/ˈlɪtl/","adj.","小的； 少的","a little house","小屋"],["however","/haʊˈɛvɚ/","adv.","可是， 然而， 尽管如此； 无论如何","This is a cheap and simple process. However, there are dangers.","这是个花钱少而又简单的方法，不过有危险。"],["deep","/dip/","adv/adj.","深深地； 在深处；深的；深厚的；沉睡的；渊博的","Some bones were hidden deep beneath the ground.","一些尸骨深埋在地下。"],["goose","/ɡus/","n.","鹅","...roast goose.","…烤鹅。"],["forgive","/fɚˈɡɪv/","vt.","原谅， 宽恕","He didn’t look the sort of man to forgive and forget (= forgive someone and no longer think about it ) .","他看上去不是那种不记仇的人。"],["origin","/ˈɔrɪdʒɪn/","n.","起源； 由来","The tradition has its origins in the Middle Ages.","这一传统源于中世纪。"],["for","/fɚ/","conj/prep.","因为， 由于；为了；在…期间；对于","I cannot tell whether she is old or young, for I have never seen her.","我不知道她是年老还是年轻，因为我从没见过她。"],["mistaken","/mɪˈstekən/","adj.","错误的","Marijuana has few withdrawal effects, and this has given rise to the mistaken belief that it is not addictive.","大麻几乎没有脱瘾症状，这就让人们错误地认为它不会致瘾。"],["content","/ˈkɑntɛnt/","adj/n.","满意的；内容； 含量","Andy was a good husband, and Nicky was clearly very content.","安迪是个好丈夫，尼基显然非常满足。"],["deed","/did/","n.","行为， 事迹","After the morning’s good deeds he deserved a rest.","上午做了好事之后，他理应休息一下。"],["burden","/ˈbɝdn/","n.","担子， 负担","His family responsibilities had started to become a burden.","家庭责任已开始成为他的负担。"],["salute","/səˈlut/","n&v.","敬礼； 问候","The two soldiers saluted Lieutenant Cecil.","那两名士兵向塞西尔中尉行了礼。"],["random","/ˈrændəm/","adj.","随意的， 任意的","The company has introduced random drug testing of its employees.","公司已实行对雇员的随机毒品测试。"],["perhaps","/pɚˈhæps/","adv.","可能， 或许","Perhaps she’s next door.","她也许在隔壁。"],["plot","/plɑt/","vt/n.","密谋；情节","The minister was found guilty of plotting the downfall of the government.","那名部长被判犯有阴谋颠覆政府罪。"],["rate","/ret/","v/n.","估价； 认为；比率；价格；速度","I never rated him.","我从来都不认为他好。"],["skill","/skɪl/","n.","技能， 技巧","Reading and writing are two different skills.","阅读和写作是两种不同的技能。"],["trouble","/ˈtrʌbl/","n/vt.","问题；疾病；麻烦；使苦恼； 使忧虑； 使麻烦","Recent stock market losses point to trouble ahead.","最近股市的下跌预示着未来将有麻烦。"],["unfair","/ˈʌnˈfɛr/","adj.","不公平的， 不公正的","an unfair advantage","不公平的优势"],["divide","/dɪˈvaɪd/","v.","分， 划分； 除以","The physical benefits of exercise can be divided into three factors.","锻炼对身体的好处可以分成3个方面。"],["contrary","/ˈkɑntrɛri/","adj/n.","相反的；反面","Two contrary views emerged.","出现了两种相反的观点。"],["sit","/sɪt/","vi.","坐","The parliament building sits in a large square.","议会大楼位于一个大广场上。"],["digital","/ˈdɪdʒɪtl/","adj.","数字的， 数码的","digital TV","数字电视"],["over","/ˈovɚ/","adv/adj/prep.","越过；完了， 结束了；在…之上；超过","There are only three canoes so some people will have to swim over.","仅有三条独木舟，所以一部分人得游过去。"],["brilliant","/ˈbrɪljənt/","adj.","闪耀的； 有才气的","She had a brilliant mind.","她有极聪明的头脑。"],["practical","/ˈpræktɪkl/","adj.","实际的； 适用的； 实用的； 应用的","Candidates should have training and practical experience in basic electronics.","应征者应该具备基础电子学方面的培训和实践经验。"],["pesticide","/ˈpɛstɪsaɪd/","n.","杀虫剂","They sprinkled pesticide to bug the potatoes .","他们喷撒杀虫剂给马铃薯除虫。"],["bound","/baʊnd/","adj/v.","被束缚的；有义务的；跳跃","a fog-bound airport","因大雾而关闭的机场"],["false","/fɔls/","adj.","假的； 不正确的","Please decide whether the following statements are true or false .","请判断以下说法的对错。"],["go","/go/","v.","去，走；进行；进展； 变得， 变成","The plate went crashing to the floor.","盘子哗啦一声掉在地板上。"],["tease","/tiz/","v.","取笑， 嘲弄","Don’t get upset. I was only teasing .","别生气，我只是在逗你玩。"],["fork","/fɔrk/","n.","叉； 餐叉","Put the knives and forks on the table.","把刀叉摆放在桌子上。"],["form","/fɔrm/","v/n.","形成， 组建；表格；形式；结构","The winning party will form the government.","获胜的党派将组建政府。"],["publish","/ˈpʌblɪʃ/","v.","出版， 发行","The first edition was published in 1765.","第一版于1765年出版。"],["pyramid","/ˈpɪrəmɪd/","n.","角锥形； 金字塔","different levels of the management pyramid","金字塔式管理体系中的不同层次"],["cheque","/tʃɛk/","n.","支票","You could write her a cheque .","你可以给她开张支票。"],["avoid","/əˈvɔɪd/","vt.","避免， 躲开， 逃避","Road safety is taught to young children to avoid road accidents.","小孩子受到道路安全知识的教育，以避免交通事故。"],["bid","/bɪd/","v&n.","出价， 投标","the person who places the highest bid","出价最高的人"],["fresh","/frɛʃ/","adj.","新鲜的； 不熟练的","Ryan will bring a fresh approach to the job.","瑞安将带来一种新的工作方法。"],["astonish","/əˈstɑnɪʃ/","vt.","使惊讶","Her reply astonished me.","她的回答让我大吃一惊。"],["withdraw","/wɪðˈdrɔ/","v.","缩回， 撤回","After much persuasion he agreed to withdraw his resignation.","几经劝说，他同意收回辞呈。"],["straightforward","/ˌstreɪtˈfɔːwəd/","adj&adv.","正直的， 坦率的","Jack is tough, but always straightforward and fair.","虽然杰克很严厉，但一向坦诚公正。"],["very","/ˈvɛrɪ/","adv/adj.","很，非常；恰好的， 正好的","It feels very cold today.","今天很冷。"],["decade","/ˈdɛked/","n.","十年","...the last decade of the nineteenth century.","…19世纪的最后10年。"],["expert","/ˈɛkspɝt/","n.","专家， 能手","...a yoga expert.","…一位瑜伽专家。"],["practice","/ˈpræktɪs/","n.","实践； 练习； 惯例， 常规","It takes hours of practice to learn to play the guitar.","学习弹吉他需要长时间的练习。"],["select","/səˈlɛkt/","adj/vt.","精选的；选择，挑选，选拔","The party was small and select.","团里人员不多，都是经过精心挑选的。"],["crowd","/kraʊd/","v/n.","拥挤， 群聚；人群；堆","Holidaymakers crowded the beaches.","海滩上挤满了度假者。"],["sick","/sɪk/","adj.","有病的， 患病的， 不舒服的；  呕吐的","His mother’s very sick.","他母亲病得很重。"],["bit","/bɪt/","n.","一点， 一些， 少量","He’s taken the engine to bits .","他把发动机拆开了。"],["welfare","/ˈwɛlˈfɛr/","n.","福利； 安宁， 幸福","Our only concern is the children’s welfare.","我们唯一关心的是孩子们的幸福。"],["output","/ˈaʊtpʊt/","n.","产量， 输出量","Output is up 30% on last year.","产量比去年提高了30%。"],["corner","/ˈkɔrnɚ/","n.","角； 角落； 拐角","He pulled a dirty handkerchief out by its corner and waved it at me.","他拽出一块脏手帕，捏着一角向我挥动。"],["else","/ɛls/","adv.","别的， 其他的","There’s something else I’d like to talk about as well.","我还有其他事情要谈一谈。"],["modem","/ˈmoˈdɛm/","n.","调制解调器","He sent his work to his publishers by modem.","他通过调制解调器把作品发给他的出版商。"],["majority","/məˈdʒɔrəti/","n.","多数","The Labour Party won a huge majority at the last general election.","工党在上次大选中以巨大的票数优势获胜。"],["beside","/bɪˈsaɪd/","prep.","在…旁边； 靠近","Wendy came up and sat beside me.","温迪走过来，坐在我身边。"],["join","/dʒɔɪn/","v.","参加， 加入； 连接； 会合","Many sacrificed their weekend to join the hunt for the missing girl.","许多人牺牲周末时间，加入了寻找失踪女孩的行动。"],["drag","/dræg/","v.","拖， 拽","He grabbed her arm and dragged her into the room.","他抓住她的手臂把她拖进房间。"],["reduce","/rɪˈdʊs/","vt.","减少， 缩减","The governor announced a new plan to reduce crime.","州长宣布了一项降低犯罪率的新计划。"],["likely","/ˈlaɪkli/","adj.","很可能的","Snow showers are likely tomorrow.","明天可能有阵雪。"],["large","/lɑrdʒ/","adj.","大的； 巨大的","Los Angeles is the second largest city in the US.","洛杉矶是美国的第二大城市。"],["bakery","/ˈbekəri/","n.","面包店","A smell of bread drifted from some distant bakery.","一股面包的味道从远处的某个面包店飘来。"],["vain","/ven/","adj.","自负的； 徒劳的","Men can be just as vain as women.","男人有时会和女人一样虚荣。"],["ordinary","/ˈɔrdnɛri/","adj.","普通的， 平常的","It’s just an ordinary camera.","这只是普通的相机。"],["fry","/fraɪ/","v.","油炸， 油煎","Fry the potatoes, covered, for about 20 minutes.","盖上盖，将马铃薯煎20分钟左右。"],["somebody","/ˈsʌmbədi/","pron.","某人； 重要人物","There’s somebody waiting to see you.","有人等着要见你。"],["drink","/drɪŋk/","v/n.","喝；饮酒","You should drink plenty of water.","你应该大量喝水。"],["announce","/əˈnaʊns/","v.","宣布， 宣告","They announced their engagement in ‘The Times’.","他们在《泰晤士报》上宣布了订婚的消息。"],["traditional","/trəˈdɪʃənl/","adj.","传统的","traditional Italian cooking","传统的意大利烹饪"],["lively","/ˈlaɪvli/","adj.","活泼的； 充满生气的","a lively child","精力充沛的孩子"],["operate","/ˈɑpəˈret/","v.","动手术； 操作， 运转","Doctors had to operate to remove the bullet.","医生不得不开刀取出子弹。"],["begin","/bɪˈɡɪn/","v.","开始， 着手","As everybody’s here, let’s begin.","大家都到齐了，我们就开始吧。"],["become","/bɪˈkʌm/","vt.","变得， 成为","The weather became warmer.","天气变暖和了。"],["bacterium","/bækˈtɪrɪəm/","n.","细菌","They also converted one species of bacterium into another through a \"genome transplant\".","他们还通过“基因移植”，把一个物种的细菌转变为另一种。"],["paragraph","/ˈpærəɡræf/","n.","段落","the opening paragraphs of the novel","小说开篇的几个段落"],["oilfield","/ˈɔɪlfild/","n.","油田","The injection technic develops gradually with the deeper exploitation to oilfield.","注水技术是随着油田的深度开采而逐步发展起来的。"],["alive","/əˈlaɪv/","adj.","活着的， 存在的","It was a bad accident – they’re lucky to be alive.","这是一宗严重事故——他们能活着实属幸运。"],["eventually","/ɪˈvɛntʃuəli/","adv.","最终地","He eventually escaped and made his way back to England.","他终于逃脱并返回英格兰。"],["neighbour","/ˈneɪbə(r)/","n.","邻居","One of the neighbors complained about the noise from the party.","有位邻居抱怨聚会太吵。"],["tournament","/ˈtɝ​nəmənt/","n.","比赛， 锦标赛","I feel I can win this tournament.","我觉得我能打赢这次锦标赛。"],["cycle","/ˈsaɪkl/","vi/n/vt.","骑自行车，循环；周期；循环；使循环","The water is cycled through the machine and reused.","水通过机器循环后重复使用。"],["thinking","/ˈθɪŋkɪŋ/","n.","思索； 见解； 想法","This is a time of decisive action and quick thinking.","这个时刻需要行动果断、思维敏捷。"],["literature","/lɪtərəˌtʃʊr/","n.","文学","He has read many of the major works of literature.","他读过许多重要的文学作品。"],["astronomer","/əˈstrɑnəmɚ/","n.","天文学家","Then one day an astronomer came to the village.","终有一日，村子里来了一个天文学家。"],["prejudice","/ˈprɛdʒədɪs/","n.","偏见， 成见","Women still face prejudice in the workplace.","女性在职场中仍然面临歧视。"],["digest","/daɪˈdʒɛst/","v/n.","消化； 领会；摘要， 概要； 文摘","Most babies can digest a wide range of food easily.","大多数婴儿能轻易地消化很多种食物。"],["angle","/ˈæŋɡl/","n.","角度","You didn’t measure the angle accurately.","你没有量准角度。"],["tradition","/trəˈdɪʃən/","n.","传统， 惯例","the traditions of South East Asia","东南亚的传统"],["ability","/əˈbɪlətɪ/","n.","能力； 才能","The test measures your mathematical ability.","这种测试考查的是数学能力。"],["everything","/ˈɛvrɪˈθɪŋ/","pron.","每件事； 一切， 所有的东西","Everything was covered in a thick layer of dust.","所有东西上面都蒙着厚厚一层灰。"],["unbearable","/ʌnˈbɛrəbl/","adj.","无法忍受的","The pain was almost unbearable.","那疼痛几乎难以忍受。"],["urgent","/ˈɝdʒənt/","adj.","急迫的， 紧急的","He was in urgent need of medical attention.","他急需治疗。"],["programme","/proɡrəm/","v/n.","为…编制程序；节目；项目","What’s your favourite television programme ?","你最喜欢的电视节目是什么？"],["belief","/bɪˈlif/","n.","[C] 信条， 信念， 信仰； [U] 信任， 相信","When you get something wrong, it can shake your belief in yourself.","如果有什么事情没做好，就会动摇你对自己的信心。"],["delight","/dɪˈlaɪt/","n/vt.","快乐，乐事；使高兴， 使快乐","Chris takes great delight in teasing his sister.","克里斯以取笑妹妹为乐。"],["immigration","/ˌɪmɪˈgreɪʃn/","n.","移民","He called for a common European policy on immigration.","他要求欧洲国家实施共同的移民政策。"],["break","/brek/","v/n.","打破，弄坏；撕开；间歇； 休息","Their teeth are sharp enough to break the skin.","它们牙齿锋利，足以咬破皮肤。"],["chain store","","n.","连锁店","Jim often helps out in that chain store after school.","吉姆经常在放学后在那家连锁店帮忙。"],["vest","/vest/","n.","背心， 内衣","a bulletproof vest","防弹背心"],["change","/tʃendʒ/","vt/n.","改变；更换；兑换；零钱； 变化","Susan has changed a lot since I last saw her.","自从我上次见到苏珊之后，她变了许多。"],["suggestion","/səˈdʒɛstʃən/","n.","[C] 建议","Any suggestions would be welcome.","任何建议都欢迎。"],["fluency","/ˈfluənsi/","n.","流利， 流畅","She speaks swahili with great fluency .","她说的斯瓦希里语非常流利。"],["draw","/drɔ/","v.","绘画； 拉， 吸引； 提取","Katie had drawn a cottage with a little stream running next to it.","凯蒂画了一间小茅舍，旁边流淌着一条小溪。"],["systematic","/ˈsɪstəˈmætɪk/","adj.","系统的， 有体系的","They went about their business in a systematic way.","他们按部就班地做生意。"],["trolleybus","/ˈtrɒlibʌs/","n.","无轨电车","A trolleybus will take you to the museum .","一部无轨电车会带你到博物馆。"],["lantern","/ˈlæntɚn/","n.","灯笼","Colour the tiger lantern brown .","把老虎灯笼涂成棕色。"],["cupboard","/ˈkʌbɚd/","n.","碗柜， 橱柜","It’s in the kitchen cupboard.","它在厨房的碗柜里。"],["off","/ɔf/","prep&adv.","离开， 走开","He got into his car and drove off.","他上了车，随即开车走了。"],["comfort","/ˈkʌmfɚt/","v/n.","安慰，缓和；安慰， 慰问","Within hours of the news, Helen arrived to comfort her heartbroken friend.","得到消息几小时以后，海伦赶来安慰她那心碎的朋友。"],["joke","/dʒok/","n.","笑话","I couldn’t go out with someone for a joke, could you?","我可不能拿谈恋爱当儿戏，对不对？"],["knee","/ni/","n.","膝盖","Lucy had a bandage round her knee.","露西的膝盖上缠着绷带。"],["punishment","/ˈpʌnɪʃmənt/","n.","惩罚， 处罚","...a group that campaigns against the physical punishment of children.","…一个发起运动反对体罚儿童的组织。"],["hide","/haɪd/","v.","掩饰； 隐藏","She keeps a bottle of gin hidden behind a stack of books.","她在一堆书的后面藏了一瓶杜松子酒。"],["troublesome","/ˈtrʌblsəm/","adj.","令人烦恼的； 讨厌的","a troublesome child","烦人的孩子"],["instruction","/ɪnˈstrʌkʃən/","n.","说明， 须知； 教导","This book gives instructions for making a wide range of skin and hand creams.","这本书给出了多种护肤霜和护手霜的制作说明。"],["report","/rɪˈpɔrt/","n&vt.","报道， 报告","According to recent news reports , two of the victims are Americans.","根据近期的新闻报道，受害者中有两名是美国人。"],["oral","/ˈɔrəl/","adj.","口头的， 口述的","oral history","口述的历史"],["complete","/kəmˈplit/","adj/vt.","完成的， 完整的；完成；结束","The police were in complete control of the situation.","警方已完全控制了局势。"],["compensate","/ˈkɑmpɛnset/","v.","补偿， 赔偿","Because my left eye is so weak, my right eye has to work harder to compensate.","因为我左眼视力差，右眼就要辛苦点来弥补一下。"],["fun","/fʌn/","n.","乐趣， 娱乐","There’s plenty of fun for all the family.","可以让全家人玩得很开心。"],["constant","/ˈkɑnstənt/","adj.","经常的， 不断的","There was a constant stream of visitors to the house.","参观这幢房子的游客川流不息。"],["smog","/smɑːɡ/","n.","烟雾","Cars cause pollution, both smog and acid rain.","汽车引起污染，既有烟雾又有酸雨。"],["sob","/sɑb/","n&v.","抽泣， 呜咽地说","He began sobbing uncontrollably .","他不由自主地抽噎起来。"],["political","/pəˈlɪtɪkl/","adj.","政治的","All other political parties there have been completely banned.","那里的其他所有政党都已经完全被取缔了。"],["while","/hwaɪl/","conj/n.","正当…的时候；然而；一小会儿","They arrived while we were having dinner.","他们来时我们正在吃饭。"],["anger","/ˈæŋɡɚ/","n.","愤怒","There is growing anger among the people against the government.","民众对政府越来越不满。"],["second","/ˈsɛkənd/","adj/num/n.","二等的；第二；秒","the Second World War","第二次世界大战"],["that","/ðæt/","determiner/conjunction/adv.","那，那个〔指已经提到或已经知道的人、事物、想法等〕；〔用于动词、名词或形容词后引导一个从句，表示某人所说或所想，或陈述一个事实或理由〕；那么〔大、多等〕〔尤指通过手势比画来表示大小、数量等〕","‘You never cared about me.’ ‘That’s not true.’","“你从不关心我。”“那不是事实。”"],["edge","/ɛdʒ/","n.","边缘","Put the eggs in the centre of the dish, with the vegetables and herbs around the edge.","把鸡蛋放在盘子中间，盘边一圈放些蔬菜和香草。"],["download","/ˌdaunˈləud/","n&vt.","下载","games that can be downloaded free from the Internet","可以从因特网上免费下载的游戏"],["split","/splɪt/","vt.","撕开， 切开","The branch split under their weight.","树枝承受不住他们的重量断裂了。"],["than","/ðæn/","conj.","比","Natalie was prettier than her sister.","纳塔莉比她姐姐漂亮。"],["limit","/ˈlɪmɪt/","vt.","限制， 限定； 减少","a decision to limit imports of foreign cars","限制进口外国汽车的决定"],["widespread","/ˈwʌɪdsprɛd/","adj.","分布广的","the widespread use of chemicals in agriculture","化学品在农业中的广泛使用"],["antique","/ænˈtik/","n.","古董","The palace is full of priceless antiques.","宫殿里到处都是价值连城的古董。"],["sow","/so/","v.","播种","Sow the seeds in late March.","三月底播种。"],["different","/ˈdɪfrənt/","adj.","不同的， 有差异的","The place looks completely different now.","这地方现在完全变了。"],["fasten","/ˈfæsən/","v.","扎牢， 扣住","Make sure all the windows are securely fastened before you leave.","离开前要确保所有的窗子都已关严。"],["porter","/ˈpɔrtɚ/","n.","搬运工","Our taxi pulled up at Old Delhi station and a porter sprinted to the door.","我们的出租车停在老德里车站，一个搬运工疾步跑向车门。"],["level","/ˈlɛvl/","adj/n.","平坦的；水平线，水平","The floors in the old house were not completely level.","老房子的地面不是完全平整的。"],["dirt","/dɝt/","n.","污物， 脏物； 尘土","You should have seen the dirt on that car!","你没看见那车上沾了多少泥！"],["videophone","/ˈvɪdɪofon/","n.","可视电话","In the future, shopping can be done by videophone.","在将来，购买东西能在可视电话中进行。"],["preserve","/prɪˈzɝv/","vt.","保护， 保存","We must encourage the planting of new trees and preserve our existing woodlands.","我们必须鼓励栽种新树木，同时也要保护现有的林地。"],["plus","/plʌs/","prep.","加， 加上","Three plus six equals nine (3+6=9).","3 加6等于9。"],["relevant","/ˈrɛləvənt/","adj.","有关的","Relevant documents were presented in court.","法庭上出示了相关的文件。"],["license","/ˈlaɪsns/","n.","执照， 许可证","Since you have no license, you are not allowed to drive.","因为你没有驾驶执照，所以不允许你开车。"],["entry","/ˈɛntri/","n.","进入； 入口","There was no sign of a forced entry.","没有强行闯入的迹象。"],["expand","/ɪkˈspænd/","vi/vt.","发展；扩张","The computer industry has expanded greatly over the last decade.","计算机行业在过去十年间大大地发展起来。"],["dream","/drim/","n/v.","梦；梦想，希望","I had lots of dreams last night.","昨晚我做了很多梦。"],["noble","/ˈnobl/","adj.","高贵的， 贵族的","It’s very noble of you to spend all your weekends helping the old folk.","你心地真好，周末的时间全都用来帮助老人。"],["plug","/plʌɡ/","vt/n.","把…塞住；接通电源；塞子， 插头","We used mud to plug up the holes in the roof.","我们用泥堵住了房顶上的漏洞。"],["bunch","/bʌntʃ/","n.","串， 束","He had left a huge bunch of flowers in her hotel room.","他在她的宾馆房间里留了一大束花。"],["spy","/spaɪ/","v/n.","侦探， 刺探；密探，间谍","She worked as a spy for the American government.","她为美国政府收集情报。"],["postpone","/poˈspon/","vt.","推迟， 延期","The match had to be postponed until next week.","比赛不得不推迟到下周举行。"],["tense","/tɛns/","adj/n.","紧张的；拉紧的；时态","Is anything wrong? You look a little tense.","有什么不对劲吗？你看起来有点紧张。"],["bride","/braɪd/","n.","新娘","Guests toasted the bride and groom with champagne.","客人们以香槟为新娘新郎敬酒。"],["heat","/hit/","v/n.","加热；热","Heat the milk until it boils.","把牛奶煮开。"],["behind","/bɪˈhaɪnd/","adv/prep.","在后面； 向后；在…后面","Rising into the hills behind are 800 acres of parkland.","往上延伸至后面小山的是800英亩的草木区。"],["hammer","/ˈhæmɚ/","v/n.","敲， 锤击；锤子，锣锤","the sound of hammering and sawing","锤打和拉锯的声音"],["seal","/sil/","n.","海豹","",""],["recipe","/ˈrɛsəpi/","n.","食谱","a recipe book","一本烹饪书"],["ambassadress","/æmˈbæsədrɛs/","n.","大使夫人； 女大使","",""],["mental","/ˈmɛntl/","adj.","精神的， 脑力的","The centre provides help for people suffering from mental illness .","该中心对精神病患者提供帮助。"],["bow","/baʊ/","v&n.","鞠躬， 弯腰","She bowed and left the stage.","她鞠了一躬，离开了舞台。"],["storage","/ˈstɔrɪdʒ/","n.","贮藏， 储存； 存放","the storage of highly radioactive material","高放射性材料的存放"],["racial","/ˈreʃl/","adj.","种族的","a victim of racial discrimination","种族歧视的受害者"],["switch","/swɪtʃ/","v&n.","更换， 转换","The terrorists will switch tactics .","恐怖分子会改变战术。"],["total","/ˈtotl/","adj/n/vt.","总数的；总括的；完全的；合计；合计为","a total ban on cigarette advertising","香烟广告的全面禁止"],["of","/ʌv/","prep.","…的","the back of the house","房子的后部"],["reserve","/rɪˈzɝv/","n&vt.","保留， 储备； 预订","Do you have to reserve tickets in advance?","你必须预先订票吗？"],["somehow","/ˈsʌmhaʊ/","adv.","以某种方式； 不知怎么地","Don’t worry, we’ll get the money back somehow.","别担心，我们总会把那些钱拿回来的。"],["brick","/brɪk/","n.","砖； 砖块","a brick wall","砖墙"],["dive","/daɪv/","vi.","跳水","Diving off the cliffs is dangerous.","从悬崖上跳水是很危险的。"],["heap","/hip/","v/n.","堆起来；堆","Mrs. Madrigal heaped more carrots onto Michael's plate.","马德里加尔太太往迈克尔的盘子里放了更多的胡萝卜。"],["sympathy","/ˈsɪmpəθi/","n.","同情","Our sympathies are with the families of the victims.","我们向受害者家庭表示慰问。"],["hear","/hɪr/","v.","听见， 听说， 得知","Blanche heard a crash as the back door was flung open.","布兰奇听见后门哗啦一声被推开。"],["fight","/faɪt/","n&v.","打仗， 打架； 争论","She fought him desperately, kicking and biting.","她又踢又咬，与他拼命撕打。"],["roundabout","/ˈraʊndəbaʊt/","adj/n.","绕道的；不直接的；转盘路","The bus took a very long and roundabout route .","公共汽车路线很长，绕着圈子走。"],["rescue","/ˈrɛskju/","vt&n.","营救， 援救","Survivors of the crash were rescued by helicopter.","空难的生还者被直升机救了出来。"],["facial","/ˈfeʃl/","adj.","面部用的","Victor’s facial expression didn’t change.","维克托脸上的表情没有变化。"],["on","/ɑn/","adv/prep.","继续；在…上；在…时候；在…地方；关于","I wanted to punch him on the nose.","我真想一拳打到他鼻子上。"],["zebra","/ˈzibrə/","n.","斑马","Sixty acres of woods and ponds are home to camels, zebra, bison , water buffalo, ostrich and antelope.","六十英亩的森林和池塘是骆驼，斑马，野牛，水牛，鸵鸟和羚羊的家园。"],["brief","/brif/","adj.","简洁的","The president read a brief statement to reporters before boarding his plane.","总统登机前向记者宣读了一篇简短的声明。"],["unfortunate","/ʌnˈfɔrtʃənət/","adj.","不幸的， 倒霉的","When we entered the room, the teacher was yelling at some unfortunate student.","我们进教室的时候，老师正在对着一个倒霉的学生吼叫。"],["recover","/rɪˈkʌvɚ/","vi/vt.","痊愈；恢复； 重新获得","He is recovering from a knee injury.","他的膝伤正在痊愈。"],["or","/ɔr/","conj.","或者； 还是， 否则","Shall we go out to the cinema or stay at home?","我们是出去看电影还是待在家里？"],["chance","/tʃæns/","n.","机会； 可能性","There’s always the chance that something will go wrong.","总有可能会出现问题。"],["determine","/dɪˈtɝmɪn/","v.","决定； 测定； 确定","Investigators are still trying to determine the cause of the fire.","调查人员仍在设法弄清失火的原因。"],["nature","/ˈnetʃɚ/","n.","自然； 性质； 本性","a child with a happy, easy-going nature","个性开朗、容易相处的孩子"],["social","/ˈsoʃl/","adj.","社会的； 社交的； 群居的","social issues, such as unemployment and education","失业和教育之类的社会问题"],["wheel","/wil/","n.","轮， 车轮； 方向盘","Shall I take the wheel (= drive instead of someone else )?","我来开车好吗？"],["interesting","/ˈɪntrəstɪŋ/","adj.","有趣的","That’s an interesting question.","那是一个有趣的问题。"],["cross","/krɔs/","n/vt.","十字形的东西；十字架；越过； 穿过","He raised his arms in triumph as he crossed the line for his 100-metres win.","他以胜利的姿态高举双手跑过终点线，赢得了这场百米赛。"],["control","/kənˈtrol/","vt&n.","控制","The disease robs you of muscle control.","这种疾病会让你丧失肌肉控制力。"],["drill","/drɪl/","v/n.","钻；重复训练；钻头；  训练","Drill a hole in each corner.","在每个角上钻一个孔。"],["friction","/ˈfrɪkʃən/","n.","摩擦； 摩擦力","Putting oil on both surfaces reduces friction.","两面都上油可减小摩擦力。"],["clerk","/klɝk/","n.","书记员； 办事员； 职员","a clerk in a commercial firm","一家商行的文员"],["walnut","/ˈwɔlnət/","n.","胡桃， 胡桃木","coffee and walnut cake","咖啡核桃蛋糕"],["acknowledge","/əkˈnɑlɪdʒ/","vt.","答谢； 承认","The family acknowledge the need for change.","全家人都承认需要改变一下。"],["equip","/ɪˈkwɪp/","vt.","装备； 训练","They try to equip their vehicles with gadgets to deal with every possible contingency.","他们尽量给他们的车辆配备各种小装置以应付任何可能的突发状况。"],["radiation","/ˌreɪdiˈeɪʃn/","n.","放射； 放射物； 放射疗法","Sun creams work by blocking harmful ultraviolet radiation.","防晒霜可隔离有害的紫外线辐射。"],["quarrel","/ˈkwɔrəl/","n&vi.","争吵， 吵架","I wish you two would stop quarreling.","我希望你们两个别再吵了。"],["Christian","/ˈkrɪstʃən/","adj/n.","基督教徒的；基督教徒","the Christian religion","基督教"],["pulse","/pʌls/","v/n.","搏动， 跳动；脉搏；脉冲","She felt the blood pulsing through her veins .","她觉得血液冲击着自己的血管。"],["maple","/ˈmepl/","n.","枫树","...a solid maple worktop.","…一张结实的枫木工作台。"],["spiritual","/ˈspɪrɪtʃʊəl/","adj.","精神的； 心灵的","Painting helps fill a spiritual need for beauty.","绘画可以满足对美的精神需求。"],["worthwhile","/ˈwɝθˈwaɪl/","adj.","值得做的","He wanted to do a worthwhile job.","他想做有意义的工作。"],["nation","/ˈneʃən/","n.","民族， 国家","the President’s radio broadcast to the nation","总统对全国的广播讲话"],["upper","/ˈʌpɚ/","adj.","较高的， 较上的","the upper lip","上唇"],["splendid","/ˈsplɛndɪd/","adj.","灿烂的， 辉煌的； 〈口语〉 极好的","a splendid idea","很妙的主意"],["adaptation","/ˌædæpˈteɪʃn/","n.","[U] 适应， 适合； [C] 改编本","Branagh won two awards for his screen adaptation of Shakespeare's Henry the Fifth.","布拉纳因他对莎士比亚的《亨利五世》的荧幕改编而获了两次奖。"],["behalf","/bɪˈhæf/","n.","利益； 代表","She asked the doctor to speak to her parents on her behalf.","她请医生代她同她父母谈谈。"],["somewhere","/ˈsʌmwɛr/","adv.","在某处， 到某处","My wallet must be around here somewhere.","我的钱包肯定是在这里的什么地方。"],["scene","/sin/","n.","一场， 场景， 布景； 景色， 风景","He photographed a wide range of street scenes.","他拍下了丰富多彩的街景。"],["injure","/ˈɪndʒɚ/","vt.","损害， 伤害","A number of bombs have exploded, seriously injuring at least five people.","一些炸弹爆炸了，至少5人严重受伤。"],["freeze","/friz/","v.","结冰","The lake had frozen overnight.","湖上一夜之间就结了冰。"],["eastward","/ˈistwɚdz/","adv.","向东","A powerful snow storm is moving eastward.","一场猛烈的暴风雪正向东转移。"],["geography","/dʒiˈɑɡrəfɪ/","n.","地理学","a geography lesson","地理课"],["horrible","/ˈhɑːrəbl/","adj.","令人恐惧的， 恐怖的","The weather has been really horrible all week.","整个星期天气都很糟。"],["strengthen","/ˈstrɛŋθn/","v.","加强， 增强","Our friendship has steadily strengthened over the years.","我们的友谊逐年加深。"],["injury","/ˈɪndʒəri/","n.","损伤； 受伤处","She was taken to hospital with serious head injuries.","她头部受重伤被送到医院。"],["diploma","/dɪˈplomə/","n.","毕业文凭， 学位证书","I’m hoping to get my teaching diploma this year.","我希望今年能拿到教师证书。"],["brand","/brænd/","n.","商标， 牌子","products which lack a strong brand image","缺乏鲜明品牌形象的产品"],["suspension","/səˈspɛnʃən/","n.","暂停， 中止； 悬挂， 悬浮","He received a six-month suspension for unprofessional behaviour.","他因有违职业道德的行为被停职六个月。"],["choke","/tʃok/","n&v.","窒息","Six people choked to death on the fumes.","六人被烟呛死。"],["alcohol","/ˈælkəhɔl/","n.","酒精， 酒","I don’t drink alcohol anymore.","我不再喝酒了。"],["pleasure","/ˈplɛʒɚ/","n.","高兴， 愉快","the simple pleasures of life","生活中的简单乐趣"],["old","/old/","adj.","老的， 旧的","a pair of old shoes","一双旧鞋"],["recreation","/ˌrekriˈeɪʃn/","n.","消遣， 娱乐","His only recreations are drinking beer and watching football.","他唯一的消遣就是喝啤酒和看足球比赛。"],["allowance","/əˈlaʊəns/","n.","津贴， 补贴","Sales staff get a generous mileage allowance or a company car.","销售人员有优厚的里程补贴或者公司提供的专用汽车。"],["interpreter","/ɪnˈtɝprɪtɚ/","n.","翻译员， 口译人员","Speaking through an interpreter (= using an interpreter ), Ahmed said, ‘I’m very worried about my wife and children.’","艾哈迈德通过口译者说:“我很担心我的妻子和孩子们。”"],["hurricane","/ˈhʌrɪken/","n.","飓风， 狂风","I still remember a hurricane that hit us thirty years ago.","我还记得三十年前袭击我们的一次飓风。"],["portable","/ˈpɔrtəbl/","adj.","轻便的， 便携的","a portable radio","便携式收音机"],["then","/ðɛn/","adv.","当时， 那时； 然后； 那么","I wish I had known then what I know now.","我真希望那时我就知道现在所知道的一切。"],["ancient","/ˈenʃənt/","adj.","古代的， 古老的","the ancient civilizations of Asia","亚洲的古代文明"],["accept","/əkˈsɛpt/","v.","接受","Rick accepted her offer of coffee.","她请里克喝咖啡，他接受了。"],["glory","/ˈɡlɔri/","n.","光荣， 荣誉","She dreamt of future glory as an Olympic champion.","她梦想着将来能得到奥运冠军的荣誉。"],["seat","/sit/","n/vt.","座位，座；使就座； 可容纳","I was in the back seat and Jo was driving.","我在后座，乔开车。"],["wander","/ˈwɑndɚ/","v.","游荡； 漫步； 流浪","When he got bored he wandered around the fair.","烦闷时，他便在集市上四处闲逛。"],["adopt","/əˈdɑpt/","vt.","采用； 收养","Sally was adopted when she was four.","莎莉四岁时被人收养。"],["oppose","/əˈpoz/","v.","反对","Congress is continuing to oppose the President’s health care budget.","国会继续反对总统的医疗保健预算。"],["minus","/ˈmaɪnəs/","adj/prep.","负的；减去","‘Any minus points ?’ ‘Well, the engine is rather noisy.’","“有什么毛病吗？”“嗯，发动机噪音很大。”"],["belly","/ˈbɛli/","n.","肚子","She laid her hands on her swollen belly.","她把手放在隆起的肚子上。"],["conservative","/kənˈsɝvətɪv/","adj.","守旧的； 保守主义的； 谨慎的","a very conservative attitude to education","对待教育非常守旧的态度"],["access","/ˈæksɛs/","n/vt.","通道；机会，权利；进入； 存取","Access is by means of a small door on the right.","入口是右边的一扇小门。"],["conference","/ˈkɑnfərəns/","n.","会议","Representatives from over 100 countries attended the International Peace Conference in Geneva.","来自一百多个国家的代表出席了在日内瓦举行的国际和平大会。"],["primitive","/ˈprɪmətɪv/","adj.","原始的， 远古的","a primitive society","原始社会"],["activity","/ækˈtɪvətɪ/","n.","活动","Everyone is free to engage in peaceful political activity.","每个人都可以自由参加和平的政治活动。"],["dormitory","/ˈdɔrmətɔri/","n.","学生宿舍","She lived in a college dormitory.","她住在一幢大学宿舍楼里。"],["overcome","/ˌəuvəˈkʌm/","v.","战胜， 克服， 胜过","Australia overcame the Netherlands 2-1.","澳大利亚队2比1战胜了荷兰队。"],["recite","/rɪˈsaɪt/","v.","背诵","She recited a poem that she had learnt at school.","她背诵了一首学校里学的诗。"],["seek","/sik/","v.","试图； 寻找， 寻求","Do you think the President will seek re-election ?","你认为总统会谋求连任吗？"],["seem","/sim/","v.","似乎， 好像","Ann didn’t seem very sure.","安看来并不十分肯定。"],["heel","/hil/","n.","脚后跟","black boots with high heels","有高跟的黑靴子"],["variety","/vəˈraɪəti/","n.","种种； 种类","West Hampstead has a variety of good stores and supermarkets.","西汉普斯特德有几家不同的高品质商店和超市。"],["disturb","/dɪˈstɝb/","v.","打扰， 扰乱","Sorry to disturb you, but I have an urgent message.","对不起打扰一下，我有个紧急消息。"],["adore","/əˈdɔr/","vt.","爱慕， 崇拜","Betty adores her grandchildren.","贝蒂非常宠爱孙辈。"],["lecture","/ˈlɛktʃɚ/","n.","[C] 讲课， 演讲","...a series of lectures by Professor Eric Robinson.","…埃里克·鲁滨逊教授的系列讲座。"],["civilian","/səˈvɪlɪən/","n.","平民， 老百姓","Many innocent civilians were killed during the war.","许多无辜的平民在战争中丧生。"],["so","/so/","adv/conjunction/n.","也，同样〔用于表示刚说过的情况也适用于某人或某物〕；因此，所以；全音阶的第五音","\"Do you think that made much of a difference to the family?\"—\"I think so.\"","“你认为那样给全家带来了很大变化吗？”—“我觉得是。”"],["pump","/pʌmp/","vt/n.","用泵抽水；抽；抽水机， 泵","We were able to pump clean water from several of the wells.","我们能从几口井里抽出干净的水来。"],["caution","/ˈkɔʃən/","n.","小心， 谨慎","The physician must exercise caution when prescribing antidepressants.","医师在开抗抑郁药处方时必须谨慎。"],["key","/kiː/","n.","[C] 钥匙； 答案； 键； 关键","A bunch of keys hung from his belt.","他的皮带上挂着一串钥匙。"],["teenager","/ˈtinedʒɚ/","n.","青少年， 十几岁的少年","a TV sex education series aimed at teenagers","一部针对青少年的性教育电视系列片"],["dumpling","/ˈdʌmplɪŋ/","n.","饺子","chicken and dumplings","鸡肉和汤团"],["silent","/ˈsaɪlənt/","adj.","无声的， 沉默的","The large house was silent and lonely.","这幢大房子寂静荒凉。"],["decision","/dɪˈsɪʒn/","n.","决定； 决议","Do you ever wonder if you made the right decision?","你怀疑过自己所作的决定是否正确吗？"],["addicted","/əˈdɪktɪd/","adj.","入迷的， 上瘾的","Many of the women are addicted to heroin and cocaine.","这些妇女中的很多吸食海洛因和可卡因成瘾。"],["necessary","/ˈnɛsəˌsɛri/","adj.","必需的， 必要的","The booklet provides all the necessary information about the college.","这本小册子提供了关于那所学院的所有必需信息。"],["one","/wʌn/","num&pron.","一个  ； 任何人","‘Have you got a camera?’ ‘No.’ ‘You should buy one’ (= buy a camera ).","“你有照相机吗？”“没有。”“你应该买一架。”"],["garage","/gəˈrɑ:ʒ/","n.","汽车间， 汽车库","I’ll just go and put the car in the garage.","我把车停到车库去。"],["badminton","/ˈbædmɪntən/","n.","羽毛球","I like playing basketball and badminton.","我喜欢打篮球和羽毛球。"],["confirm","/kənˈfɝm/","vt.","确定； 批准","Could you confirm the dates we discussed?","你能确认我们商讨过的日期吗？"],["single","/ˈsɪŋɡl/","adj.","单一的， 单个的","A single tree gave shade from the sun.","唯有一棵树遮阴。"],["pull","/pʊl/","v/n.","拉，拖；拉力， 引力","Mom! Davey’s pulling my hair!","妈妈! 戴维拽我的头发！"],["unconditional","/ˌʌnkənˈdɪʃənl/","adj.","无条件的， 绝对的","the unconditional release of all political prisoners","所有政治犯的无条件释放"],["gallon","/ˈɡælən/","n.","加仑","a 20 gallon fish tank","一个20加仑的鱼缸"],["appoint","/əˈpɔɪnt/","vt.","指定， 任命","officials appointed by the government","政府任命的官员"],["assist","/əˈsɪst/","v.","帮助， 协助","The family decided to assist me with my chores.","家人决定分担我的琐事。"],["bun","/bʌn/","n.","馒头； 小甜面包","a hamburger bun","用来做汉堡包的圆面包"],["but","/bʌt/","conj/prep.","但是，可是；除了， 除…外","It’s an old car, but it’s very reliable.","这是一辆旧车，但是性能非常可靠。"],["symbol","/ˈsɪmbl/","n.","符号， 象征","The symbol on the packet is a guarantee that the food has been produced organically.","包装盒上的这个标识保证这种食物是有机生产的。"],["sincerely","/sɪnˈsɪrli/","adv.","真诚地","I sincerely hope I’ll see her again.","我衷心希望再见到她。"],["commercial","/kəˈmɝʃəl/","adj.","商业的， 贸易的","Our top priorities must be profit and commercial growth.","我们必须把利润和贸易增长作为我们的第一要务。"],["separate","/(forv.)sɛpəˌret/","v/adj.","分开，  分离；单独的， 分开的","This will keep your dressing from separating.","这样可以防止调味汁分层。"],["declare","/dɪˈklɛr/","v.","宣布， 声明； 申报","A state of emergency has been declared.","已宣布进入紧急状态。"],["reasonable","/ˈriznəbl/","adj.","合理的， 有道理的； 通情达理的， 合乎情理的","a reasonable request","合情合理的要求"],["dislike","/dɪsˈlaɪk/","n&vt.","不喜欢， 嫌恶","Why do you dislike her so much?","你为什么那么讨厌她？"],["willing","/ˈwɪlɪŋ/","adj.","情愿的， 乐意的","I soon had an army of willing helpers.","我很快就拥有了一批热心的帮手。"],["available","/əˈveləbl/","adj.","有空的； 可得到的， 可用的","Tickets are available from the box office.","售票处有票出售。"],["express","/ɪkˈsprɛs/","vt/n.","表达；表示；快车","Parents have expressed their concerns about their children’s safety.","父母对自己孩子的安全表示忧虑。"],["advocate","/ˈædvəkeɪt；-et/","vt.","提倡； 鼓吹","Extremists were openly advocating violence.","极端主义者公开鼓吹使用暴力。"],["amazing","/əˈmezɪŋ/","adj.","令人惊异的","He’s an amazing player to watch.","看他比赛那才叫精彩呢。"],["luggage","/ˈlʌɡɪdʒ/","n.","〈总称〉 行李","They searched his luggage for illegal drugs.","他们搜查他的行李看是否藏有毒品。"],["drawback","/ˈdrɔbæk/","n.","缺点； 障碍","It’s a great city – the only drawback is the weather.","这是座很不错的城市，唯一的不足就是天气。"],["dynamic","/daɪˈnæmɪk/","adj.","有活力的； 动力的， 动力学的","dynamic and ambitious people","精力充沛且雄心勃勃的人"],["up","/ʌp/","adv/v.","从下往上地，向上地；提高；增加","We walked slowly up the hill.","我们慢慢地爬上山。"],["unusual","/ʌnˈjuʒəl/","adj.","不平常的， 异常的","an unusual feature","不寻常的特点"],["extreme","/ɪkˈstrim/","adj.","极端的， 偏激的","Extreme poverty still exists in many rural areas.","许多农村地区仍处于赤贫状态。"],["usual","/ˈjuʒuəl/","adj.","通常的， 平常的","Make a cheese sauce in the usual way.","按通常的做法做奶酪酱。"],["sink","/sɪŋk/","v/n.","下沉；消沉；陷入；洗涤槽， 污水槽","Their motorboat struck a rock and began to sink.","他们的摩托艇触了礁，开始下沉。"],["degree","/dɪˈɡri/","n.","程度； 度数； 文凭","Preheat the oven to 425 degrees.","把烘箱预热至425度。"],["astronomy","/əˈstrɑnəmi/","n.","天文学","The book treats of astronomy.","这本书是讲天文学的。"],["suppose","/səˈpoz/","vi/vt.","料想；猜想，假定","There were many more deaths than was first supposed.","死亡人数远远超过最初的预料。"],["brake","/brek/","v/n.","刹车；闸","He heard tyres squeal as the car braked to avoid a collision.","他听到当汽车刹车为避免撞车时轮胎发出了刺耳的尖声。"],["tube","/tub/","n.","管子","pasta tubes","通心粉"],["outspoken","/aʊtˈspokən/","adj.","坦率的","an outspoken critic of the education reforms","对教育改革直言不讳的批评者"],["especially","/ɪˈspɛʃlɪ/","adv.","特别， 尤其","I never liked long walks, especially in winter.","我向来不喜欢长距离散步，尤其在冬天。"],["once","/wʌns/","adv/conjunction.","一次，一回；一…便，一旦，一经","I’ve only met her once.","我只见过她一面。"],["failure","/ˈfeljɚ/","n.","失败","Successful people often aren’t very good at dealing with failure.","一帆风顺的人往往不太擅长应对失败。"],["quake","/kwek/","n&vi.","震动","The explosion made the whole house quake.","爆炸使整个房子都晃动起来。"],["know","/no/","v.","知道， 了解； 认识； 懂得","Who knows the answer?","谁知道答案？"],["sing","/sɪŋ/","v.","唱， 唱歌","She can sing beautifully.","她唱歌很好听。"],["organise","/ˈɔrgə/","v.","组织","Do they organise words around a principle of syntax?","他们会按照一定的句法规则组织单词吗？"],["support","/səˈpɔrt/","vt&n.","支持， 赞助； 赡养","The bill was supported by a large majority in the Senate.","这项法案得到参议院绝大多数人的支持。"],["drop","/drɑp/","v/n.","掉下，落下；滴； 下降","Your button has dropped off.","你的纽扣掉了。"],["preview","/ˈpriˈvjʊ/","vt.","预演， 预习","Journalists will be able to preview the exhibition tomorrow.","新闻记者明天将可以参观预展。"],["questionnaire","/ˌkwɛstʃənˈɛr/","n.","调查表， 问卷","Teachers will be asked to fill in a questionnaire.","教师们将被要求填写一份调查问卷。"],["saucer","/ˈsɔsɚ/","n.","茶碟； 小圆盘","Rae's coffee cup clattered against the saucer as she picked it up.","蕾把咖啡杯拿起来的时候杯子碰响了茶碟。"],["hire","/ˈhaɪɚ/","vt.","租用","The best way to explore the island is to hire a car.","在该岛寻幽访胜的最好方式就是租用一辆汽车。"],["breakthrough","/ˈbrekˈθrʊ/","n.","突破","The company looks poised to make a significant breakthrough in China.","该公司看上去稳将在中国实现一次重大突破。"],["idea","/aɪˈdiə/","n.","主意， 意见； 打算， 想法","You should talk to Ken – he's always full of good ideas.","你应该和肯谈谈，他总是满脑子好主意。"],["destination","/ˌdestɪˈneɪʃn/","n.","目的地","Ellis Island has become one of America's most popular tourist destinations.","埃利斯岛已经成为美国最受欢迎的游览地之一。"],["apron","/ˈeprən/","n.","围裙； 台口","She wiped her eyes with her apron.","她用她的围裙擦干了眼泪。"],["vertical","/ˈvɝtɪkl/","adj.","垂直的， 直立的； 纵向的","a vertical line","垂直线"],["monument","/ˈmɑnjumənt/","n.","纪念碑， 纪念物","He erected a monument on the spot where his daughter was killed.","他在女儿遇难的地方立了块纪念碑。"],["pure","/pjʊr/","adj.","纯的， 不掺杂的","rings made of pure gold","纯金制成的戒指"],["vivid","/ˈvɪvɪd/","adj.","生动的， 鲜明的","I’ve got vivid memories of that summer.","我对那年夏天记忆犹新。"],["damp","/dæmp/","adj/n/v.","潮湿的；潮湿；湿气；使潮湿","Wipe the leather with a damp cloth.","用湿布擦拭皮面。"],["throughout","/θrʊˈaʊt/","prep.","遍及， 贯穿","a large organization with offices throughout the world","在世界各地都设有办事处的一家大型机构"],["virtue","/ˈvɝtʃʊ/","n.","美德， 正直的品行","Women have often been used as symbols of virtue.","女性常被用作美德的象征。"],["overweight","/ˈovəˈwet/","adj.","过重的， 超重的","He is slightly overweight.","他略微超重。"],["gay","/ɡe/","adj/n.","快活的，愉快的；同性恋","She felt excited and quite gay.","她感到兴奋而快活。"],["successful","/səkˈsɛsfl/","adj.","成功的， 有成就的","The operation was successful.","手术成功了。"],["lovely","/ˈlʌvli/","adj.","美好的， 可爱的","She had a lovely face.","她有一张漂亮的脸蛋。"],["normal","/ˈnɔrml/","adj/n.","正常的；正常， 常态， 普通","A normal working week is 40 hours.","一个正常的工作周是40小时。"],["gradual","/ˈɡrædʒuəl/","adj.","逐渐的， 渐进的","There has been a gradual change in climate.","气候渐渐发生了变化。"],["figure","/ˈfɪɡjɚ/","v/n.","认为；  描绘；数字；人物","How do you figure he can live without me?","你怎么会认为他没有了我还能活？"],["socialist","/ˈsoʃəlɪst/","adj/n.","社会主义的；社会主义者","socialist principles","社会主义原则"],["airmail","/ˈɛrmel/","n.","〈总称〉航空邮件","Send the letter by airmail.","这封信用航空邮寄。"],["slight","/slaɪt/","adj.","轻微的， 细小的","a slight improvement","些许的改进"],["corrupt","/kəˈrʌpt/","adj/v.","腐败的，贪污的；腐烂， 腐蚀","Corrupt judges have taken millions of dollars in bribes.","腐败的法官接受了几百万美元的贿赂。"],["wide","/waɪd/","adj.","宽的， 宽阔的； 广泛的","a man with a wide experience of foreign affairs","外交事务经验丰富的人"],["previous","/ˈprivɪəs/","adj.","在前的， 早先的","She has a teenage daughter from a previous marriage.","她有个出自前一次婚姻的十几岁的女儿。"],["teach","/titʃ/","v.","教书； 教","She taught me fractions and counting.","他教我分数和计算。"],["socialism","/ˈsoʃəlɪzəm/","n.","社会主义","From then on we proceeded to build socialism.","从那时起，我们开始建设社会主义。"],["argue","/ˈɑrgjʊ/","v.","争论； 说服","We could hear the neighbours arguing.","我们听到邻居在争吵。"],["technology","/tɛkˈnɑlədʒɪ/","n.","技术， 科技","Modern technology makes moving money around much easier than it used to be.","现代科技使货币流动比以前便捷得多。"],["superior","/sʊˈpɪrɪɚ/","adj/n.","较高的， 上好的；长者；上级","Fletcher’s superior technique brought him victory.","弗莱彻更胜一筹的技术使他取得了胜利。"],["succeed","/səkˈsid/","vi/vt.","成功；继承， 接替","She wanted to be the first woman to climb Mount Qomolangma, and she almost succeeded.","她本想成为第一位登上珠穆朗玛峰的女性，而且差一点就成功了。"],["choir","/ˈkwaɪɚ/","n.","唱诗班","He joined a church choir at the age of eight.","他八岁时加入了一个教堂唱诗班。"],["punctual","/ˈpʌŋtʃʊəl/","adj.","准时的","She’s always very punctual for appointments.","她一向准时赴约。"],["advertise","/ˈædvɚtaɪz/","vt.","为…做广告","They no longer advertise alcohol or cigarettes at sporting events.","他们不再在体育赛事上做烟酒广告了。"],["compromise","/ˈkɑmprəmaɪz/","v.","妥协， 折中","She admitted that she was unable to compromise.","她承认自己无法作出妥协。"],["software","/ˈsɔftwɛr/","n.","软件","She loaded the new software .","她给电脑装上新的软件。"],["seminar","/ˈsɛmɪnɑr/","n.","研究会， 讨论发表会","a Shakespeare seminar","莎士比亚研讨班"],["reach","/ritʃ/","v.","到达；  够到","Chelsea could reach the final of the European Cup.","切尔西队会进入欧洲杯决赛。"],["react","/riˈækt/","vi.","起反应， 起作用； 反抗","He reacted angrily to the suggestion that he had lied.","说他撒谎，他非常生气。"],["competition","/ˌkɒmpəˈtɪʃn/","n.","比赛， 竞赛","Going to trade fairs is an ideal opportunity to size up the competition .","参加商品交易会是估量竞争规模的理想机会。"],["none","/nʌn/","pron.","无任何东西或人","",""],["type","/taɪp/","vt.","打字， 用打字机打出","He types with two fingers.","他用两个手指打字。"],["beyond","/bɪˈjɑnd/","prep.","超过；  在…的那边","They crossed the mountains and headed for the valleys beyond.","他们翻过山，向更远处的山谷进发。"],["practise","/ˈpræktɪs/","v.","练习； 实习； 经常做； 养成…的习惯","They moved the furniture back to practise their dance routine.","他们把家具往后挪以便练习舞蹈动作。"],["review","/rɪˈvju/","vt/n.","复习；重新调查；复习； 复查； 评论","The journal receives review copies(=  free copies to review ) of most new software products.","这家杂志会收到大多数新软件产品的赠样以作评论之用。"],["sight","/saɪt/","n.","情景， 风景； 视力","Anne’s sight is very good for someone of her age.","安妮的视力对于她这个年龄的人来说算是非常好的。"],["voluntary","/ˈvɑləntɛri/","adj.","自愿的","Workers are being encouraged to take voluntary redundancy.","工人被鼓励主动离职。"],["asleep","/əˈslip/","adj.","睡着的， 熟睡的","Quiet! The baby’s asleep.","安静！ 宝宝在睡觉。"],["nobody","/ˈnəubədi/","pron/n.","没有人，谁也不；小人物","I knocked on the door but nobody answered.","我敲了敲门，但没人应门。"],["guide","/ɡaɪd/","v/n.","指导； 指引；向导，导游","Teenagers need adults to guide them.","十几岁的青少年需要大人来引导。"],["between","/bəˈtwin/","prep.","在之间； 在…中间","",""],["surrounding","/səˈraʊndɪŋ/","adj/n.","周围的；围绕；","Troops sealed off the surrounding area .","军队封锁了周围地区。"],["goal","/ɡol/","n.","目标； 进球得分；  球门","Your goal as a parent is to help your child become an independent adult.","身为父母，你的目标就是要培养孩子成为独立的成年人。"],["collar","/ˈkɑlɚ/","n.","衣领","He grabbed me by the collar.","他抓住我的衣领。"],["natural","/ˈnætʃrəl/","adj.","自然的， 天然的； 天生的","the study of the natural world","对自然界的研究"],["overhead","/ˌəuvəˈhed/","adj&adv.","在高处， 在空中","Bullets whizzed overhead.","子弹嗖嗖地掠过头顶。"],["conclude","/kənˈklud/","v.","推论； 断定； 完成； 结束","When the investigation is concluded, the results will be sent to the US Attorney’s office.","等到调查结束后，结果会被送到联邦检察官办公室。"],["come","/kʌm/","vi/v.","来，来到；变成","Let me know when they come.","他们来了就告诉我。"],["comprehension","/ˌkɒmprɪˈhenʃn/","n.","理解","",""],["leather","/ˈlɛðɚ/","n.","皮革","The inside of the bag was lined with soft leather.","这包的里面衬了软皮。"],["comb","/kom/","v/n.","梳；梳子","Melanie ran upstairs to comb her hair .","梅拉妮跑上楼去梳头发。"],["exist","/ɪɡˈzɪst/","vi.","存在， 生存","The custom of arranged marriages still exists in many countries.","许多国家仍存在包办婚姻的习俗。"],["unemployment","/ˌʌnɪmˈplɔɪmənt/","n.","失业","a town where there is high unemployment","高失业率城镇"],["exact","/ɪɡˈzækt/","adj.","精确的， 准确的， 确切的","Police are still investigating the exact cause of the accident.","警方还在调查这起事故的确切原因。"],["lift","/lɪft/","vi.","升起，  消散","He heard a scream and the hairs on the back of his neck began to lift.","他听到一声尖叫，吓得脖子后面寒毛直竖。"],["motto","/ˈmɑto/","n.","箴言， 格言","‘Be prepared’ is the motto of the Boy Scouts.","“时刻准备着”是童子军的格言。"],["nationwide","/ˌneɪʃnˈwaɪd/","adj.","全国性的","a nationwide search for a missing British tourist","在全国范围内对一名失踪英国游客的搜寻"],["force","/fɔrs/","vt/n.","强迫，迫使；力量， 武力","Due to the high cost of borrowing, many companies have been forced to close.","由于借贷成本高，许多公司被迫关门。"],["centigrade","/ˈsɛntɪɡred/","adj.","摄氏的； 百分度的","...daytime temperatures of up to forty degrees centigrade.","…高达40摄氏度的日间气温。"],["botany","/ˈbɑtəni/","n.","植物学； 植物","He studied botany at university.","他在大学学习植物学。"],["wear","/wɛr/","v.","穿， 戴； 留， 蓄； 磨损， 使变旧","The cushions are starting to wear a little.","这些靠垫开始有点磨破了。"],["range","/rendʒ/","n.","范围； 射程","a temperature range of 72-85˚","72 度到85度之间的温度范围"],["weak","/wik/","adj.","虚弱的； 差的","The illness left her feeling weak.","疾病使她感到身体虚弱。"],["leak","/lik/","v.","漏， 泄漏","The roof is leaking.","屋顶在漏水。"],["impress","/ɪmˈprɛs/","vt.","留下印象","Steve borrowed his dad’s sports car to impress his girlfriend.","史蒂夫借来他爸爸的跑车向女友炫耀。"],["flat","/flæt/","adj/n.","平的；一套房间； 公寓","houses with flat roofs","平顶房"],["get","/ɡɛt/","v/vt.","变得； 到达；得到，获得","We need to get help quickly!","我们需要马上得到帮助！"],["course","/kɔrs/","n.","过程， 经过； 课程","",""],["barber","/ˈbɑrbɚ/","n.","理发师","My father marched me over to Otto, the local barber, to have my hair cut short.","爸爸把我拽到当地理发师奥托跟前，让他把我的头发剪短。"],["copy","/ˈkɑpi/","v/n.","复制； 抄写； 复印；抄本，副本；一本","Could you copy this letter and send it out, please?","你能把这封信复印一份发出去吗？"],["precise","/prɪˈsaɪs/","adj.","精确的， 准确的","precise sales figures","准确的销售数据"],["power","/ˈpaʊɚ/","n.","力量； 动力","the pulling power (= ability to attract people or attention ) of major celebrities","大名人的吸引力"],["place","/ples/","n/vt.","地方，处所；放置， 安置","Make sure you keep the key in a safe place.","一定要把钥匙放在安全的地方。"],["dare","/dɛr/","v.","敢， 敢于","He wanted to ask her, but he didn’t dare.","他想问她，但又不敢。"],["regular","/ˈrɛgjəlɚ/","adj.","规则的； 经常的","The company holds regular meetings with employees.","公司定期召集雇员开会。"],["precious","/ˈprɛʃəs/","adj.","宝贵的， 珍贵的","planes delivering precious supplies of medicine and food","运送药品、食品等宝贵物资的飞机"],["sell","/sɛl/","v.","卖， 售","If you offer him another hundred, I think he’ll sell.","如果你再加一百元钱，我想他会卖的。"],["tired","/ˈtaɪrd/","adj.","疲劳的， 累的； 厌烦的","He looks tired out (= very tired ) .","他看起来累坏了。"],["tremble","/ˈtrɛmbl/","v.","颤抖， 挥动","His lip started to tremble and then he started to cry.","他的嘴唇开始颤抖，接着就哭了起来。"],["gymnastics","/dʒɪmˈnæstɪks/","n.","体操， 体育","a gymnastics display","体操表演"],["suspect","/sʌspɛkt/","v/n.","怀疑；犯罪嫌疑人","She strongly suspected he was lying to her.","她非常怀疑他在对她撒谎。"],["suggest","/səˈdʒɛst/","vt.","建议； 提出； 暗示","The zoo asked its visitors to suggest a name for the new baby panda.","动物园请游客提建议，给刚出生的大熊猫起一个名字。"],["apologize","/əˈpɑlədʒaɪz/","vi.","道歉， 谢罪","I’m so sorry, I do apologize.","非常对不起，我真心道歉。"],["expect","/ɪkˈspɛkt/","v.","预料； 期望； 要求","He will be hard to beat. I fully expect (= am completely sure about ) that and I’m ready.","他很难击败。我确信这一点，不过我准备好了。"],["help","/hɛlp/","n&v.","帮助， 帮忙； 有帮助， 有用","If there’s anything I can do to help, just give me a call.","如果需要我帮忙，就给我打个电话。"],["depth","/dɛpθ/","n.","深， 深度","Astronomers may one day travel to the depths of space.","天文学家也许有一天可以到太空深处去。"],["assess","/əˈsɛs/","vt.","估定， 评定","The test was to assess aptitude rather than academic achievement.","该测试将评估能力而不是学业成绩。"],["prescription","/prɪˈskrɪpʃən/","n.","处方， 药方","We are trying to cut the price of prescription drugs .","我们正努力降低处方药的价格。"],["behaviour","/bɪˈhevjər/","n.","[U] 行为， 举止","It is important to reward good behaviour.","表现好要给予奖励，这是很重要的。"],["chorus","/ˈkɔrəs/","n.","合唱","I sing with the university chorus.","我在大学合唱队里唱歌。"],["minimum","/ˈmɪnɪməm/","adj/n.","最小的；最小量，最小值","The minimum number of students we need to run the course is fifteen.","我们开这门课程最少要有15个学生。"],["queue","/kju/","vi/n.","排队；行列， 长队","File not in print queue.","文件不在打印队列中。"],["apology","/əˈpɑlədʒi/","n.","道歉； 歉意","Edward can’t be here today, but he sends his apologies .","爱德华今天来不了，他向大家表示歉意。"],["date","/det/","n/vt.","日期；约会；约会； 注明日期","The date on the letter was 30th August 1962.","信上的日期是1962年8月30日。"],["magic","/ˈmædʒɪk/","adj/n.","有魔力的；魔法，魔术","a book of magic spells","一本关于魔法的书"],["dress","/drɛs/","v/n.","穿衣，打扮；女服， 连衣裙； 服装","Can you wait a minute? I’m just getting dressed .","稍等一会儿，我穿下衣服就好。"],["argument","/ˈɑrɡjumənt/","n.","[C] 争论， 辩论","We need to provide a convincing argument as to why the system should be changed.","我们得提出有说服力的论据，证明为何要改变体制。"],["passage","/ˈpæsɪdʒ/","n.","一节； 走廊； 通道","My office is just along the passage.","我的办公室就在过道旁边。"],["theoretical","/ˌθɪəˈretɪkl/","adj.","理论的","theoretical physics","理论物理"],["adequate","/ˈædɪkwət/","adj.","足够的， 适当的","Farmers have been slow to make adequate provision for their retirement.","农民们迟迟没有为退休做好适当安排。"],["sound","/saʊnd/","n/v/adj.","声，声音；听起来；看起来；好像；明智的；合理的；正确的","There were strange sounds coming from the next room.","隔壁房间传来奇怪的声音。"],["own","/on/","adj/vt.","自己的；拥有","Bring your own equipment.","带上你自己的装备。"],["hopeful","/ˈhopfl/","adj.","有希望的； 有前途的","The vote is a hopeful sign that attitudes in the church are changing.","投票结果是个好兆头，表明教会的态度正在转变。"],["dozen","/ˈdʌzn/","n.","十二个； 许多","We collected dozens and dozens of shells on the beach.","我们在海滩上捡了很多很多贝壳。"],["translate","/trænsˈlet/","v.","翻译","Poetry doesn’t usually translate well.","诗歌通常都译不好。"],["drug","/drʌg/","n.","药， 药物； 毒品","A lot of young people start taking drugs at school.","许多年轻人上学时开始吸毒。"],["barrier","/ˈbærɪɚ/","n.","栅栏， 挡板； 障碍","He advocated the removal of trade barriers.","他提倡消除贸易壁垒。"],["plain","/plen/","adj/n.","平常的，普通的；明白的；草原","The advantages were plain to see.","优势显而易见。"],["should","/ʃəd/","modal verb.","应当，应该 〔用于提供或征求建议〕","What should I do? Should I trust him?","我该怎么办？我应该相信他吗？"],["only","/onlɪ/","adv/adj.","只， 仅仅；唯一的，仅有的","Naomi was only 17 when she got married.","娜奥米结婚时才17岁。"],["create","/krɪˈet/","vt.","创造； 造成","Some people believe the universe was created by a big explosion.","有些人认为宇宙是通过一次大爆炸创造出来的。"],["justice","/ˈdʒʌstɪs/","n.","正义， 公正； 司法","No one doubts the justice of our cause.","没有人怀疑我们的事业是正义的。"],["criminal","/ˈkrɪmɪnl/","n.","罪犯","Police have described the man as a violent and dangerous criminal.","警方形容那名男子是个凶暴而危险的罪犯。"],["blow","/blo/","v/n.","吹  ； 刮风；击，打击","A cold breeze was blowing hard .","寒风劲吹。"],["curious","/ˈkjʊrɪəs/","adj.","好奇的； 奇异的","Puppies are naturally curious.","小狗天生好奇。"],["proud","/praʊd/","adj.","自豪的， 骄傲的","Seth was the proud owner of a new sports car.","赛思因为有了新跑车而扬扬得意。"],["like","/laɪk/","v/prep/n.","喜欢， 喜爱；像，跟…一样；爱好","I like your jacket.","我喜欢你这件上衣。"],["ugly","/ˈʌɡli/","adj.","丑陋的， 难看的","a very ugly man","非常丑陋的男子"],["earthquake","/ˈɝθˈkwek/","n.","地震","An earthquake measuring 6.1 on the Richter scale struck southern California on June 28.","6月28日加州南部地区发生了里氏6.1级地震。"],["tax","/tæks/","n.","税， 税款","No-one enjoys paying tax.","没人喜欢缴税。"],["towards","/tɔrdz/","prep.","向， 朝， 对于","He noticed two policemen coming towards him.","他注意到两名警察正朝他走来。"],["messy","/ˈmɛsi/","adj.","乱七八糟的","Don't worry if this first coat of paint looks messy.","如果这第一层油漆看上去有点脏的话，不用担心。"],["embassy","/ˈɛmbəsi/","n.","大使馆","the American Embassy in Paris","美国驻巴黎大使馆"],["rectangle","/ˈrɛktæŋɡl/","adj/n.","长方形的；长方形","Yes, it is like a rectangle.","是的，它象一个长方形。"],["fragile","/ˈfrædʒəl/","adj.","易碎的， 脆的","Be careful with that vase – it’s very fragile.","小心那只花瓶——很容易打碎的。"],["departure","/dɪˈpɑrtʃɚ/","n.","离开； 背离； 违反","...the president's departure for Helsinki.","…总统前往赫尔辛基。"],["dash","/dæʃ/","v/n.","快跑，猛撞；快跑， 猛撞； 少量","Suddenly she dashed down to the cellar.","她猛地朝地窖冲过去。"],["send","/sɛnd/","vt.","打发， 派遣； 送， 邮寄","Lyn sent some pictures of the wedding.","琳恩寄了几张婚礼照片。"],["concrete","/ˈkɑŋkrit/","adj.","具体的； 有形的","What does that mean in concrete terms ?","具体来说那到底是什么意思？"],["note","/not/","n/vt.","便条，笔记，注释；记录， 注意","Can I borrow your lecture notes?","我能不能借用一下你的课堂笔记？"],["everybody","/ˈɛvrɪbɑdi/","pron.","每人， 人人","We like everybody to say what they think.","我们喜欢让人人都说出他们的看法。"],["sail","/sel/","v/n.","航行，开航；帆； 航行","Three tall ships sailed past.","三艘大船驶了过去。"],["cab","/kæb/","n.","出租车； 驾驶室","New York’s yellow cabs","纽约的黄色出租车"],["purpose","/ˈpɝpəs/","n.","目的， 意图","Nick had no particular purpose in mind when he started.","尼克开始的时候头脑中并没有明确的目标。"],["regret","/rɪˈɡrɛt/","n/vt.","遗憾，懊悔；令人遗憾的事；遗憾； 后悔","It is with great regret that I must decline your offer.","很遗憾，我不得不谢绝你的好意。"],["line","/laɪn/","v/n.","画线于，  成行；直线；排","Crowds lined the route to the palace.","人群夹道站在通往王宫的路上。"],["stout","/staʊt/","adj.","结实的， 矮胖的","a stout pair of shoes","一双厚实耐穿的鞋子"],["link","/lɪŋk/","v/n.","连接，联合；链环， 链接","He walked with her, linking arms (= putting his arm around her arm ).","他与她挽臂同行。"],["flee","/fli/","v.","逃走， 逃跑","His attackers turned and fled.","袭击他的人转身逃走了。"],["weep","/wip/","v.","哭泣， 流泪","James broke down and wept.","詹姆斯控制不住感情，哭了起来。"],["tune","/tun/","n.","曲调， 调子","That’s a nice tune.","那曲调很美。"],["aware","/əˈwɛr/","adj.","知道的， 意识到的","Mr Braley has been made aware of the need for absolute secrecy.","布雷利先生被告知需要绝对保密。"],["can","/kæn/","n.","罐头； 铁罐； 垃圾桶","Two large cans of paint ought to be enough.","两大桶油漆应该够了。"],["security","/səˈkjʊrəti/","n.","安全","The trial was held under tight security .","这场审讯是在戒备森严的情况下进行的。"],["award","/əˈwɔrd/","n.","奖品， 奖励","The movie has won a number of awards.","该片获得了多个奖项。"],["ready","/ˈrɛdi/","adj.","准备就绪的","Come on. Aren’t you ready yet?","快点，你还没准备好吗？"],["alarm","/əˈlɑrm/","n.","警报","I forgot to set the burglar alarm.","我忘记打开防盗警报器了。"],["weed","/wid/","n.","野草， 杂草","the constant battle against weeds","对付杂草的长期斗争"],["herb","/ɝb/","n.","草药","Sprinkle the dish with chopped fresh herbs.","在菜肴上撒些切碎的新鲜香草。"],["unconscious","/ʌnˈkɑnʃəs/","adj.","不省人事的， 无意识的","She was found alive but unconscious.","她被找到时还活着，但已不省人事。"],["rainfall","/ˈrenˈfɔl/","n.","一场雨； 降雨量","We’ve had a long period of low rainfall.","我们已有很长一段时间雨量偏低。"],["cost","/kɔst/","n/vt.","成本；代价；花费； 使付出","I offered to pay the cost of the taxi.","我提出支付出租车费。"],["will","/wɪl/","n.","意志； 遗嘱","Children sometimes have strong wills.","小孩子有时有很强的意志力。"],["satisfy","/ˈsætɪsfaɪ/","v.","满足， 使满意","Nothing I did would ever satisfy my father.","我做什么都不能让父亲满意。"],["smoke","/smok/","v/n.","冒烟； 吸烟；烟","I don’t smoke and I don’t drink much.","我不吸烟，酒也喝得不多。"],["match","/mætʃ/","v/n.","相配，相称；比赛； 火柴","We painted the cabinets green to match the rug.","我们把柜子刷成绿色，和地毯相配。"],["arbitrary","/ˈɑːrbətreri/","adj.","武断的； 任意的","an arbitrary decision","武断的决定"],["cuisine","/kwɪˈzin/","n.","烹饪， 烹饪术","French cuisine","法式烹饪"],["fault","/fɔlt/","n.","过错， 缺点， 毛病","I’m really sorry - it’s all my fault.","我真的很抱歉——都是我的错。"],["follow","/ˈfɑlo/","v.","跟随； 遵循； 仿效","Are those men following us?","那些人在跟着我们吗？"],["passive","/ˈpæsɪv/","adj.","被动的； 消极的","Kathy seems to take a very passive role in the relationship.","凯茜在这一关系中似乎扮演着十分被动的角色。"],["hard-working","/ˌhɑːdˈwɜːkɪŋ/","adj.","勤劳的， 辛勤工作的","a hard-working teacher","努力工作的老师"],["carrier","/ˈkærɪɚ/","n.","搬运者；  置物架","a baby carrier","婴儿背带"],["dignity","/ˈdɪɡnəti/","n.","尊严； 高贵","an appearance of quiet dignity","肃穆的神态"],["challenge","/ˈtʃælɪndʒ/","n/vt.","挑战；挑战性；挑战","They threw down the challenge that he couldn’t wash 40 cars in one hour (= invited him to try to do it ) .","他们激将他，说他不可能在1小时内擦洗40辆汽车。"],["category","/ˈkætəɡɔri/","n.","种类","people in the over-45 age category","属45岁以上年龄组的人"],["cosy","/ˈkozi/","adj.","暖和舒服的； 舒适的","The living room was warm and cosy .","客厅暖和又舒适。"],["intend","/ɪnˈtɛnd/","v.","想要， 打算","Maybe he intends to leave her.","也许他打算离开她。"],["wild","/waɪld/","adj.","野生的","{\"COLLOINEXA\":[\"wild animals\"]}","野生动物"]];